INSERT INTO is_learn_sections (id, category_id, title, description, sort_order) SELECT '3453004d-bf3a-5083-9293-131b518c7bdc', c.id, '{"en": "Learn to pray, step by step", "bn": "নামাজ শিখি: ধাপে ধাপে"}', '{"en": "Wudu and ghusl, every position of the prayer and what is said in it, and the janazah.", "bn": "অজু ও গোসল, নামাজের প্রতিটি অবস্থা ও তাতে কী পড়া হয়, এবং জানাযা।"}', 10 FROM is_learn_categories c WHERE c.id = '81169494-3732-54c5-b38e-ea84f000e4a2' ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('75433196-8781-551c-b2f5-17e1e7ef264a', '{"en": "Learn wudu & ghusl", "bn": "অজু ও গোসল শিখি"}', '{"en": "The steps of wudu, what breaks it, ghusl and tayammum.", "bn": "অজুর ধাপ, যা অজু ভাঙে, গোসল ও তায়াম্মুম।"}', NULL, 'droplets', 'in_review', 1, (SELECT s.id FROM is_learn_sections s WHERE s.id = '3453004d-bf3a-5083-9293-131b518c7bdc')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('c55a6370-e397-57df-be51-c14c9ec3a220', '75433196-8781-551c-b2f5-17e1e7ef264a', '{"en": "The steps of wudu", "bn": "অজুর ধাপগুলো"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('77dbc336-e14f-5fa1-a01f-3da6759adb69', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'order', '{"en": "Put the steps of wudu in order", "bn": "অজুর ধাপগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Say Bismillah", "bn": "বিসমিল্লাহ বলা"}, {"en": "Wash both hands", "bn": "দুই হাত কব্জি পর্যন্ত ধোয়া"}, {"en": "Rinse the mouth", "bn": "কুলি করা"}, {"en": "Rinse the nose", "bn": "নাকে পানি দেওয়া"}, {"en": "Wash the face", "bn": "মুখমণ্ডল ধোয়া"}, {"en": "Wash the arms to the elbows", "bn": "কনুইসহ হাত ধোয়া"}, {"en": "Wipe the head (and ears)", "bn": "মাথা (ও কান) মাসেহ করা"}, {"en": "Wash the feet to the ankles", "bn": "টাখনুসহ পা ধোয়া"}], "rtl": false}', '{"en": "The Prophet’s ﷺ wudu as ‘Uthman (RA) showed it; the Quran names face, arms, head and feet in this order.", "bn": "উসমান (রা.) যেভাবে নবীজির ﷺ অজু দেখিয়েছেন; কুরআনেও মুখ, হাত, মাথা ও পা এই ক্রমে এসেছে।"}', 'Quran 5:6; Sahih al-Bukhari 159', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7d498b8-c57d-5044-bcda-08d43381b220', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'fill', '{"en": "Complete the step", "bn": "ধাপটি পূর্ণ করুন"}', '{"options": [{"en": "elbows", "bn": "কনুই"}, {"en": "wrists", "bn": "কব্জি"}, {"en": "shoulders", "bn": "কাঁধ"}, {"en": "fingertips", "bn": "আঙুলের ডগা"}], "correct": 0, "rtl": false, "before": {"en": "Wash the arms up to and including the", "bn": "হাত ধুতে হবে"}, "after": {"en": "", "bn": "পর্যন্ত (সহ)"}}', '{"en": "\"…and your arms to the elbows.\"", "bn": "\"…এবং কনুই পর্যন্ত তোমাদের হাত।\""}', 'Quran 5:6', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8a1de3df-1759-50b5-af24-2c71c740e494', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'match', '{"en": "How is each part done?", "bn": "কোন অঙ্গে কী করা হয়?"}', '{"pairs": [{"left": {"en": "Face", "bn": "মুখমণ্ডল"}, "right": {"en": "Wash it", "bn": "ধোয়া"}}, {"left": {"en": "Head", "bn": "মাথা"}, "right": {"en": "Wipe it with wet hands", "bn": "ভেজা হাতে মাসেহ"}}, {"left": {"en": "Arms", "bn": "হাত"}, "right": {"en": "Wash to the elbows", "bn": "কনুই পর্যন্ত ধোয়া"}}, {"left": {"en": "Feet", "bn": "পা"}, "right": {"en": "Wash to the ankles", "bn": "টাখনু পর্যন্ত ধোয়া"}}]}', '{"en": "Wash the face, arms and feet; wipe the head.", "bn": "মুখ, হাত ও পা ধোয়া; মাথা মাসেহ।"}', 'Quran 5:6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ec0cfdf0-d655-5ef6-89c7-d788428fa1bb', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'true_false', '{"en": "The Prophet ﷺ liked to begin with the right side.", "bn": "নবী ﷺ ডান দিক থেকে শুরু করা পছন্দ করতেন।"}', '{"answer": true}', '{"en": "‘A’ishah (RA): he liked to start with the right in putting on shoes, combing and in his purification.", "bn": "আয়েশা (রা.): জুতা পরা, চুল আঁচড়ানো ও পবিত্রতা অর্জনে তিনি ডান দিক থেকে শুরু করা পছন্দ করতেন।"}', 'Sahih al-Bukhari 168', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('09d45fdc-c7e3-5de9-91b1-6fbbf2b0ae2b', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'true_false', '{"en": "Washing each limb more than three times is the Sunnah.", "bn": "প্রতিটি অঙ্গ তিনবারের বেশি ধোয়া সুন্নাত।"}', '{"answer": false}', '{"en": "He ﷺ washed up to three times and said whoever adds to this has done wrong.", "bn": "নবী ﷺ সর্বোচ্চ তিনবার ধুয়েছেন এবং বলেছেন, এর বেশি যে করে সে ভুল করল।"}', 'Sunan Abi Dawud 135', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e9a7a306-3b26-5c09-bf3d-97d8fb26f338', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'true_false', '{"en": "One wudu can be used for several prayers, as long as it is not broken.", "bn": "অজু না ভাঙলে এক অজুতে একাধিক নামাজ পড়া যায়।"}', '{"answer": true}', '{"en": "On the day of the conquest of Makkah he ﷺ prayed several prayers with one wudu.", "bn": "মক্কা বিজয়ের দিন নবী ﷺ এক অজুতে কয়েক ওয়াক্ত নামাজ পড়েছেন।"}', 'Sahih Muslim 277', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('010a0ff7-a963-5185-a071-68c5d160e821', 'c55a6370-e397-57df-be51-c14c9ec3a220', 'choice', '{"en": "What did the Prophet ﷺ teach us to say after wudu?", "bn": "অজুর পর নবী ﷺ কী পড়তে শিখিয়েছেন?"}', '{"options": [{"en": "Ashhadu an la ilaha illallah… wa ashhadu anna Muhammadan ‘abduhu wa rasuluh", "bn": "আশহাদু আল্লা ইলাহা ইল্লাল্লাহু… ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ"}, {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "As-salamu ‘alaykum", "bn": "আসসালামু আলাইকুম"}, {"en": "Rabbana atina", "bn": "রাব্বানা আতিনা"}], "correct": 0}', '{"en": "Whoever says the shahadah after a complete wudu, the eight gates of Paradise are opened for him.", "bn": "পূর্ণ অজুর পর যে শাহাদাত পড়ে, তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়।"}', 'Sahih Muslim 234', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('e18367d5-53da-5dcc-86e2-e835dbef0b5a', '75433196-8781-551c-b2f5-17e1e7ef264a', '{"en": "What breaks wudu", "bn": "যা অজু ভাঙে"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('03822809-f95c-57a7-bfac-3332306155e4', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'true_false', '{"en": "Passing wind breaks wudu.", "bn": "বায়ু বের হলে অজু ভেঙে যায়।"}', '{"answer": true}', '{"en": "\"Allah does not accept the prayer of one who has broken his wudu until he does wudu.\" Abu Hurayrah explained: passing wind.", "bn": "\"অজু ভেঙে গেলে অজু না করা পর্যন্ত আল্লাহ নামাজ কবুল করেন না।\" আবু হুরায়রা (রা.) ব্যাখ্যা করেন: বায়ু বের হওয়া।"}', 'Sahih al-Bukhari 135', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d78b452b-3b68-5a8a-8245-00f2f0e2a343', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'choice', '{"en": "Which of these breaks wudu?", "bn": "নিচের কোনটি অজু ভাঙে?"}', '{"options": [{"en": "Smiling", "bn": "মুচকি হাসি"}, {"en": "Drinking water", "bn": "পানি পান করা"}, {"en": "Urinating", "bn": "পেশাব করা"}, {"en": "Saying salam", "bn": "সালাম দেওয়া"}], "correct": 2}', '{"en": "Whatever comes out from the toilet passages (urine, stool, wind) breaks wudu.", "bn": "পেশাব-পায়খানার রাস্তা দিয়ে যা বের হয় (পেশাব, পায়খানা, বায়ু) তাতে অজু ভাঙে।"}', 'Quran 5:6', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('770908fa-7bf7-5176-b77f-3f6f010f152e', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'true_false', '{"en": "Eating bread or rice breaks wudu.", "bn": "রুটি বা ভাত খেলে অজু ভেঙে যায়।"}', '{"answer": false}', '{"en": "Ordinary food does not break wudu; he ﷺ ate and prayed without a new wudu.", "bn": "সাধারণ খাবারে অজু ভাঙে না; নবী ﷺ খেয়ে নতুন অজু ছাড়াই নামাজ পড়েছেন।"}', 'Sahih al-Bukhari 207', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d01e9607-25ca-5b81-9bac-bf40e88f1b20', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'true_false', '{"en": "Deep sleep lying down breaks wudu.", "bn": "শুয়ে গভীর ঘুমালে অজু ভেঙে যায়।"}', '{"answer": true}', '{"en": "In deep sleep one cannot know if wudu was broken, so a new wudu is needed — all the schools agree on this case.", "bn": "গভীর ঘুমে অজু ভাঙল কি না টের পাওয়া যায় না, তাই নতুন অজু লাগে — এ ক্ষেত্রে সব মাজহাব একমত।"}', 'Sunan Abi Dawud 203', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fbdc53d8-acd0-5e40-a9c3-221024197b9f', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'true_false', '{"en": "Fainting (losing consciousness) breaks wudu.", "bn": "অজ্ঞান হলে অজু ভেঙে যায়।"}', '{"answer": true}', '{"en": "Scholars agree that losing consciousness breaks wudu, even more than sleep.", "bn": "আলেমগণ একমত, অজ্ঞান হওয়া ঘুমের চেয়েও বেশি করে অজু ভাঙে।"}', 'Ijma‘ (scholarly agreement)', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c3758f8e-c92f-5560-9958-7c5025749d14', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'true_false', '{"en": "A man who feels something in his stomach during salah was told not to leave the prayer unless he hears a sound or finds a smell.", "bn": "নামাজে পেটে কিছু অনুভব করা ব্যক্তিকে বলা হয়েছে: শব্দ না শুনলে বা গন্ধ না পেলে নামাজ ছেড়ে যাবে না।"}', '{"answer": true}', '{"en": "Mere doubt does not cancel a certain wudu inside the prayer.", "bn": "নিছক সন্দেহে নামাজের মধ্যে নিশ্চিত অজু বাতিল হয় না।"}', 'Sahih al-Bukhari 137; Sahih Muslim 362', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3af2f185-908d-5ba5-a071-8c4febf909ef', 'e18367d5-53da-5dcc-86e2-e835dbef0b5a', 'choice', '{"en": "After janabah (major impurity), what is needed before salah?", "bn": "জানাবাতের (বড় নাপাকির) পর নামাজের আগে কী লাগবে?"}', '{"options": [{"en": "Only wudu", "bn": "শুধু অজু"}, {"en": "Ghusl (a full bath)", "bn": "গোসল"}, {"en": "Nothing", "bn": "কিছু না"}, {"en": "Only washing the hands", "bn": "শুধু হাত ধোয়া"}], "correct": 1}', '{"en": "\"If you are in a state of janabah, then purify yourselves.\"", "bn": "\"যদি তোমরা জানাবাত অবস্থায় থাকো, তবে ভালোভাবে পবিত্র হও।\""}', 'Quran 5:6', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('4361bf70-e649-5c2e-9ee4-d8254dc440fe', '75433196-8781-551c-b2f5-17e1e7ef264a', '{"en": "Ghusl & tayammum", "bn": "গোসল ও তায়াম্মুম"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('71830047-636e-5d68-aad9-6131d642bde4', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'choice', '{"en": "Which of these makes ghusl obligatory?", "bn": "নিচের কোনটির পর গোসল ফরজ?"}', '{"options": [{"en": "Eating", "bn": "খাওয়া"}, {"en": "Cutting hair", "bn": "চুল কাটা"}, {"en": "The end of menstruation", "bn": "ঋতুস্রাব শেষ হওয়া"}, {"en": "A short nap", "bn": "অল্প তন্দ্রা"}], "correct": 2}', '{"en": "\"…do not approach them until they are pure; when they have purified themselves…\"", "bn": "\"…পবিত্র না হওয়া পর্যন্ত তাদের কাছে যেয়ো না; যখন তারা ভালোভাবে পবিত্র হয়…\""}', 'Quran 2:222; Sahih al-Bukhari 228', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b4d31254-2ad9-5200-8a90-2a1818ee3977', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'order', '{"en": "Put the Prophet’s ﷺ way of ghusl in order", "bn": "নবীজির ﷺ গোসলের পদ্ধতি ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Wash the hands", "bn": "দুই হাত ধোয়া"}, {"en": "Wash the private parts", "bn": "লজ্জাস্থান ধোয়া"}, {"en": "Do wudu as for salah", "bn": "নামাজের মতো অজু করা"}, {"en": "Pour water over the head three times", "bn": "মাথায় তিনবার পানি ঢালা"}, {"en": "Pour water over the whole body", "bn": "সারা শরীরে পানি ঢালা"}], "rtl": false}', '{"en": "As ‘A’ishah and Maymunah (RA) described it. What is a must is that water reaches the whole body.", "bn": "আয়েশা ও মাইমুনা (রা.) যেভাবে বর্ণনা করেছেন। আবশ্যক হলো সারা শরীরে পানি পৌঁছানো।"}', 'Sahih al-Bukhari 248; Sahih al-Bukhari 249', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7f3d0d98-fb48-5540-88fc-eed403cc56dc', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'true_false', '{"en": "In ghusl, water must reach the whole body.", "bn": "গোসলে সারা শরীরে পানি পৌঁছানো আবশ্যক।"}', '{"answer": true}', '{"en": "That is the core of ghusl; a dry spot left on purpose means the ghusl is not complete.", "bn": "এটিই গোসলের মূল; ইচ্ছা করে শুকনো জায়গা রাখলে গোসল পূর্ণ হয় না।"}', 'Quran 5:6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d785fe2a-fb7e-5a8f-8ce1-12b356f1220d', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'fill', '{"en": "Complete the sentence", "bn": "বাক্যটি পূর্ণ করুন"}', '{"options": [{"en": "earth", "bn": "মাটি"}, {"en": "milk", "bn": "দুধ"}, {"en": "perfume", "bn": "সুগন্ধি"}, {"en": "juice", "bn": "শরবত"}], "correct": 0, "rtl": false, "before": {"en": "If there is no water, purify yourself with clean", "bn": "পানি না পেলে পবিত্র"}, "after": {"en": "(tayammum).", "bn": "দিয়ে পবিত্র হও (তায়াম্মুম)।"}}', '{"en": "\"…and you find no water, then seek clean earth.\"", "bn": "\"…আর পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো।\""}', 'Quran 4:43', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('26f49272-17ce-541d-8b78-2cb867bad287', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'true_false', '{"en": "Tayammum is allowed for someone who is ill and would be harmed by water.", "bn": "পানিতে ক্ষতি হবে এমন অসুস্থ ব্যক্তির জন্য তায়াম্মুম জায়েজ।"}', '{"answer": true}', '{"en": "\"And if you are ill, or on a journey… and find no water, then seek clean earth.\"", "bn": "\"আর যদি তোমরা অসুস্থ হও বা সফরে থাকো… এবং পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো।\""}', 'Quran 5:6', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dd6da45e-e4dd-5eab-a6c7-c9313d93c34d', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'choice', '{"en": "In tayammum, what is wiped?", "bn": "তায়াম্মুমে কী মাসেহ করা হয়?"}', '{"options": [{"en": "The feet", "bn": "পা"}, {"en": "The face and hands", "bn": "মুখমণ্ডল ও হাত"}, {"en": "The head", "bn": "মাথা"}, {"en": "The whole body", "bn": "সারা শরীর"}], "correct": 1}', '{"en": "\"…and wipe your faces and hands with it.\"", "bn": "\"…এবং তা দিয়ে মুখমণ্ডল ও হাত মাসেহ করো।\""}', 'Quran 5:6', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('727320f7-2ffe-5771-9e10-602485836b40', '4361bf70-e649-5c2e-9ee4-d8254dc440fe', 'true_false', '{"en": "When water is found and can be used, the tayammum no longer counts.", "bn": "পানি পাওয়া গেলে এবং ব্যবহার করা গেলে তায়াম্মুম আর থাকে না।"}', '{"answer": true}', '{"en": "\"Clean earth is the Muslim’s means of purification… when he finds water, let him touch it to his skin.\"", "bn": "\"পবিত্র মাটি মুসলিমের পবিত্রতার উপায়… যখন সে পানি পাবে, তখন যেন তা শরীরে লাগায়।\""}', 'Sunan Abi Dawud 332; Jami‘ at-Tirmidhi 124', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('6554490a-ee12-58f0-b092-790737109472', '{"en": "Learn to pray", "bn": "নামাজ শিখি"}', '{"en": "Before the prayer, each position and what is said in it, and the rak‘ahs.", "bn": "নামাজের আগে, প্রতিটি অবস্থা ও তাতে কী পড়া হয়, এবং রাকাত।"}', NULL, 'clock', 'in_review', 2, (SELECT s.id FROM is_learn_sections s WHERE s.id = '3453004d-bf3a-5083-9293-131b518c7bdc')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d4aa79ca-0c78-52ae-ae13-83c7c3f399d2', '6554490a-ee12-58f0-b092-790737109472', '{"en": "Before the prayer", "bn": "নামাজের আগে"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7c351b1d-df6f-56b9-89bf-4aeb042ada9e', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'choice', '{"en": "Before salah, the body, clothes and place must be…?", "bn": "নামাজের আগে শরীর, কাপড় ও জায়গা কেমন হতে হবে?"}', '{"options": [{"en": "Clean (pure)", "bn": "পবিত্র"}, {"en": "New", "bn": "নতুন"}, {"en": "Expensive", "bn": "দামি"}, {"en": "Perfumed", "bn": "সুগন্ধিযুক্ত"}], "correct": 0}', '{"en": "\"And your clothing purify.\" Purity of body, clothes and place is a condition of salah.", "bn": "\"আর তোমার পোশাক পবিত্র রাখো।\" শরীর, কাপড় ও জায়গা পবিত্র থাকা নামাজের শর্ত।"}', 'Quran 74:4', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('56f13d02-5fad-594b-ad96-4cb9f906523d', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'true_false', '{"en": "A prayer offered before its time has begun is valid.", "bn": "ওয়াক্ত শুরুর আগে পড়া নামাজ সহিহ হয়।"}', '{"answer": false}', '{"en": "\"Indeed, prayer has been prescribed for the believers at fixed times.\"", "bn": "\"নিশ্চয় নামাজ মুমিনদের ওপর নির্দিষ্ট সময়ে ফরজ।\""}', 'Quran 4:103', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8c2c0f6c-2328-584c-b450-32d1fd2f4e5a', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'true_false', '{"en": "Covering the ‘awrah (the parts that must be covered) is a condition of salah.", "bn": "সতর ঢাকা নামাজের শর্ত।"}', '{"answer": true}', '{"en": "\"O children of Adam, take your adornment at every masjid.\"", "bn": "\"হে আদম সন্তান, প্রত্যেক নামাজের সময় তোমরা সাজসজ্জা (পোশাক) গ্রহণ করো।\""}', 'Quran 7:31', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9a873055-5b54-570d-a96f-28ee3ed8a988', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'choice', '{"en": "Where is the intention (niyyah) for salah made?", "bn": "নামাজের নিয়ত কোথায় করা হয়?"}', '{"options": [{"en": "In the heart", "bn": "অন্তরে"}, {"en": "On paper", "bn": "কাগজে"}, {"en": "Only aloud to others", "bn": "শুধু অন্যকে শুনিয়ে"}, {"en": "After the salam", "bn": "সালামের পর"}], "correct": 0}', '{"en": "\"Actions are only by intentions\" — the intention is the heart’s purpose to pray this prayer.", "bn": "\"সকল কাজ নিয়তের ওপর নির্ভরশীল\" — নিয়ত হলো অন্তরে এই নামাজ পড়ার সংকল্প।"}', 'Sahih al-Bukhari 1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8854583d-a345-5838-b810-62fbe3a22ba0', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'order', '{"en": "Put the phrases of the adhan in order", "bn": "আজানের বাক্যগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Ashhadu an la ilaha illallah", "bn": "আশহাদু আল্লা ইলাহা ইল্লাল্লাহ"}, {"en": "Ashhadu anna Muhammadar-Rasulullah", "bn": "আশহাদু আন্না মুহাম্মাদার রাসুলুল্লাহ"}, {"en": "Hayya ‘alas-salah", "bn": "হাইয়া আলাস সালাহ"}, {"en": "Hayya ‘alal-falah", "bn": "হাইয়া আলাল ফালাহ"}, {"en": "Allahu Akbar (again)", "bn": "আল্লাহু আকবার (আবার)"}, {"en": "La ilaha illallah", "bn": "লা ইলাহা ইল্লাল্লাহ"}], "rtl": false}', '{"en": "The adhan taught to ‘Abdullah ibn Zayd (RA); each phrase is repeated as the mu’adhdhin calls.", "bn": "আবদুল্লাহ ইবনে যায়েদ (রা.)-কে শেখানো আজান; মুয়াজ্জিন প্রতিটি বাক্য নির্দিষ্ট সংখ্যায় বলেন।"}', 'Sunan Abi Dawud 499', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0cfeb0a7-6daf-5398-8e49-e5dd44766786', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'fill', '{"en": "In the Fajr adhan", "bn": "ফজরের আজানে"}', '{"options": [{"en": "sleep", "bn": "ঘুম"}, {"en": "food", "bn": "খাবার"}, {"en": "work", "bn": "কাজ"}, {"en": "play", "bn": "খেলা"}], "correct": 0, "rtl": false, "before": {"en": "\"As-salatu khayrun minan-nawm\": prayer is better than", "bn": "\"আসসালাতু খাইরুম মিনান নাউম\": নামাজ"}, "after": {"en": "", "bn": "থেকে উত্তম"}}', '{"en": "It is added in the Fajr adhan only.", "bn": "এটি শুধু ফজরের আজানে বলা হয়।"}', 'Sunan Abi Dawud 500', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6ebd4183-d465-5581-94a3-f7ea579fb9f8', 'd4aa79ca-0c78-52ae-ae13-83c7c3f399d2', 'true_false', '{"en": "If you truly cannot find the qiblah, you try your best and pray in the direction you judge.", "bn": "কিবলা কোন দিকে কোনোভাবেই জানতে না পারলে সাধ্যমতো চিন্তা করে যে দিক মনে হয় সেদিকে নামাজ পড়বেন।"}', '{"answer": true}', '{"en": "\"Allah does not burden a soul beyond its capacity\"; facing the qiblah is required as far as one is able.", "bn": "\"আল্লাহ কাউকে সাধ্যের বাইরে দায়িত্ব দেন না\"; সাধ্যমতো কিবলামুখী হওয়া আবশ্যক।"}', 'Quran 2:286; Quran 2:144', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('e66646f7-047e-5cdc-8e1c-6fea99ad94d6', '6554490a-ee12-58f0-b092-790737109472', '{"en": "From takbir to ruku‘", "bn": "তাকবির থেকে রুকু"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0b16f1db-bab0-52f2-9fb2-f90ae2cf56e3', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'order', '{"en": "Put the first rak‘ah in order", "bn": "প্রথম রাকাত ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Opening takbir: Allahu Akbar", "bn": "শুরুর তাকবির: আল্লাহু আকবার"}, {"en": "Recite al-Fatiha", "bn": "সূরা ফাতিহা পড়া"}, {"en": "Recite another surah or some ayahs", "bn": "অন্য সূরা বা কিছু আয়াত পড়া"}, {"en": "Ruku‘: Subhana Rabbiyal-‘Azim", "bn": "রুকু: সুবহানা রাব্বিয়াল আযিম"}, {"en": "Rise: Sami‘Allahu liman hamidah", "bn": "ওঠা: সামি‘আল্লাহু লিমান হামিদাহ"}, {"en": "First sujud", "bn": "প্রথম সিজদা"}, {"en": "Sit briefly between the two", "bn": "দুই সিজদার মাঝে একটু বসা"}, {"en": "Second sujud", "bn": "দ্বিতীয় সিজদা"}], "rtl": false}', '{"en": "This is the order he ﷺ taught the man who prayed badly.", "bn": "যে ব্যক্তি ভুলভাবে নামাজ পড়েছিল, তাকে নবী ﷺ এই ক্রম শিখিয়েছিলেন।"}', 'Sahih al-Bukhari 757; Sahih al-Bukhari 789', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('da16edbe-603a-503c-aa43-6e873bef92a7', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'true_false', '{"en": "\"Amin\" is said after al-Fatiha.", "bn": "সূরা ফাতিহার পর \"আমিন\" বলা হয়।"}', '{"answer": true}', '{"en": "\"When the imam says Amin, say Amin…\"", "bn": "\"ইমাম যখন আমিন বলে, তোমরাও আমিন বলো…\""}', 'Sahih al-Bukhari 780', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9e24d908-21d5-5981-b2fc-4ebcf3b2d828', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'fill', '{"en": "What is said in ruku‘?", "bn": "রুকুতে কী পড়া হয়?"}', '{"options": [{"en": "‘Azim", "bn": "আযিম"}, {"en": "A‘la", "bn": "আ‘লা"}, {"en": "Hamd", "bn": "হামদ"}, {"en": "Akbar", "bn": "আকবার"}], "correct": 0, "rtl": false, "before": {"en": "Subhana Rabbiyal-", "bn": "সুবহানা রাব্বিয়াল"}}', '{"en": "\"Glory be to my Lord, the Most Great.\"", "bn": "\"আমার মহান রবের পবিত্রতা ঘোষণা করছি।\""}', 'Sahih Muslim 772', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4c601450-ebe9-5441-a82b-2f857ece95aa', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'true_false', '{"en": "In ruku‘ the back is kept level, the head neither raised nor lowered.", "bn": "রুকুতে পিঠ সমান রাখা হয়, মাথা উঁচুও নয় নিচুও নয়।"}', '{"answer": true}', '{"en": "‘A’ishah (RA): when he bowed he neither raised his head nor lowered it, but kept it in between.", "bn": "আয়েশা (রা.): রুকুতে তিনি মাথা উঁচুও করতেন না, নিচুও করতেন না, বরং মাঝামাঝি রাখতেন।"}', 'Sahih Muslim 498', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('28b32209-980d-559e-9b63-e0a918618d97', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'choice', '{"en": "When the imam says \"Sami‘Allahu liman hamidah\", the people behind him say…?", "bn": "ইমাম \"সামি‘আল্লাহু লিমান হামিদাহ\" বললে পেছনের মুসল্লিরা কী বলেন?"}', '{"options": [{"en": "Amin", "bn": "আমিন"}, {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Rabbana wa lakal-hamd", "bn": "রাব্বানা ওয়া লাকাল হামদ"}, {"en": "Subhanallah", "bn": "সুবহানাল্লাহ"}], "correct": 2}', '{"en": "\"…say: Allahumma Rabbana lakal-hamd (O Allah, our Lord, to You is all praise).\"", "bn": "\"…তোমরা বলো: আল্লাহুম্মা রাব্বানা লাকাল হামদ (হে আল্লাহ, আমাদের রব, সব প্রশংসা আপনার)।\""}', 'Sahih al-Bukhari 796', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fd8b0946-55af-50cc-bffd-a71b2c957457', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'match', '{"en": "Match each phrase to its meaning", "bn": "প্রতিটি বাক্যের অর্থ মেলান"}', '{"pairs": [{"left": {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, "right": {"en": "Allah is the Greatest", "bn": "আল্লাহ সবচেয়ে বড়"}}, {"left": {"en": "Subhana Rabbiyal-‘Azim", "bn": "সুবহানা রাব্বিয়াল আযিম"}, "right": {"en": "Glory be to my Lord, the Most Great", "bn": "আমার মহান রবের পবিত্রতা"}}, {"left": {"en": "Sami‘Allahu liman hamidah", "bn": "সামি‘আল্লাহু লিমান হামিদাহ"}, "right": {"en": "Allah hears whoever praises Him", "bn": "যে প্রশংসা করে আল্লাহ তা শোনেন"}}, {"left": {"en": "Rabbana wa lakal-hamd", "bn": "রাব্বানা ওয়া লাকাল হামদ"}, "right": {"en": "Our Lord, to You is all praise", "bn": "হে আমাদের রব, সব প্রশংসা আপনার"}}]}', '{"en": "The words of the standing and the ruku‘.", "bn": "দাঁড়ানো ও রুকুর বাক্যগুলো।"}', 'Sahih al-Bukhari 789; Sahih Muslim 772', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0f3a5c93-58ad-5458-923c-337da52b3655', 'e66646f7-047e-5cdc-8e1c-6fea99ad94d6', 'true_false', '{"en": "We should recite the Quran in ruku‘ and sujud.", "bn": "রুকু ও সিজদায় কুরআন তিলাওয়াত করা উচিত।"}', '{"answer": false}', '{"en": "\"I have been forbidden to recite the Quran while bowing or prostrating.\"", "bn": "\"রুকু বা সিজদা অবস্থায় কুরআন পড়তে আমাকে নিষেধ করা হয়েছে।\""}', 'Sahih Muslim 479', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('84a026b8-29b8-5efc-8900-1f63ccd4abfc', '6554490a-ee12-58f0-b092-790737109472', '{"en": "Sujud & sitting", "bn": "সিজদা ও বৈঠক"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3cde71b5-24d0-52da-bfd2-56b832986fef', '84a026b8-29b8-5efc-8900-1f63ccd4abfc', 'choice', '{"en": "On how many body parts did the Prophet ﷺ say to prostrate?", "bn": "নবী ﷺ কয়টি অঙ্গের ওপর সিজদা করতে বলেছেন?"}', '{"options": [{"en": "Three", "bn": "তিনটি"}, {"en": "Five", "bn": "পাঁচটি"}, {"en": "Seven", "bn": "সাতটি"}, {"en": "Ten", "bn": "দশটি"}], "correct": 2}', '{"en": "\"…on seven bones: the forehead (and nose), the two hands, the two knees and the ends of the two feet.\"", "bn": "\"…সাতটি অঙ্গের ওপর: কপাল (ও নাক), দুই হাত, দুই হাঁটু ও দুই পায়ের আঙুল।\""}', 'Sahih al-Bukhari 812', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cf73e2e2-a0f8-534c-a011-9c2400712815', '84a026b8-29b8-5efc-8900-1f63ccd4abfc', 'match', '{"en": "What is said where? Match them", "bn": "কোথায় কী পড়া হয়? মেলান"}', '{"pairs": [{"left": {"en": "Subhana Rabbiyal-‘Azim", "bn": "সুবহানা রাব্বিয়াল আযিম"}, "right": {"en": "Ruku‘", "bn": "রুকু"}}, {"left": {"en": "Subhana Rabbiyal-A‘la", "bn": "সুবহানা রাব্বিয়াল আ‘লা"}, "right": {"en": "Sujud", "bn": "সিজদা"}}, {"left": {"en": "Rabbighfir li", "bn": "রাব্বিগফিরলি"}, "right": {"en": "Between the two sujud", "bn": "দুই সিজদার মাঝে"}}, {"left": {"en": "At-tahiyyatu lillah…", "bn": "আত্তাহিয়্যাতু লিল্লাহ…"}, "right": {"en": "The sitting (tashahhud)", "bn": "বৈঠক (তাশাহহুদ)"}}]}', '{"en": "Each position has its own remembrance.", "bn": "প্রতিটি অবস্থার নিজস্ব জিকির আছে।"}', 'Sahih Muslim 772; Sunan Abi Dawud 874; Sahih al-Bukhari 831', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9eafce8c-cbd7-53ae-ae9f-42b4cb53191e', '84a026b8-29b8-5efc-8900-1f63ccd4abfc', 'fill', '{"en": "What is said in sujud?", "bn": "সিজদায় কী পড়া হয়?"}', '{"options": [{"en": "‘Azim", "bn": "আযিম"}, {"en": "A‘la", "bn": "আ‘লা"}, {"en": "Karim", "bn": "কারিম"}, {"en": "Hamd", "bn": "হামদ"}], "correct": 1, "rtl": false, "before": {"en": "Subhana Rabbiyal-", "bn": "সুবহানা রাব্বিয়াল"}}', '{"en": "\"Glory be to my Lord, the Most High.\"", "bn": "\"আমার সর্বোচ্চ রবের পবিত্রতা ঘোষণা করছি।\""}', 'Sahih Muslim 772', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('71dc84b0-ed38-57ca-b2b8-b0c07e19e469', '84a026b8-29b8-5efc-8900-1f63ccd4abfc', 'true_false', '{"en": "A servant is closest to his Lord in sujud, so make much dua there.", "bn": "সিজদায় বান্দা তার রবের সবচেয়ে নিকটে থাকে, তাই সেখানে বেশি দোয়া করো।"}', '{"answer": true}', '{"en": "\"The closest a servant is to his Lord is while he is prostrating, so make much dua.\"", "bn": "\"বান্দা তার রবের সবচেয়ে নিকটে থাকে সিজদা অবস্থায়, তাই বেশি করে দোয়া করো।\""}', 'Sahih Muslim 482', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('818e6eec-818f-533b-b475-5bafafdb756d', '84a026b8-29b8-5efc-8900-1f63ccd4abfc', 'true_false', '{"en": "In a four-rak‘ah prayer there is a sitting after the second rak‘ah and another at the end.", "bn": "চার রাকাতের নামাজে দ্বিতীয় রাকাতের পর একটি এবং শেষে আরেকটি বৈঠক আছে।"}', '{"answer": true}', '{"en": "When he ﷺ once stood up without the first sitting, he made two prostrations of forgetfulness for it.", "bn": "একবার নবী ﷺ প্রথম বৈঠক না করে দাঁড়িয়ে গেলে তার জন্য সাহু সিজদা করেছিলেন।"}', 'Sahih al-Bukhari 829', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fd84ca93-4189-5626-ab6c-8e1e2a1f0956', '84a026b8-29b8-5efc-8900-1f63ccd4abfc', 'choice', '{"en": "What is recited in the first sitting, after two rak‘ahs?", "bn": "দুই রাকাতের পর প্রথম বৈঠকে কী পড়া হয়?"}', '{"options": [{"en": "Al-Fatiha", "bn": "সূরা ফাতিহা"}, {"en": "The tashahhud (at-tahiyyat)", "bn": "তাশাহহুদ (আত্তাহিয়্যাতু)"}, {"en": "Ayat al-Kursi", "bn": "আয়াতুল কুরসি"}, {"en": "The adhan", "bn": "আজান"}], "correct": 1}', '{"en": "\"When you sit after every two rak‘ahs, say: At-tahiyyatu lillah…\"", "bn": "\"প্রতি দুই রাকাত পর যখন বসবে, বলবে: আত্তাহিয়্যাতু লিল্লাহ…\""}', 'Sahih al-Bukhari 831; Sunan an-Nasa’i (from Ibn Mas‘ud)', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('f81c27a7-1640-5fe7-984b-efbace9c3fce', '6554490a-ee12-58f0-b092-790737109472', '{"en": "Tashahhud, salawat & salam", "bn": "তাশাহহুদ, দরুদ ও সালাম"}', 'lesson', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7f992de2-224c-568e-a763-95c4f581ed31', 'f81c27a7-1640-5fe7-984b-efbace9c3fce', 'order', '{"en": "Put the tashahhud in order (Ibn Mas‘ud’s wording)", "bn": "তাশাহহুদ ক্রমানুসারে সাজান (ইবনে মাসউদের বর্ণনা)"}', '{"pieces": [{"en": "At-tahiyyatu lillahi", "bn": "আত্তাহিয়্যাতু লিল্লাহি"}, {"en": "was-salawatu wat-tayyibat", "bn": "ওয়াস সালাওয়াতু ওয়াত তাইয়্যিবাতু"}, {"en": "As-salamu ‘alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh", "bn": "আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ"}, {"en": "As-salamu ‘alayna wa ‘ala ‘ibadillahis-salihin", "bn": "আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন"}, {"en": "Ashhadu an la ilaha illallah", "bn": "আশহাদু আল্লা ইলাহা ইল্লাল্লাহু"}, {"en": "wa ashhadu anna Muhammadan ‘abduhu wa rasuluh", "bn": "ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ"}], "rtl": false}', '{"en": "Ibn Mas‘ud (RA) learnt it from the Prophet ﷺ like a surah. (Other authentic wordings exist, e.g. Ibn ‘Abbas’s.)", "bn": "ইবনে মাসউদ (রা.) নবী ﷺ থেকে সূরার মতো করে এটি শিখেছেন। (ইবনে আব্বাসের বর্ণনার মতো অন্য সহিহ শব্দও আছে।)"}', 'Sahih al-Bukhari 831; Sahih al-Bukhari 6265', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d1cb6cda-25d5-5386-9fbc-a698fe246b84', 'f81c27a7-1640-5fe7-984b-efbace9c3fce', 'match', '{"en": "Match each part of the tashahhud to its meaning", "bn": "তাশাহহুদের প্রতিটি অংশের অর্থ মেলান"}', '{"pairs": [{"left": {"en": "At-tahiyyatu lillah", "bn": "আত্তাহিয়্যাতু লিল্লাহ"}, "right": {"en": "All greetings are for Allah", "bn": "সকল সম্মান-অভিবাদন আল্লাহর জন্য"}}, {"left": {"en": "As-salamu ‘alayka ayyuhan-nabiyy", "bn": "আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু"}, "right": {"en": "Peace be upon you, O Prophet", "bn": "হে নবী, আপনার ওপর শান্তি বর্ষিত হোক"}}, {"left": {"en": "As-salamu ‘alayna wa ‘ala ‘ibadillahis-salihin", "bn": "আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন"}, "right": {"en": "Peace be upon us and on Allah’s righteous servants", "bn": "শান্তি বর্ষিত হোক আমাদের ওপর ও আল্লাহর নেক বান্দাদের ওপর"}}, {"left": {"en": "Ashhadu an la ilaha illallah", "bn": "আশহাদু আল্লা ইলাহা ইল্লাল্লাহ"}, "right": {"en": "I testify that there is no god but Allah", "bn": "আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই"}}]}', '{"en": "Understanding what we say makes the prayer come alive.", "bn": "যা পড়ছি তা বুঝলে নামাজ প্রাণবন্ত হয়।"}', 'Sahih al-Bukhari 831', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('32254b77-95b6-5d90-932b-1e8de9985968', 'f81c27a7-1640-5fe7-984b-efbace9c3fce', 'choice', '{"en": "Besides Muhammad ﷺ, which prophet is named in the salawat (Durud Ibrahim)?", "bn": "দরুদে ইবরাহিমে মুহাম্মাদ ﷺ ছাড়া আর কোন নবীর নাম আছে?"}', '{"options": [{"en": "Musa", "bn": "মুসা (আ.)"}, {"en": "Ibrahim", "bn": "ইবরাহিম (আ.)"}, {"en": "Isa", "bn": "ঈসা (আ.)"}, {"en": "Nuh", "bn": "নূহ (আ.)"}], "correct": 1}', '{"en": "\"…as You sent blessings on Ibrahim and the family of Ibrahim…\"", "bn": "\"…যেমন আপনি ইবরাহিম ও ইবরাহিমের পরিবারের ওপর রহমত পাঠিয়েছেন…\""}', 'Sahih al-Bukhari 3370', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a1b3899d-0685-5034-adf1-c028b21016bb', 'f81c27a7-1640-5fe7-984b-efbace9c3fce', 'true_false', '{"en": "The salawat (Durud Ibrahim) is recited in the last sitting, after the tashahhud.", "bn": "দরুদে ইবরাহিম শেষ বৈঠকে তাশাহহুদের পর পড়া হয়।"}', '{"answer": true}', '{"en": "The companions asked how to send salawat on him in the prayer, and he ﷺ taught this.", "bn": "সাহাবিরা নামাজে কীভাবে দরুদ পড়বেন জিজ্ঞেস করলে নবী ﷺ এটি শেখান।"}', 'Sahih al-Bukhari 3370', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('20a4f66d-f5ad-544a-a9b1-5a4bc2cf23d4', 'f81c27a7-1640-5fe7-984b-efbace9c3fce', 'true_false', '{"en": "Before the salam, it is good to seek refuge from four things: Hell, the grave, the trials of life and death, and the Dajjal.", "bn": "সালামের আগে চারটি জিনিস থেকে আশ্রয় চাওয়া ভালো: জাহান্নাম, কবরের আজাব, জীবন-মৃত্যুর ফিতনা ও দাজ্জাল।"}', '{"answer": true}', '{"en": "\"When one of you finishes the last tashahhud, let him seek refuge with Allah from four…\"", "bn": "\"তোমাদের কেউ শেষ তাশাহহুদ শেষ করলে চারটি জিনিস থেকে আল্লাহর কাছে আশ্রয় চাইবে…\""}', 'Sahih Muslim 588', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9e36e573-8064-50f3-b16a-b76ac697d12b', 'f81c27a7-1640-5fe7-984b-efbace9c3fce', 'choice', '{"en": "With which words does the prayer end?", "bn": "কোন বাক্য দিয়ে নামাজ শেষ হয়?"}', '{"options": [{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Amin", "bn": "আমিন"}, {"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "As-salamu ‘alaykum wa rahmatullah", "bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ"}], "correct": 3}', '{"en": "\"…its closing is the salam.\"", "bn": "\"…নামাজের সমাপ্তি সালাম।\""}', 'Sunan Abi Dawud 61; Sahih Muslim 582', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('27495074-fb29-57b7-80f2-da3636e4c024', '6554490a-ee12-58f0-b092-790737109472', '{"en": "Rak‘ahs & times", "bn": "রাকাত ও ওয়াক্ত"}', 'lesson', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('85fed799-a832-5445-9eae-9217975a3a84', '27495074-fb29-57b7-80f2-da3636e4c024', 'match', '{"en": "Match each prayer to its time", "bn": "প্রতিটি নামাজের সময় মেলান"}', '{"pairs": [{"left": {"en": "Fajr", "bn": "ফজর"}, "right": {"en": "From dawn until sunrise", "bn": "সুবহে সাদিক থেকে সূর্যোদয় পর্যন্ত"}}, {"left": {"en": "Dhuhr", "bn": "যোহর"}, "right": {"en": "After the sun passes its height", "bn": "সূর্য মাথার ওপর থেকে হেলে পড়ার পর"}}, {"left": {"en": "Asr", "bn": "আসর"}, "right": {"en": "The afternoon", "bn": "বিকেল"}}, {"left": {"en": "Maghrib", "bn": "মাগরিব"}, "right": {"en": "Just after sunset", "bn": "সূর্যাস্তের পরপর"}}, {"left": {"en": "Isha", "bn": "এশা"}, "right": {"en": "Night, after the twilight goes", "bn": "রাতে, পশ্চিম আকাশের লালিমা মিলিয়ে যাওয়ার পর"}}]}', '{"en": "The five times the Prophet ﷺ described.", "bn": "নবী ﷺ যে পাঁচ সময়ের বর্ণনা দিয়েছেন।"}', 'Sahih Muslim 612', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6e32e765-0643-56df-bf9f-504499418834', '27495074-fb29-57b7-80f2-da3636e4c024', 'fill', '{"en": "Count the fard rak‘ahs", "bn": "ফরজ রাকাত গুনুন"}', '{"options": [{"en": "17", "bn": "১৭"}, {"en": "15", "bn": "১৫"}, {"en": "20", "bn": "২০"}, {"en": "12", "bn": "১২"}], "correct": 0, "rtl": false, "before": {"en": "Fard rak‘ahs in a day (not travelling): 2 + 4 + 4 + 3 + 4 =", "bn": "দিনে ফরজ রাকাত (মুসাফির না হলে): ২ + ৪ + ৪ + ৩ + ৪ ="}}', '{"en": "Fajr 2, Dhuhr 4, Asr 4, Maghrib 3, Isha 4 = 17.", "bn": "ফজর ২, যোহর ৪, আসর ৪, মাগরিব ৩, এশা ৪ = ১৭।"}', 'Sahih al-Bukhari 350', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('df3eea5a-9349-5682-88ca-9fd5baa241ba', '27495074-fb29-57b7-80f2-da3636e4c024', 'choice', '{"en": "Which prayer is prayed after the sun passes its highest point?", "bn": "সূর্য মাথার ওপর থেকে হেলে পড়ার পর কোন নামাজ?"}', '{"options": [{"en": "Fajr", "bn": "ফজর"}, {"en": "Dhuhr", "bn": "যোহর"}, {"en": "Maghrib", "bn": "মাগরিব"}, {"en": "Isha", "bn": "এশা"}], "correct": 1}', '{"en": "\"The time of Dhuhr is when the sun has passed the meridian…\"", "bn": "\"সূর্য হেলে পড়লে যোহরের সময়…\""}', 'Sahih Muslim 612', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2304d856-3e3b-5272-a298-5dc62a769b2c', '27495074-fb29-57b7-80f2-da3636e4c024', 'true_false', '{"en": "A traveller prays Maghrib as two rak‘ahs.", "bn": "মুসাফির মাগরিব দুই রাকাত পড়েন।"}', '{"answer": false}', '{"en": "Only four-rak‘ah prayers are shortened; Maghrib stays three.", "bn": "শুধু চার রাকাতের নামাজ কসর হয়; মাগরিব তিন রাকাতই থাকে।"}', 'Sahih al-Bukhari 1090', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cc7e9abf-c5e8-547c-980c-21fdc1228492', '27495074-fb29-57b7-80f2-da3636e4c024', 'true_false', '{"en": "The Prophet ﷺ forbade praying at the moment the sun is rising.", "bn": "সূর্য উদয়ের মুহূর্তে নামাজ পড়তে নবী ﷺ নিষেধ করেছেন।"}', '{"answer": true}', '{"en": "‘Uqbah (RA): three times he forbade us to pray — when the sun rises, at its height, and when it sets.", "bn": "উকবা (রা.): তিন সময়ে নামাজ পড়তে তিনি নিষেধ করেছেন — সূর্যোদয়, ঠিক দুপুর ও সূর্যাস্তের সময়।"}', 'Sahih Muslim 831', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('02c65075-4af9-52be-913f-fc3dad7dc727', '27495074-fb29-57b7-80f2-da3636e4c024', 'choice', '{"en": "How many rak‘ahs is the Eid prayer?", "bn": "ঈদের নামাজ কত রাকাত?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "1", "bn": "১"}], "correct": 0}', '{"en": "Ibn ‘Abbas (RA): he ﷺ went out on the day of Eid and prayed two rak‘ahs.", "bn": "ইবনে আব্বাস (রা.): নবী ﷺ ঈদের দিন বের হয়ে দুই রাকাত নামাজ পড়েছেন।"}', 'Sahih al-Bukhari 989', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('295f0812-829a-5959-8c58-71a5e136ff66', '6554490a-ee12-58f0-b092-790737109472', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('511309d1-8f45-5280-b44f-bf2471e99b05', '295f0812-829a-5959-8c58-71a5e136ff66', 'match', '{"en": "What is said where? Match them", "bn": "কোথায় কী পড়া হয়? মেলান"}', '{"pairs": [{"left": {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, "right": {"en": "Opening the prayer", "bn": "নামাজ শুরু"}}, {"left": {"en": "Al-Fatiha", "bn": "সূরা ফাতিহা"}, "right": {"en": "Standing", "bn": "দাঁড়ানো অবস্থায়"}}, {"left": {"en": "Subhana Rabbiyal-A‘la", "bn": "সুবহানা রাব্বিয়াল আ‘লা"}, "right": {"en": "Sujud", "bn": "সিজদা"}}, {"left": {"en": "As-salamu ‘alaykum wa rahmatullah", "bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ"}, "right": {"en": "Ending the prayer", "bn": "নামাজ শেষ"}}]}', '{"en": "\"Its opening is the takbir and its closing is the salam.\"", "bn": "\"নামাজের শুরু তাকবির আর শেষ সালাম।\""}', 'Sunan Abi Dawud 61', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a9530791-e4fa-529c-89ae-85e49af44616', '295f0812-829a-5959-8c58-71a5e136ff66', 'true_false', '{"en": "Rabbighfir li is said in ruku‘.", "bn": "রাব্বিগফিরলি রুকুতে পড়া হয়।"}', '{"answer": false}', '{"en": "\"Rabbighfir li\" is said between the two prostrations; in ruku‘ we say \"Subhana Rabbiyal-‘Azim\".", "bn": "\"রাব্বিগফিরলি\" পড়া হয় দুই সিজদার মাঝে; রুকুতে \"সুবহানা রাব্বিয়াল আযিম\"।"}', 'Sunan Abi Dawud 874', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4d780880-9001-56b4-ab57-85015d7bae00', '295f0812-829a-5959-8c58-71a5e136ff66', 'choice', '{"en": "How many sujud are in each rak‘ah?", "bn": "প্রতি রাকাতে কয়টি সিজদা?"}', '{"options": [{"en": "1", "bn": "১"}, {"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}], "correct": 1}', '{"en": "Prostrate, sit, prostrate again.", "bn": "সিজদা, বসা, আবার সিজদা।"}', 'Sahih al-Bukhari 757', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('71c321cb-fb64-57b3-afd7-570604b979b5', '295f0812-829a-5959-8c58-71a5e136ff66', 'fill', '{"en": "Complete the phrase", "bn": "বাক্যটি পূর্ণ করুন"}', '{"options": [{"en": "hamidah", "bn": "হামিদাহ"}, {"en": "‘Azim", "bn": "আযিম"}, {"en": "akbar", "bn": "আকবার"}, {"en": "rajim", "bn": "রাজিম"}], "correct": 0, "rtl": false, "before": {"en": "Sami‘Allahu liman", "bn": "সামি‘আল্লাহু লিমান"}}', '{"en": "Said while rising from ruku‘.", "bn": "রুকু থেকে ওঠার সময় বলা হয়।"}', 'Sahih al-Bukhari 789', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9a5f1a0b-24a3-5aae-b33c-252e5660a4f5', '295f0812-829a-5959-8c58-71a5e136ff66', 'true_false', '{"en": "The adhan begins with \"Allahu Akbar\" and ends with \"La ilaha illallah\".", "bn": "আজান \"আল্লাহু আকবার\" দিয়ে শুরু ও \"লা ইলাহা ইল্লাল্লাহ\" দিয়ে শেষ হয়।"}', '{"answer": true}', '{"en": "As taught to ‘Abdullah ibn Zayd (RA).", "bn": "আবদুল্লাহ ইবনে যায়েদ (রা.)-কে যেভাবে শেখানো হয়েছিল।"}', 'Sunan Abi Dawud 499', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c32a7310-40f3-589e-958f-8ac58d104592', '295f0812-829a-5959-8c58-71a5e136ff66', 'choice', '{"en": "In which position is a servant closest to his Lord?", "bn": "কোন অবস্থায় বান্দা তার রবের সবচেয়ে নিকটে?"}', '{"options": [{"en": "Standing", "bn": "দাঁড়ানো"}, {"en": "Ruku‘", "bn": "রুকু"}, {"en": "Sujud", "bn": "সিজদা"}, {"en": "Sitting", "bn": "বসা"}], "correct": 2}', '{"en": "\"…while he is prostrating, so make much dua.\"", "bn": "\"…সিজদা অবস্থায়, তাই বেশি দোয়া করো।\""}', 'Sahih Muslim 482', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8bab3b4e-7399-5431-bd48-ba2b28c8435d', '295f0812-829a-5959-8c58-71a5e136ff66', 'true_false', '{"en": "Asr has four fard rak‘ahs for one who is not travelling.", "bn": "মুসাফির না হলে আসরে চার রাকাত ফরজ।"}', '{"answer": true}', '{"en": "Dhuhr, Asr and Isha have four each.", "bn": "যোহর, আসর ও এশায় চার রাকাত করে।"}', 'Sahih al-Bukhari 350', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('05ef6f1c-2284-5ad5-85af-cdc484eacafb', '{"en": "Learn about janazah", "bn": "জানাযা শিখি"}', '{"en": "What to do after a death, the janazah prayer, burial and visiting graves.", "bn": "মৃত্যুর পর করণীয়, জানাযার নামাজ, দাফন ও কবর জিয়ারত।"}', NULL, 'hand-heart', 'in_review', 3, (SELECT s.id FROM is_learn_sections s WHERE s.id = '3453004d-bf3a-5083-9293-131b518c7bdc')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('7f929e02-a12f-55f3-94b0-30dc9ed39a6d', '05ef6f1c-2284-5ad5-85af-cdc484eacafb', '{"en": "After a death", "bn": "মৃত্যুর পর করণীয়"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('30ff23ef-cb99-5bf5-942d-f52da4fe5a12', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'fill', '{"en": "What do we say on hearing of a death?", "bn": "মৃত্যুর খবর শুনলে কী বলি?"}', '{"options": [{"en": "raji‘un", "bn": "রাজিউন"}, {"en": "akbar", "bn": "আকবার"}, {"en": "‘alaykum", "bn": "আলাইকুম"}, {"en": "al-hamd", "bn": "আল-হামদ"}], "correct": 0, "rtl": false, "before": {"en": "Inna lillahi wa inna ilayhi", "bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি"}}', '{"en": "\"Indeed we belong to Allah, and to Him we will return.\"", "bn": "\"নিশ্চয় আমরা আল্লাহর জন্য এবং নিশ্চয় আমরা তাঁরই দিকে ফিরে যাব।\""}', 'Quran 2:156', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d88c7b40-ad96-5a2b-b49c-5374977839ab', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'true_false', '{"en": "The Prophet ﷺ closed the eyes of Abu Salamah after he died.", "bn": "আবু সালামা (রা.)-এর মৃত্যুর পর নবী ﷺ তাঁর চোখ বন্ধ করে দিয়েছিলেন।"}', '{"answer": true}', '{"en": "He ﷺ closed his eyes and said: \"When the soul is taken, the sight follows it.\"", "bn": "তিনি চোখ বন্ধ করে বললেন: \"যখন রুহ কবজ করা হয়, দৃষ্টি তার অনুসরণ করে।\""}', 'Sahih Muslim 920', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c0fe9a18-e58b-5e2b-a0ae-fcd7ace117da', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'true_false', '{"en": "The deceased is washed an odd number of times, as the Prophet ﷺ instructed.", "bn": "নবী ﷺ-এর নির্দেশমতো মৃতকে বেজোড় সংখ্যকবার গোসল দেওয়া হয়।"}', '{"answer": true}', '{"en": "\"Wash her three or five times, or more if you see fit… and begin with her right side and the places of wudu.\"", "bn": "\"তাকে তিন বা পাঁচবার, প্রয়োজন মনে করলে আরও বেশি গোসল দাও… ডান দিক ও অজুর অঙ্গ থেকে শুরু করো।\""}', 'Sahih al-Bukhari 1253; Sahih al-Bukhari 167', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('82b49a45-3f2c-5642-853b-6aa6674519a0', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'true_false', '{"en": "The martyrs of Uhud were buried without being washed.", "bn": "উহুদের শহিদদের গোসল ছাড়াই দাফন করা হয়েছিল।"}', '{"answer": true}', '{"en": "He ﷺ ordered them buried in their blood, without washing.", "bn": "নবী ﷺ তাঁদের রক্তমাখা অবস্থায় গোসল ছাড়া দাফনের নির্দেশ দেন।"}', 'Sahih al-Bukhari 1343', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a45f0b04-ae28-5cee-96ff-d2a1a2264585', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'choice', '{"en": "What colour of cloth did the Prophet ﷺ recommend for the shroud?", "bn": "কাফনের জন্য নবী ﷺ কোন রঙের কাপড় পছন্দ করেছেন?"}', '{"options": [{"en": "Black", "bn": "কালো"}, {"en": "Green", "bn": "সবুজ"}, {"en": "Red", "bn": "লাল"}, {"en": "White", "bn": "সাদা"}], "correct": 3}', '{"en": "\"Wear white clothes… and shroud your dead in them.\"", "bn": "\"তোমরা সাদা পোশাক পরো… এবং তাতে তোমাদের মৃতদের কাফন দাও।\""}', 'Sunan Abi Dawud 3878; Jami‘ at-Tirmidhi 994', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1993bdc2-518f-53d2-84af-14167d7df22e', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'true_false', '{"en": "The deceased’s debts are paid before the inheritance is shared out.", "bn": "মৃতের ঋণ মিরাস বণ্টনের আগে পরিশোধ করা হয়।"}', '{"answer": true}', '{"en": "\"…after any bequest he made or debt.\"", "bn": "\"…তার অসিয়ত পূরণ ও ঋণ পরিশোধের পর।\""}', 'Quran 4:11–12', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3865de18-85d0-5cc6-80b0-3c481a16ee9a', '7f929e02-a12f-55f3-94b0-30dc9ed39a6d', 'choice', '{"en": "When Ja‘far (RA) was martyred, what did the Prophet ﷺ tell people to do for his family?", "bn": "জাফর (রা.) শহিদ হলে নবী ﷺ তাঁর পরিবারের জন্য কী করতে বলেছিলেন?"}', '{"options": [{"en": "Make food for them", "bn": "তাদের জন্য খাবার তৈরি করো"}, {"en": "Hold a feast at their house", "bn": "তাদের বাড়িতে ভোজ করো"}, {"en": "Leave them alone for a year", "bn": "এক বছর তাদের থেকে দূরে থাকো"}, {"en": "Nothing", "bn": "কিছু না"}], "correct": 0}', '{"en": "\"Make food for the family of Ja‘far, for something has come to them that keeps them busy.\"", "bn": "\"জাফরের পরিবারের জন্য খাবার তৈরি করো, কারণ তাদের ওপর এমন বিপদ এসেছে যা তাদের ব্যস্ত রেখেছে।\""}', 'Sunan Abi Dawud 3132; Jami‘ at-Tirmidhi 998', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('acd33a44-9f50-5ca5-95fa-2871accba305', '05ef6f1c-2284-5ad5-85af-cdc484eacafb', '{"en": "The janazah prayer", "bn": "জানাযার নামাজ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f1cae9c9-4c15-5342-8e83-64c4fb3ba778', 'acd33a44-9f50-5ca5-95fa-2871accba305', 'choice', '{"en": "How many takbirs are in the janazah prayer?", "bn": "জানাযার নামাজে কয়টি তাকবির?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "5", "bn": "৫"}], "correct": 2}', '{"en": "He ﷺ prayed over the Negus with four takbirs.", "bn": "নবী ﷺ চার তাকবিরে নাজাশির জানাযা পড়েছেন।"}', 'Sahih al-Bukhari 1333', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c2d37556-94ac-597a-9302-4680411d305b', 'acd33a44-9f50-5ca5-95fa-2871accba305', 'true_false', '{"en": "The janazah prayer has ruku‘ and sujud.", "bn": "জানাযার নামাজে রুকু ও সিজদা আছে।"}', '{"answer": false}', '{"en": "It is prayed standing: takbirs, praise, salawat and dua, then the salam.", "bn": "এটি দাঁড়িয়ে পড়া হয়: তাকবির, প্রশংসা, দরুদ ও দোয়া, তারপর সালাম।"}', 'Sahih al-Bukhari 1333', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a745ef90-630d-5af6-b976-7fc3ba65ea88', 'acd33a44-9f50-5ca5-95fa-2871accba305', 'choice', '{"en": "What is the heart of the janazah duas?", "bn": "জানাযার দোয়ার মূল বিষয় কী?"}', '{"options": [{"en": "Asking forgiveness and mercy for the deceased", "bn": "মৃতের জন্য ক্ষমা ও রহমত চাওয়া"}, {"en": "Praising his wealth", "bn": "তার সম্পদের প্রশংসা"}, {"en": "Asking for rain", "bn": "বৃষ্টি চাওয়া"}, {"en": "Reciting poetry", "bn": "কবিতা পাঠ"}], "correct": 0}', '{"en": "\"When you pray over the deceased, make your dua for him sincere.\"", "bn": "\"মৃতের জানাযা পড়লে তার জন্য আন্তরিকভাবে দোয়া করো।\""}', 'Sunan Abi Dawud 3199', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e477e980-4db2-5d98-be3f-c3bd63296521', 'acd33a44-9f50-5ca5-95fa-2871accba305', 'choice', '{"en": "What does \"Allahummaghfir lahu warhamhu\" mean?", "bn": "\"আল্লাহুম্মাগফির লাহু ওয়ারহামহু\" অর্থ কী?"}', '{"options": [{"en": "O Allah, give him wealth", "bn": "হে আল্লাহ, তাকে সম্পদ দিন"}, {"en": "O Allah, forgive him and have mercy on him", "bn": "হে আল্লাহ, তাকে ক্ষমা করুন ও তার প্রতি দয়া করুন"}, {"en": "O Allah, guide us", "bn": "হে আল্লাহ, আমাদের হেদায়াত দিন"}, {"en": "O Allah, send rain", "bn": "হে আল্লাহ, বৃষ্টি দিন"}], "correct": 1}', '{"en": "The opening of a janazah dua the Prophet ﷺ made, reported by ‘Awf ibn Malik (RA).", "bn": "আউফ ইবনে মালিক (রা.) বর্ণিত নবীজির ﷺ জানাযার দোয়ার শুরু।"}', 'Sahih Muslim 963', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('738c521b-cf8c-5a17-8b71-fa0ba98e61b8', 'acd33a44-9f50-5ca5-95fa-2871accba305', 'true_false', '{"en": "If a hundred Muslims pray over someone, interceding for him, their intercession for him is accepted.", "bn": "কারো জানাযায় একশো মুসলিম তার জন্য সুপারিশ করে নামাজ পড়লে তাদের সুপারিশ কবুল হয়।"}', '{"answer": true}', '{"en": "In another narration: forty men who associate nothing with Allah.", "bn": "আরেক বর্ণনায়: চল্লিশজন, যারা আল্লাহর সঙ্গে কিছু শরিক করে না।"}', 'Sahih Muslim 947; Sahih Muslim 948', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bde10ece-83d1-502d-b9dc-a59a3fcf193d', 'acd33a44-9f50-5ca5-95fa-2871accba305', 'true_false', '{"en": "Whoever stays with the funeral until the burial gets two qirats of reward, each like a great mountain.", "bn": "যে দাফন পর্যন্ত জানাযার সঙ্গে থাকে সে দুই কিরাত সওয়াব পায়, প্রতিটি বিশাল পাহাড়ের মতো।"}', '{"answer": true}', '{"en": "One qirat for the prayer, two for staying until the burial.", "bn": "নামাজে এক কিরাত, দাফন পর্যন্ত থাকলে দুই কিরাত।"}', 'Sahih al-Bukhari 1325', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('c06171b3-aabc-5a0e-b5d4-f1254efb3109', '05ef6f1c-2284-5ad5-85af-cdc484eacafb', '{"en": "Burial & visiting graves", "bn": "দাফন ও কবর জিয়ারত"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f9f01b88-7c46-5aab-9c82-032cbabc6e4a', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'true_false', '{"en": "The deceased is laid in the grave facing the qiblah.", "bn": "মৃতকে কবরে কিবলামুখী করে শোয়ানো হয়।"}', '{"answer": true}', '{"en": "On the right side facing the qiblah — the unbroken practice of the Muslims.", "bn": "ডান কাতে কিবলামুখী — মুসলিমদের অবিচ্ছিন্ন আমল।"}', 'Ijma‘ (agreed practice)', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d1d47340-cea3-5fc1-b4ed-8d225d360f05', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'choice', '{"en": "What is said while placing the body in the grave?", "bn": "লাশ কবরে রাখার সময় কী বলা হয়?"}', '{"options": [{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Bismillah wa ‘ala millati Rasulillah", "bn": "বিসমিল্লাহি ওয়া আলা মিল্লাতি রাসুলিল্লাহ"}, {"en": "Amin", "bn": "আমিন"}, {"en": "Nothing", "bn": "কিছু না"}], "correct": 1}', '{"en": "\"In the name of Allah, and upon the way of the Messenger of Allah.\"", "bn": "\"আল্লাহর নামে এবং আল্লাহর রাসুলের আদর্শের ওপর।\""}', 'Sunan Abi Dawud 3213; Jami‘ at-Tirmidhi 1046', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('febb5627-5a1a-512e-8f9f-0ec38b454eaf', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'choice', '{"en": "After a burial, the Prophet ﷺ said: ask forgiveness for your brother and ask that he be made firm, for he is now…", "bn": "দাফনের পর নবী ﷺ বললেন: তোমাদের ভাইয়ের জন্য ক্ষমা চাও ও দৃঢ়তা চাও, কারণ এখন তাকে…"}', '{"options": [{"en": "…being questioned", "bn": "…প্রশ্ন করা হচ্ছে"}, {"en": "…asleep", "bn": "…ঘুমিয়ে আছে"}, {"en": "…travelling", "bn": "…সফর করছে"}, {"en": "…hearing poetry", "bn": "…কবিতা শুনছে"}], "correct": 0}', '{"en": "\"…for he is now being questioned.\"", "bn": "\"…কারণ এখন তাকে প্রশ্ন করা হচ্ছে।\""}', 'Sunan Abi Dawud 3221', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8c0d8727-7230-5352-b455-12103ef84130', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'true_false', '{"en": "The Prophet ﷺ forbade building over graves and plastering them.", "bn": "নবী ﷺ কবরের ওপর স্থাপনা বানাতে ও কবর পাকা করতে নিষেধ করেছেন।"}', '{"answer": true}', '{"en": "Jabir (RA): he forbade plastering graves, sitting on them and building over them.", "bn": "জাবির (রা.): তিনি কবর পাকা করা, তার ওপর বসা ও স্থাপনা নির্মাণ নিষেধ করেছেন।"}', 'Sahih Muslim 970', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9deb1e1f-e9ae-5518-9e17-1104248ec8a6', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'choice', '{"en": "What do we say on entering a graveyard?", "bn": "কবরস্থানে প্রবেশ করে কী বলি?"}', '{"options": [{"en": "As-salamu ‘alaykum ahlad-diyari minal-mu’minina wal-muslimin…", "bn": "আসসালামু আলাইকুম আহলাদ দিয়ারি মিনাল মুমিনিনা ওয়াল মুসলিমিন…"}, {"en": "The adhan", "bn": "আজান"}, {"en": "Happy greetings", "bn": "শুভেচ্ছা বাক্য"}, {"en": "Nothing at all", "bn": "কিছুই না"}], "correct": 0}', '{"en": "\"Peace be upon you, people of these dwellings, believers and Muslims; we will join you, if Allah wills…\"", "bn": "\"হে এই ঘরগুলোর মুমিন ও মুসলিম অধিবাসীরা, তোমাদের ওপর শান্তি; ইনশাআল্লাহ আমরাও তোমাদের সঙ্গে মিলিত হব…\""}', 'Sahih Muslim 975', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('047cc08e-0c2b-5399-9d0c-b350ba9d31ed', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'true_false', '{"en": "Visiting graves reminds us of death.", "bn": "কবর জিয়ারত মৃত্যুর কথা মনে করিয়ে দেয়।"}', '{"answer": true}', '{"en": "\"Visit the graves, for they remind you of death.\"", "bn": "\"কবর জিয়ারত করো, কারণ তা মৃত্যুর কথা মনে করিয়ে দেয়।\""}', 'Sahih Muslim 976', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('45a48262-ee73-5f7d-904f-9f5c095a0d4d', 'c06171b3-aabc-5a0e-b5d4-f1254efb3109', 'true_false', '{"en": "Wailing, slapping the cheeks and tearing clothes over the dead is allowed.", "bn": "মৃতের জন্য বিলাপ করা, গাল চাপড়ানো ও কাপড় ছেঁড়া জায়েজ।"}', '{"answer": false}', '{"en": "\"He is not one of us who slaps the cheeks, tears the clothes and calls out like the people of ignorance.\" Quiet tears are not blamed.", "bn": "\"যে গাল চাপড়ায়, কাপড় ছেঁড়ে ও জাহেলি যুগের মতো চিৎকার করে, সে আমাদের দলভুক্ত নয়।\" নীরবে কান্নায় দোষ নেই।"}', 'Sahih al-Bukhari 1294; Sahih al-Bukhari 1303', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_sections (id, category_id, title, description, sort_order) SELECT '4d89a642-10e5-52e6-8833-7f6ca53f4032', c.id, '{"en": "Worship in practice", "bn": "হাতে-কলমে ইবাদত"}', '{"en": "How to fast, pay zakat, perform Hajj and Umrah, and give qurbani.", "bn": "কীভাবে রোজা রাখবেন, যাকাত দেবেন, হজ-উমরাহ করবেন ও কুরবানি দেবেন।"}', 10 FROM is_learn_categories c WHERE c.id = '4ce48d4f-4467-5b13-85b1-16347c47309a' ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('ef7a91f0-1643-554a-b848-4998de4334e6', '{"en": "Learn to fast", "bn": "রোজা শিখি"}', '{"en": "A day of fasting, what breaks a fast and what does not, and voluntary fasts.", "bn": "রোজার একটি দিন, যা রোজা ভাঙে আর যা ভাঙে না, এবং নফল রোজা।"}', NULL, 'moon', 'in_review', 1, (SELECT s.id FROM is_learn_sections s WHERE s.id = '4d89a642-10e5-52e6-8833-7f6ca53f4032')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'ef7a91f0-1643-554a-b848-4998de4334e6', '{"en": "A day of fasting", "bn": "রোজার একটি দিন"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4438ced6-1dcf-5820-9675-15179d822f77', '7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'order', '{"en": "Put a day of fasting in order", "bn": "রোজার দিনটি ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Eat suhur before dawn", "bn": "সুবহে সাদিকের আগে সেহরি খাওয়া"}, {"en": "At true dawn (Fajr) the fast begins", "bn": "সুবহে সাদিক (ফজর) থেকে রোজা শুরু"}, {"en": "Hold back from food, drink and intimacy all day", "bn": "সারাদিন পানাহার ও স্ত্রী-সহবাস থেকে বিরত থাকা"}, {"en": "The sun sets: the fast ends", "bn": "সূর্য ডুবলে রোজা শেষ"}, {"en": "Break the fast (iftar), ideally with dates", "bn": "ইফতার করা, সম্ভব হলে খেজুর দিয়ে"}], "rtl": false}', '{"en": "\"…eat and drink until the white thread of dawn becomes distinct… then complete the fast until the night.\"", "bn": "\"…খাও ও পান করো যতক্ষণ না ভোরের সাদা রেখা স্পষ্ট হয়… তারপর রাত পর্যন্ত রোজা পূর্ণ করো।\""}', 'Quran 2:187', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3e6d09bb-30de-59d1-8dd3-6e38072be48f', '7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'true_false', '{"en": "Fasting Ramadan is obligatory on every adult, sane Muslim who is able.", "bn": "রমজানের রোজা প্রত্যেক প্রাপ্তবয়স্ক, সুস্থ মস্তিষ্ক, সক্ষম মুসলিমের ওপর ফরজ।"}', '{"answer": true}', '{"en": "\"So whoever of you witnesses the month, let him fast it.\"", "bn": "\"অতএব তোমাদের যে এ মাস পাবে, সে যেন রোজা রাখে।\""}', 'Quran 2:185', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b97e0bc6-6fb9-512a-9a1b-e2a059171905', '7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'fill', '{"en": "Complete the sentence", "bn": "বাক্যটি পূর্ণ করুন"}', '{"options": [{"en": "sunset", "bn": "সূর্যাস্ত"}, {"en": "midnight", "bn": "মধ্যরাত"}, {"en": "noon", "bn": "দুপুর"}, {"en": "Isha", "bn": "এশা"}], "correct": 0, "rtl": false, "before": {"en": "The fast lasts from true dawn until", "bn": "রোজা সুবহে সাদিক থেকে"}, "after": {"en": "", "bn": "পর্যন্ত"}}', '{"en": "\"…then complete the fast until the night\", which begins at sunset.", "bn": "\"…তারপর রাত পর্যন্ত রোজা পূর্ণ করো\" — রাত শুরু হয় সূর্যাস্তে।"}', 'Quran 2:187', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1834c3ed-ce6c-5936-8bf0-adc3db59365d', '7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'true_false', '{"en": "The Sunnah is to eat suhur late and to hurry the iftar.", "bn": "সুন্নাত হলো দেরিতে সেহরি খাওয়া এবং দ্রুত ইফতার করা।"}', '{"answer": true}', '{"en": "\"People will remain upon good as long as they hasten the iftar.\" Their suhur ended about fifty ayahs’ time before Fajr.", "bn": "\"মানুষ ততদিন কল্যাণে থাকবে যতদিন দ্রুত ইফতার করবে।\" তাঁদের সেহরি ফজরের প্রায় পঞ্চাশ আয়াত পড়ার সময় আগে শেষ হতো।"}', 'Sahih al-Bukhari 1957; Sahih al-Bukhari 1921', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5decfdf8-087a-56bd-8a00-48d0fcf98f34', '7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'choice', '{"en": "For children who have not yet reached puberty, fasting is…?", "bn": "যে শিশুরা এখনো প্রাপ্তবয়স্ক হয়নি, তাদের জন্য রোজা…?"}', '{"options": [{"en": "Not yet obligatory, but they may be trained gently", "bn": "এখনো ফরজ নয়, তবে ধীরে ধীরে অভ্যাস করানো যায়"}, {"en": "Obligatory every day", "bn": "প্রতিদিন ফরজ"}, {"en": "Forbidden", "bn": "নিষিদ্ধ"}, {"en": "Only on Eid", "bn": "শুধু ঈদের দিনে"}], "correct": 0}', '{"en": "The companions had their children fast and gave them toys of wool to distract them until iftar.", "bn": "সাহাবিরা শিশুদের রোজা রাখাতেন এবং ইফতার পর্যন্ত ভুলিয়ে রাখতে পশমের খেলনা দিতেন।"}', 'Sahih al-Bukhari 1960', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('390cd9ea-7f19-529e-8e2b-a2edf670ef05', '7ed1f419-cf47-5989-b6cf-c300c4f052c0', 'true_false', '{"en": "Laylat al-Qadr is in Ramadan.", "bn": "লাইলাতুল কদর রমজান মাসে।"}', '{"answer": true}', '{"en": "The Quran was sent down in Ramadan, on the Night of Decree.", "bn": "কুরআন রমজানে, কদরের রাতে নাজিল হয়েছে।"}', 'Quran 2:185; Quran 97:1', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'ef7a91f0-1643-554a-b848-4998de4334e6', '{"en": "What breaks a fast?", "bn": "কিসে রোজা ভাঙে?"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f2cfc4bb-8fcf-5376-961a-b6f4c1df6270', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'true_false', '{"en": "Eating or drinking forgetfully breaks the fast.", "bn": "ভুলে খেলে বা পান করলে রোজা ভেঙে যায়।"}', '{"answer": false}', '{"en": "\"Whoever forgets and eats or drinks, let him complete his fast; it is Allah who fed him.\"", "bn": "\"যে ভুলে খেয়ে বা পান করে ফেলে, সে যেন রোজা পূর্ণ করে; আল্লাহই তাকে খাইয়েছেন।\""}', 'Sahih al-Bukhari 1933', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bfdd3728-2c82-5101-a75a-acb17e259445', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'true_false', '{"en": "Eating or drinking on purpose during the day breaks the fast.", "bn": "দিনের বেলা ইচ্ছাকৃতভাবে খেলে বা পান করলে রোজা ভেঙে যায়।"}', '{"answer": true}', '{"en": "The fast is holding back from these from dawn to sunset.", "bn": "ভোর থেকে সূর্যাস্ত পর্যন্ত এগুলো থেকে বিরত থাকাই রোজা।"}', 'Quran 2:187', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a31ef963-cfa2-5929-9c5f-cd7d344332a0', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'true_false', '{"en": "Brushing the teeth with a miswak does not break the fast.", "bn": "মিসওয়াক করলে রোজা ভাঙে না।"}', '{"answer": true}', '{"en": "‘Amir ibn Rabi‘ah (RA) saw the Prophet ﷺ use the miswak while fasting more times than he could count.", "bn": "আমির ইবনে রাবিআ (রা.) নবী ﷺ-কে রোজা অবস্থায় অগণিতবার মিসওয়াক করতে দেখেছেন।"}', 'Jami‘ at-Tirmidhi 725', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bb831ab7-fbcc-5598-90eb-555ff8a834bf', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'true_false', '{"en": "Waking up in janabah (needing ghusl) means that day’s fast is lost.", "bn": "জানাবাত অবস্থায় (গোসল ফরজ অবস্থায়) ঘুম থেকে উঠলে সেদিনের রোজা হয় না।"}', '{"answer": false}', '{"en": "He ﷺ sometimes woke at Fajr in janabah in Ramadan, did ghusl and fasted.", "bn": "নবী ﷺ কখনো রমজানে জানাবাত অবস্থায় ফজরে জেগে গোসল করে রোজা রেখেছেন।"}', 'Sahih al-Bukhari 1925–1926', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a7e39d45-f588-5c1b-817c-3ae1ca2b1300', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'true_false', '{"en": "If menstruation begins during the day, that day is not counted and is made up later.", "bn": "দিনের বেলা ঋতুস্রাব শুরু হলে সেদিনের রোজা গণ্য হয় না, পরে কাজা করতে হয়।"}', '{"answer": true}', '{"en": "‘A’ishah (RA): \"We were ordered to make up the fasts.\"", "bn": "আয়েশা (রা.): \"আমাদের রোজা কাজা করার নির্দেশ দেওয়া হতো।\""}', 'Sahih Muslim 335', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e4616a9d-fffd-5650-ba09-155ea4b3a75f', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'true_false', '{"en": "Swallowing one’s own saliva breaks the fast.", "bn": "নিজের থুথু গিলে ফেললে রোজা ভেঙে যায়।"}', '{"answer": false}', '{"en": "Saliva cannot be avoided and does not break the fast.", "bn": "থুথু এড়ানো যায় না, এতে রোজা ভাঙে না।"}', 'Ijma‘ (scholarly agreement)', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b7148ed4-1514-53a0-bff1-a45e6aa82c46', 'd734f7a4-3f5f-5720-9a80-d191e4a6ba65', 'choice', '{"en": "A fasting person is insulted. What should he say?", "bn": "রোজাদারকে কেউ গালি দিলে সে কী বলবে?"}', '{"options": [{"en": "Insult him back", "bn": "পাল্টা গালি"}, {"en": "\"I am fasting\"", "bn": "\"আমি রোজাদার\""}, {"en": "Nothing ever", "bn": "কখনো কিছু না"}, {"en": "\"I break my fast\"", "bn": "\"আমি রোজা ভেঙে দিলাম\""}], "correct": 1}', '{"en": "Fasting is a shield: no foul talk or quarrelling.", "bn": "রোজা ঢাল: অশ্লীল কথা বা ঝগড়া নয়।"}', 'Sahih al-Bukhari 1904', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'ef7a91f0-1643-554a-b848-4998de4334e6', '{"en": "Voluntary fasts", "bn": "নফল রোজা"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c9123545-6a1c-504c-98c2-373ae254d8b4', 'c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'match', '{"en": "Match each fast to its virtue", "bn": "প্রতিটি রোজার ফজিলত মেলান"}', '{"pairs": [{"left": {"en": "Day of Arafah", "bn": "আরাফার দিন"}, "right": {"en": "Expiates the year before and after", "bn": "আগের ও পরের বছরের কাফফারা"}}, {"left": {"en": "Ashura", "bn": "আশুরা"}, "right": {"en": "Expiates the year before", "bn": "আগের বছরের কাফফারা"}}, {"left": {"en": "Six days of Shawwal", "bn": "শাওয়ালের ছয় রোজা"}, "right": {"en": "With Ramadan, like a whole year", "bn": "রমজানসহ সারা বছরের মতো"}}, {"left": {"en": "Monday", "bn": "সোমবার"}, "right": {"en": "The day he ﷺ was born", "bn": "যেদিন নবী ﷺ জন্মগ্রহণ করেছেন"}}]}', '{"en": "All from Sahih Muslim.", "bn": "সবগুলো সহিহ মুসলিম থেকে।"}', 'Sahih Muslim 1162; Sahih Muslim 1164', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7eabed4b-ffb2-5d60-b9de-c89a9820a35a', 'c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'choice', '{"en": "The \"white days\" for fasting are which dates of each Hijri month?", "bn": "\"আইয়ামে বীজ\"-এর রোজা প্রতি হিজরি মাসের কোন তারিখে?"}', '{"options": [{"en": "13, 14, 15", "bn": "১৩, ১৪, ১৫"}, {"en": "1, 2, 3", "bn": "১, ২, ৩"}, {"en": "20, 21, 22", "bn": "২০, ২১, ২২"}, {"en": "27, 28, 29", "bn": "২৭, ২৮, ২৯"}], "correct": 0}', '{"en": "The nights of the full moon.", "bn": "পূর্ণিমার রাতগুলোর দিন।"}', 'Jami‘ at-Tirmidhi 761', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('02b2c980-55bd-51b2-bea6-3a7c28543d02', 'c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'true_false', '{"en": "The Prophet ﷺ liked to fast on Mondays and Thursdays because deeds are presented then.", "bn": "আমল পেশ করা হয় বলে নবী ﷺ সোম ও বৃহস্পতিবার রোজা রাখতে পছন্দ করতেন।"}', '{"answer": true}', '{"en": "\"Deeds are presented on Monday and Thursday, and I like my deeds to be presented while I am fasting.\"", "bn": "\"সোম ও বৃহস্পতিবার আমল পেশ করা হয়, আর আমি চাই রোজা অবস্থায় আমার আমল পেশ হোক।\""}', 'Jami‘ at-Tirmidhi 747', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c3a120cb-fed9-503b-b413-4c4b586ef16a', 'c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'true_false', '{"en": "Fasting on the day of Eid al-Fitr is recommended.", "bn": "ঈদুল ফিতরের দিন রোজা রাখা মুস্তাহাব।"}', '{"answer": false}', '{"en": "He ﷺ forbade fasting on the two days of Eid.", "bn": "নবী ﷺ দুই ঈদের দিনে রোজা রাখতে নিষেধ করেছেন।"}', 'Sahih al-Bukhari 1991', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5708b968-9591-520a-897b-072b453f0202', 'c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'choice', '{"en": "How did Prophet Dawud (AS) fast?", "bn": "দাউদ (আ.) কীভাবে রোজা রাখতেন?"}', '{"options": [{"en": "Every day", "bn": "প্রতিদিন"}, {"en": "One day on, one day off", "bn": "একদিন রোজা, একদিন বিরতি"}, {"en": "Only on Fridays", "bn": "শুধু শুক্রবার"}, {"en": "Once a year", "bn": "বছরে একবার"}], "correct": 1}', '{"en": "\"The most beloved fasting to Allah is that of Dawud: he fasted a day and broke the next.\"", "bn": "\"আল্লাহর কাছে সবচেয়ে প্রিয় রোজা দাউদের রোজা: একদিন রাখতেন, একদিন রাখতেন না।\""}', 'Sahih al-Bukhari 3420', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3377720d-5175-5120-bab3-fc801af54533', 'c1a6d077-9dfc-5a37-bbcd-815771f1db3f', 'choice', '{"en": "For Ashura, which days did the Prophet ﷺ intend to fast?", "bn": "আশুরার জন্য নবী ﷺ কোন দিনগুলোতে রোজার ইচ্ছা করেছিলেন?"}', '{"options": [{"en": "The 10th of Muharram, and the 9th as well", "bn": "মহররমের ১০ তারিখ, সঙ্গে ৯ তারিখও"}, {"en": "The 1st of Muharram only", "bn": "শুধু মহররমের ১ তারিখ"}, {"en": "The whole of Muharram", "bn": "পুরো মহররম"}, {"en": "The 15th of Sha‘ban", "bn": "শাবানের ১৫ তারিখ"}], "correct": 0}', '{"en": "\"If I live until next year I will fast the ninth (too).\"", "bn": "\"আগামী বছর বেঁচে থাকলে নবম তারিখেও রোজা রাখব।\""}', 'Sahih Muslim 1134', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('2935b7cc-24c9-5810-a65a-8867e20aa487', '{"en": "Learn zakat", "bn": "যাকাত শিখি"}', '{"en": "Who pays and how much, who receives it, and Sadaqat al-Fitr.", "bn": "কে দেবে ও কত, কারা পাবে, এবং সদকাতুল ফিতর।"}', NULL, 'coins', 'in_review', 2, (SELECT s.id FROM is_learn_sections s WHERE s.id = '4d89a642-10e5-52e6-8833-7f6ca53f4032')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('fe9531c6-e0f2-56a4-8578-a6cd77bacca5', '2935b7cc-24c9-5810-a65a-8867e20aa487', '{"en": "Who pays, and how much", "bn": "কে দেবে, কত দেবে"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('81d9868e-0b63-534b-b49d-b0f0d24cf8b2', 'fe9531c6-e0f2-56a4-8578-a6cd77bacca5', 'true_false', '{"en": "Zakat is due on savings that reach the nisab and stay with you for a full lunar year.", "bn": "সঞ্চয় নিসাব পরিমাণ হয়ে পূর্ণ এক চান্দ্রবছর থাকলে যাকাত ফরজ হয়।"}', '{"answer": true}', '{"en": "\"No zakat is due on wealth until a year has passed over it.\"", "bn": "\"এক বছর অতিক্রম না করা পর্যন্ত সম্পদে যাকাত নেই।\""}', 'Sunan Abi Dawud 1573', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7b4d5361-3b23-54fa-b739-6ef02ea1db4e', 'fe9531c6-e0f2-56a4-8578-a6cd77bacca5', 'fill', '{"en": "Complete the rule", "bn": "নিয়মটি পূর্ণ করুন"}', '{"options": [{"en": "2.5", "bn": "২.৫"}, {"en": "10", "bn": "১০"}, {"en": "5", "bn": "৫"}, {"en": "20", "bn": "২০"}], "correct": 0, "rtl": false, "before": {"en": "Zakat on cash savings is", "bn": "নগদ সঞ্চয়ের যাকাত"}, "after": {"en": "percent.", "bn": "শতাংশ।"}}', '{"en": "One fortieth: \"on two hundred dirhams, five dirhams.\"", "bn": "চল্লিশ ভাগের এক ভাগ: \"দুইশো দিরহামে পাঁচ দিরহাম।\""}', 'Sunan Abi Dawud 1573', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('654ccc2c-3b4e-55b6-8a63-adddb49a82cb', 'fe9531c6-e0f2-56a4-8578-a6cd77bacca5', 'choice', '{"en": "Rahim has had 2,00,000 taka in savings, above the nisab, for a full year. His zakat is…?", "bn": "রহিমের এক বছর ধরে নিসাবের ওপরে ২,০০,০০০ টাকা সঞ্চয় আছে। তার যাকাত কত?"}', '{"options": [{"en": "500 taka", "bn": "৫০০ টাকা"}, {"en": "5,000 taka", "bn": "৫,০০০ টাকা"}, {"en": "20,000 taka", "bn": "২০,০০০ টাকা"}, {"en": "50,000 taka", "bn": "৫০,০০০ টাকা"}], "correct": 1}', '{"en": "2,00,000 × 2.5% = 5,000 taka.", "bn": "২,০০,০০০ × ২.৫% = ৫,০০০ টাকা।"}', 'Sunan Abi Dawud 1573', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b65abdc5-369d-54cc-adb5-c92a0bae392f', 'fe9531c6-e0f2-56a4-8578-a6cd77bacca5', 'choice', '{"en": "The gold nisab of 20 dinars is about how much gold today?", "bn": "২০ দিনার স্বর্ণের নিসাব আজকের হিসাবে প্রায় কত?"}', '{"options": [{"en": "About 10 g", "bn": "প্রায় ১০ গ্রাম"}, {"en": "About 85–87.5 g", "bn": "প্রায় ৮৫–৮৭.৫ গ্রাম (সাড়ে সাত তোলা)"}, {"en": "About 1 kg", "bn": "প্রায় ১ কেজি"}, {"en": "About 500 g", "bn": "প্রায় ৫০০ গ্রাম"}], "correct": 1}', '{"en": "Scholars convert 20 mithqal to about 85–87.5 g (7.5 tola); the silver nisab (200 dirhams) is about 595–612 g (52.5 tola).", "bn": "আলেমগণ ২০ মিসকালকে প্রায় ৮৫–৮৭.৫ গ্রাম (সাড়ে সাত তোলা) ধরেন; রুপার নিসাব (২০০ দিরহাম) প্রায় ৫৯৫–৬১২ গ্রাম (সাড়ে বাহান্ন তোলা)।"}', 'Sunan Abi Dawud 1573', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('90333b76-b8c5-5a60-a327-986dd587bdda', 'fe9531c6-e0f2-56a4-8578-a6cd77bacca5', 'true_false', '{"en": "Zakat is due on the car you use for yourself.", "bn": "নিজে ব্যবহারের গাড়িতে যাকাত দিতে হয়।"}', '{"answer": false}', '{"en": "Things kept for personal use are exempt: \"No zakat on a Muslim’s slave or his horse.\"", "bn": "ব্যক্তিগত ব্যবহারের জিনিসে যাকাত নেই: \"মুসলিমের দাস ও ঘোড়ায় যাকাত নেই।\""}', 'Sahih al-Bukhari 1464', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e59d8832-90a6-543b-a609-79792d76d196', 'fe9531c6-e0f2-56a4-8578-a6cd77bacca5', 'true_false', '{"en": "Zakat purifies the wealth and the soul of the giver.", "bn": "যাকাত দাতার সম্পদ ও অন্তরকে পবিত্র করে।"}', '{"answer": true}', '{"en": "\"Take from their wealth a charity by which you purify them and cause them to grow.\"", "bn": "\"তাদের সম্পদ থেকে সদকা গ্রহণ করুন, যা দ্বারা আপনি তাদের পবিত্র ও পরিশুদ্ধ করবেন।\""}', 'Quran 9:103', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('aaabea8b-4135-57c0-b6a8-59cd93f0a926', '2935b7cc-24c9-5810-a65a-8867e20aa487', '{"en": "Who receives zakat", "bn": "যাকাত কারা পাবে"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9a13dfee-3f31-5867-beb1-9a5118b8a3d9', 'aaabea8b-4135-57c0-b6a8-59cd93f0a926', 'choice', '{"en": "Which ayah lists those who may receive zakat?", "bn": "কোন আয়াতে যাকাতের হকদারদের তালিকা আছে?"}', '{"options": [{"en": "At-Tawbah 9:60", "bn": "আত-তাওবা ৯:৬০"}, {"en": "Al-Baqarah 2:255", "bn": "আল-বাকারা ২:২৫৫"}, {"en": "Yasin 36:1", "bn": "ইয়াসিন ৩৬:১"}, {"en": "Al-Mulk 67:1", "bn": "আল-মুলক ৬৭:১"}], "correct": 0}', '{"en": "\"Zakat is only for the poor, the needy, those who work on it…\"", "bn": "\"যাকাত কেবল ফকির, মিসকিন, যাকাত আদায়কারী…-দের জন্য\""}', 'Quran 9:60', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6bc415ae-46fa-5a6b-b2b1-91878d857d92', 'aaabea8b-4135-57c0-b6a8-59cd93f0a926', 'match', '{"en": "Match each group in 9:60 to its meaning", "bn": "৯:৬০-এর প্রতিটি খাতের অর্থ মেলান"}', '{"pairs": [{"left": {"en": "Al-fuqara’", "bn": "ফুকারা"}, "right": {"en": "The poor", "bn": "দরিদ্র"}}, {"left": {"en": "Al-gharimin", "bn": "গারিমিন"}, "right": {"en": "Those in debt", "bn": "ঋণগ্রস্ত"}}, {"left": {"en": "Ibn as-sabil", "bn": "ইবনুস সাবিল"}, "right": {"en": "The stranded traveller", "bn": "বিপদগ্রস্ত মুসাফির"}}, {"left": {"en": "Al-‘amilina ‘alayha", "bn": "আমিলিনা আলাইহা"}, "right": {"en": "Those who collect it", "bn": "যাকাত আদায়ের কর্মী"}}, {"left": {"en": "Fir-riqab", "bn": "ফির রিকাব"}, "right": {"en": "Freeing captives", "bn": "দাস ও বন্দি মুক্তি"}}]}', '{"en": "Five of the eight groups named in the ayah.", "bn": "আয়াতে উল্লিখিত আট খাতের পাঁচটি।"}', 'Quran 9:60', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('61c24946-f9fb-5bfc-92b3-ed093182519e', 'aaabea8b-4135-57c0-b6a8-59cd93f0a926', 'choice', '{"en": "How many groups does 9:60 name?", "bn": "৯:৬০ আয়াতে কয়টি খাতের কথা আছে?"}', '{"options": [{"en": "4", "bn": "৪"}, {"en": "6", "bn": "৬"}, {"en": "8", "bn": "৮"}, {"en": "10", "bn": "১০"}], "correct": 2}', '{"en": "The poor, the needy, its workers, those whose hearts are to be won, captives, debtors, in Allah’s way, and the traveller.", "bn": "ফকির, মিসকিন, আদায়কারী, মন জয়ের জন্য যাদের দেওয়া হয়, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে ও মুসাফির।"}', 'Quran 9:60', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2e7caccc-cb16-5704-8b97-ad13159ad918', 'aaabea8b-4135-57c0-b6a8-59cd93f0a926', 'true_false', '{"en": "A person may give his zakat to his own parents.", "bn": "নিজের বাবা-মাকে যাকাত দেওয়া যায়।"}', '{"answer": false}', '{"en": "Supporting one’s parents is already a duty, so scholars agree zakat does not go to them.", "bn": "বাবা-মায়ের ভরণপোষণ এমনিতেই দায়িত্ব, তাই আলেমগণ একমত যে তাঁদের যাকাত দেওয়া যায় না।"}', 'Ibn al-Mundhir, al-Ijma‘', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a7cb9cf6-9e45-502b-b1cc-60d9259889ef', 'aaabea8b-4135-57c0-b6a8-59cd93f0a926', 'true_false', '{"en": "Zakat may be used to help someone who cannot pay his debts.", "bn": "ঋণ শোধে অক্ষম ব্যক্তিকে যাকাত দিয়ে সাহায্য করা যায়।"}', '{"answer": true}', '{"en": "Al-gharimin, those in debt, are one of the eight groups.", "bn": "আল-গারিমিন বা ঋণগ্রস্তরা আট খাতের একটি।"}', 'Quran 9:60', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e8bcb58e-e8ec-5299-91ae-f6e4a63a95ff', 'aaabea8b-4135-57c0-b6a8-59cd93f0a926', 'true_false', '{"en": "Giving charity secretly to the poor is better for you, though giving openly is also good.", "bn": "গরিবকে গোপনে দান করা তোমার জন্য উত্তম, যদিও প্রকাশ্যে দানও ভালো।"}', '{"answer": true}', '{"en": "\"If you show your charities, that is good; but if you hide them and give them to the poor, it is better for you.\"", "bn": "\"তোমরা প্রকাশ্যে দান করলে তা ভালো; আর গোপনে অভাবীদের দিলে তা তোমাদের জন্য আরও উত্তম।\""}', 'Quran 2:271', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3b31cdf7-b161-5467-918c-24e83b971f56', '2935b7cc-24c9-5810-a65a-8867e20aa487', '{"en": "Sadaqat al-Fitr & charity", "bn": "সদকাতুল ফিতর ও দান"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0f20c37a-0c48-50e9-bd3b-2cdae9d56dba', '3b31cdf7-b161-5467-918c-24e83b971f56', 'true_false', '{"en": "Sadaqat al-Fitr is given before the Eid prayer.", "bn": "সদকাতুল ফিতর ঈদের নামাজের আগে দিতে হয়।"}', '{"answer": true}', '{"en": "He ﷺ ordered it to be given before people went out to the prayer.", "bn": "মানুষ নামাজে বের হওয়ার আগে তা আদায় করার নির্দেশ দিয়েছেন।"}', 'Sahih al-Bukhari 1503', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('70cde727-fda6-57db-a1bb-201771774a14', '3b31cdf7-b161-5467-918c-24e83b971f56', 'choice', '{"en": "Who pays the Sadaqat al-Fitr of a small child?", "bn": "ছোট শিশুর সদকাতুল ফিতর কে দেবে?"}', '{"options": [{"en": "The child, when grown up", "bn": "শিশু নিজে, বড় হয়ে"}, {"en": "The one who supports the child, e.g. the father", "bn": "যিনি শিশুর ভরণপোষণ করেন, যেমন বাবা"}, {"en": "No one", "bn": "কেউ না"}, {"en": "The neighbours", "bn": "প্রতিবেশীরা"}], "correct": 1}', '{"en": "It is due \"on the young and the old\"; the guardian pays it for those he supports.", "bn": "এটি \"ছোট-বড় সবার ওপর\"; অভিভাবক তার পোষ্যদের পক্ষ থেকে আদায় করেন।"}', 'Sahih al-Bukhari 1503', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('be99c1d3-e4cd-5dd3-b7d0-c4407a96a9b2', '3b31cdf7-b161-5467-918c-24e83b971f56', 'choice', '{"en": "What is Sadaqat al-Fitr for, according to the hadith?", "bn": "হাদিস অনুযায়ী সদকাতুল ফিতরের উদ্দেশ্য কী?"}', '{"options": [{"en": "To decorate the masjid", "bn": "মসজিদ সাজানো"}, {"en": "To pay the imam", "bn": "ইমামের বেতন"}, {"en": "To purify the fasting person from idle talk and to feed the poor", "bn": "রোজাদারকে অনর্থক কথা থেকে পবিত্র করা ও গরিবদের খাওয়ানো"}, {"en": "To buy new clothes", "bn": "নতুন জামা কেনা"}], "correct": 2}', '{"en": "Ibn ‘Abbas (RA): \"…a purification for the fasting person from idle and obscene talk, and food for the poor.\"", "bn": "ইবনে আব্বাস (রা.): \"…রোজাদারের অনর্থক ও অশ্লীল কথা থেকে পবিত্রতা এবং মিসকিনদের খাবার।\""}', 'Sunan Abi Dawud 1609', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('03d958d1-8c74-566a-b7a4-067cc76e1067', '3b31cdf7-b161-5467-918c-24e83b971f56', 'true_false', '{"en": "Every good deed is a charity.", "bn": "প্রতিটি ভালো কাজই সদকা।"}', '{"answer": true}', '{"en": "\"Every good deed (ma‘ruf) is a charity.\"", "bn": "\"প্রতিটি সৎকাজ সদকা।\""}', 'Sahih al-Bukhari 6021', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f6bd1956-0a8d-5284-a03b-31f6302f5324', '3b31cdf7-b161-5467-918c-24e83b971f56', 'choice', '{"en": "When a person dies, his deeds end except three. Sadaqah jariyah, beneficial knowledge and…?", "bn": "মানুষ মারা গেলে তিনটি ছাড়া তার আমল বন্ধ হয়ে যায়: সদকায়ে জারিয়া, উপকারী জ্ঞান এবং…?"}', '{"options": [{"en": "A big house", "bn": "একটি বড় বাড়ি"}, {"en": "A famous name", "bn": "খ্যাতি"}, {"en": "Gold", "bn": "স্বর্ণ"}, {"en": "A righteous child who prays for him", "bn": "নেক সন্তান, যে তার জন্য দোয়া করে"}], "correct": 3}', '{"en": "The three that continue after death.", "bn": "মৃত্যুর পরও যে তিনটি চলতে থাকে।"}', 'Sahih Muslim 1631', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b11d3dcc-aece-5514-88c6-b7fa69fbf18e', '3b31cdf7-b161-5467-918c-24e83b971f56', 'true_false', '{"en": "Giving charity decreases wealth.", "bn": "দান করলে সম্পদ কমে যায়।"}', '{"answer": false}', '{"en": "\"Charity does not decrease wealth.\"", "bn": "\"দান সম্পদ কমায় না।\""}', 'Sahih Muslim 2588', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('9931cc22-bb22-5e79-b6cf-fdeff75bfc17', '{"en": "Learn Hajj & Umrah", "bn": "হজ ও উমরাহ শিখি"}', '{"en": "Ihram and the talbiyah, the steps of Umrah, and the days of Hajj.", "bn": "ইহরাম ও তালবিয়া, উমরাহর ধাপ এবং হজের দিনগুলো।"}', NULL, 'landmark', 'in_review', 3, (SELECT s.id FROM is_learn_sections s WHERE s.id = '4d89a642-10e5-52e6-8833-7f6ca53f4032')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d728853b-9385-5cf7-8c02-b1f73c153239', '9931cc22-bb22-5e79-b6cf-fdeff75bfc17', '{"en": "Ihram & the talbiyah", "bn": "ইহরাম ও তালবিয়া"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d3faffc0-209b-548e-9e2f-394ae37be24d', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'choice', '{"en": "What does a man wear in ihram?", "bn": "ইহরামে পুরুষ কী পরেন?"}', '{"options": [{"en": "Two unstitched sheets: an izar and a rida’", "bn": "দুটি সেলাইবিহীন চাদর: লুঙ্গির মতো ইজার ও গায়ের চাদর রিদা"}, {"en": "A shirt and trousers", "bn": "জামা ও প্যান্ট"}, {"en": "A turban and cloak", "bn": "পাগড়ি ও জোব্বা"}, {"en": "Anything he likes", "bn": "যা খুশি"}], "correct": 0}', '{"en": "He ﷺ set out from Madinah in an izar and a rida’; men do not wear shirts, turbans, trousers or hooded cloaks in ihram.", "bn": "নবী ﷺ ইজার ও রিদা পরে মদিনা থেকে রওনা দেন; ইহরামে পুরুষ জামা, পাগড়ি, পায়জামা বা টুপিওয়ালা জোব্বা পরে না।"}', 'Sahih al-Bukhari 1545; Sahih al-Bukhari 1542', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b3f98f8c-fda0-559f-8c65-77f204f42815', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'true_false', '{"en": "Men cover their heads in ihram.", "bn": "ইহরামে পুরুষরা মাথা ঢেকে রাখেন।"}', '{"answer": false}', '{"en": "Turbans and caps are among the things a man in ihram does not wear.", "bn": "ইহরামে পুরুষ পাগড়ি বা টুপি পরে না।"}', 'Sahih al-Bukhari 1542', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bec30183-8a37-5120-9d44-2a789667895e', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'true_false', '{"en": "A woman in ihram wears her ordinary modest clothes, but not the niqab or gloves.", "bn": "ইহরামে নারী তাঁর সাধারণ শালীন পোশাক পরেন, তবে নিকাব ও হাতমোজা নয়।"}', '{"answer": true}', '{"en": "\"The woman in ihram does not wear the niqab or gloves.\"", "bn": "\"ইহরামধারী নারী নিকাব ও হাতমোজা পরবে না।\""}', 'Sahih al-Bukhari 1838', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6b7ac2cd-c933-5ee0-93fa-cf9c8d632dd1', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'order', '{"en": "Put the talbiyah in order", "bn": "তালবিয়া ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Labbayk Allahumma labbayk", "bn": "লাব্বাইক আল্লাহুম্মা লাব্বাইক"}, {"en": "Labbayka la sharika laka labbayk", "bn": "লাব্বাইকা লা শারিকা লাকা লাব্বাইক"}, {"en": "Innal-hamda wan-ni‘mata laka wal-mulk", "bn": "ইন্নাল হামদা ওয়ান নি‘মাতা লাকা ওয়াল মুলক"}, {"en": "La sharika lak", "bn": "লা শারিকা লাক"}], "rtl": false}', '{"en": "The talbiyah of the Prophet ﷺ, as Ibn ‘Umar (RA) reported it.", "bn": "ইবনে উমর (রা.) বর্ণিত নবীজির ﷺ তালবিয়া।"}', 'Sahih al-Bukhari 1549', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fed19bea-ad7e-570e-9e60-1864b3946bb3', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'match', '{"en": "Match each part of the talbiyah to its meaning", "bn": "তালবিয়ার প্রতিটি অংশের অর্থ মেলান"}', '{"pairs": [{"left": {"en": "Labbayk", "bn": "লাব্বাইক"}, "right": {"en": "Here I am, at Your service", "bn": "আমি হাজির, আপনার খেদমতে"}}, {"left": {"en": "La sharika lak", "bn": "লা শারিকা লাক"}, "right": {"en": "You have no partner", "bn": "আপনার কোনো শরিক নেই"}}, {"left": {"en": "Innal-hamda wan-ni‘mata lak", "bn": "ইন্নাল হামদা ওয়ান নি‘মাতা লাক"}, "right": {"en": "All praise and blessings are Yours", "bn": "সব প্রশংসা ও নিয়ামত আপনারই"}}, {"left": {"en": "Wal-mulk", "bn": "ওয়াল মুলক"}, "right": {"en": "And the dominion", "bn": "এবং সার্বভৌমত্বও"}}]}', '{"en": "The pilgrim answers Allah’s call.", "bn": "হাজি আল্লাহর ডাকে সাড়া দেন।"}', 'Sahih al-Bukhari 1549', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e3bcf0c8-00ed-5fcd-a8b3-aea3edc725ce', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'true_false', '{"en": "Using perfume after entering ihram is allowed.", "bn": "ইহরাম বাঁধার পর সুগন্ধি ব্যবহার জায়েজ।"}', '{"answer": false}', '{"en": "Clothes touched by saffron or wars (scents) are among what the muhrim avoids.", "bn": "জাফরান বা ওয়ারস (সুগন্ধি) লাগানো কাপড় ইহরামধারী এড়িয়ে চলেন।"}', 'Sahih al-Bukhari 1542', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9b6e2bf0-7e9a-5385-ae3f-62986266cd75', 'd728853b-9385-5cf7-8c02-b1f73c153239', 'true_false', '{"en": "Hunting land animals is forbidden in ihram.", "bn": "ইহরাম অবস্থায় স্থলের প্রাণী শিকার নিষিদ্ধ।"}', '{"answer": true}', '{"en": "\"Do not kill game while you are in ihram.\"", "bn": "\"ইহরাম অবস্থায় তোমরা শিকার বধ কোরো না।\""}', 'Quran 5:95', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('009c696a-8946-5ab1-9c63-a6dd2836b295', '9931cc22-bb22-5e79-b6cf-fdeff75bfc17', '{"en": "The steps of Umrah", "bn": "উমরাহর ধাপ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('96b33a78-b455-5cd0-86a8-e5c42d94d56f', '009c696a-8946-5ab1-9c63-a6dd2836b295', 'order', '{"en": "Put the steps of Umrah in order", "bn": "উমরাহর ধাপগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Enter ihram at the miqat", "bn": "মিকাত থেকে ইহরাম বাঁধা"}, {"en": "Tawaf: seven rounds of the Ka‘bah", "bn": "তাওয়াফ: কাবার চারপাশে সাত চক্কর"}, {"en": "Pray two rak‘ahs (behind Maqam Ibrahim if possible)", "bn": "দুই রাকাত নামাজ (সম্ভব হলে মাকামে ইবরাহিমের পেছনে)"}, {"en": "Sa‘i: seven trips between Safa and Marwah", "bn": "সাঈ: সাফা-মারওয়ায় সাত চক্কর"}, {"en": "Shave or shorten the hair", "bn": "মাথা মুণ্ডন বা চুল ছোট করা"}], "rtl": false}', '{"en": "As in the Prophet’s ﷺ Umrah and Hajj described by Jabir (RA).", "bn": "জাবির (রা.) বর্ণিত নবীজির ﷺ উমরাহ ও হজের মতো।"}', 'Sahih Muslim 1218', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ee656ad5-6563-5819-aea9-b3b5671513d7', '009c696a-8946-5ab1-9c63-a6dd2836b295', 'choice', '{"en": "From where does each tawaf begin?", "bn": "প্রতিটি তাওয়াফ কোথা থেকে শুরু হয়?"}', '{"options": [{"en": "The Black Stone corner", "bn": "হাজরে আসওয়াদের কোণ"}, {"en": "The door of the Ka‘bah", "bn": "কাবার দরজা"}, {"en": "Zamzam", "bn": "জমজম"}, {"en": "Safa", "bn": "সাফা"}], "correct": 0}', '{"en": "He ﷺ touched the Black Stone corner and began.", "bn": "নবী ﷺ হাজরে আসওয়াদের কোণ স্পর্শ করে শুরু করলেন।"}', 'Sahih Muslim 1218', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2067f545-9ec0-5508-836c-774b39d7ce23', '009c696a-8946-5ab1-9c63-a6dd2836b295', 'true_false', '{"en": "In tawaf the Ka‘bah is kept on your left.", "bn": "তাওয়াফে কাবা বাম দিকে থাকে।"}', '{"answer": true}', '{"en": "Walking anticlockwise, with the House on the left, as he ﷺ did.", "bn": "নবীজির ﷺ মতো ঘড়ির কাঁটার উল্টো দিকে হাঁটা, কাবা বাম পাশে রেখে।"}', 'Sahih Muslim 1218', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e5e985fb-4c82-59bc-8ca6-1365e204b35e', '009c696a-8946-5ab1-9c63-a6dd2836b295', 'choice', '{"en": "Sa‘i begins at…?", "bn": "সাঈ কোথা থেকে শুরু হয়?"}', '{"options": [{"en": "Marwah", "bn": "মারওয়া"}, {"en": "Safa", "bn": "সাফা"}, {"en": "Mina", "bn": "মিনা"}, {"en": "Arafat", "bn": "আরাফাত"}], "correct": 1}', '{"en": "\"I begin with what Allah began with\" — as-Safa.", "bn": "\"আল্লাহ যা দিয়ে শুরু করেছেন আমিও তা দিয়ে শুরু করছি\" — সাফা।"}', 'Quran 2:158; Sahih Muslim 1218', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c5243c77-4fb7-51f2-82b0-d58da9643357', '009c696a-8946-5ab1-9c63-a6dd2836b295', 'true_false', '{"en": "Zamzam water is for whatever it is drunk for.", "bn": "জমজমের পানি যে উদ্দেশ্যে পান করা হয়, তার জন্যই।"}', '{"answer": true}', '{"en": "\"The water of Zamzam is for whatever it is drunk for.\" Drink it and make dua.", "bn": "\"জমজমের পানি যে নিয়তে পান করা হয় তার জন্য।\" পান করে দোয়া করুন।"}', 'Sunan Ibn Majah 3062', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c26689c6-865d-5a7c-8f22-43f9a9c59ef8', '009c696a-8946-5ab1-9c63-a6dd2836b295', 'true_false', '{"en": "Umrah can only be done in Ramadan.", "bn": "উমরাহ শুধু রমজানেই করা যায়।"}', '{"answer": false}', '{"en": "Umrah may be done any time; an Umrah in Ramadan is equal (in reward) to a Hajj.", "bn": "উমরাহ যেকোনো সময় করা যায়; রমজানের উমরাহ (সওয়াবে) একটি হজের সমান।"}', 'Sahih al-Bukhari 1782', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('99e7160f-4ef9-56bd-98f7-6f27e2696a12', '9931cc22-bb22-5e79-b6cf-fdeff75bfc17', '{"en": "The days of Hajj", "bn": "হজের দিনগুলো"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c01d230f-7877-5477-a9fb-32d8ca76095e', '99e7160f-4ef9-56bd-98f7-6f27e2696a12', 'order', '{"en": "Put the days of Hajj in order", "bn": "হজের দিনগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "8th: go to Mina", "bn": "৮ তারিখ: মিনায় যাওয়া"}, {"en": "9th: stand at Arafah", "bn": "৯ তারিখ: আরাফায় অবস্থান"}, {"en": "Night: Muzdalifah", "bn": "রাতে: মুজদালিফা"}, {"en": "10th: stone Jamrat al-‘Aqabah, sacrifice, shave, Tawaf al-Ifadah", "bn": "১০ তারিখ: জামরাতুল আকাবায় কংকর, কুরবানি, মাথা মুণ্ডন, তাওয়াফে ইফাদা"}, {"en": "11th–13th: stay in Mina and stone the three jamarat", "bn": "১১–১৩ তারিখ: মিনায় থেকে তিন জামরায় কংকর"}, {"en": "Farewell tawaf before leaving", "bn": "বিদায়ের আগে বিদায়ী তাওয়াফ"}], "rtl": false}', '{"en": "The order of the Prophet’s ﷺ Hajj, from Jabir’s long hadith.", "bn": "জাবির (রা.)-এর দীর্ঘ হাদিস থেকে নবীজির ﷺ হজের ক্রম।"}', 'Sahih Muslim 1218; Sahih al-Bukhari 1755', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('28c35090-a042-5580-80d7-e7ef38d9077b', '99e7160f-4ef9-56bd-98f7-6f27e2696a12', 'match', '{"en": "Match each day to its place", "bn": "প্রতিটি দিনের স্থান মেলান"}', '{"pairs": [{"left": {"en": "8 Dhul Hijjah", "bn": "৮ জিলহজ"}, "right": {"en": "Mina", "bn": "মিনা"}}, {"left": {"en": "9 Dhul Hijjah", "bn": "৯ জিলহজ"}, "right": {"en": "Arafah", "bn": "আরাফা"}}, {"left": {"en": "The night after Arafah", "bn": "আরাফার পরের রাত"}, "right": {"en": "Muzdalifah", "bn": "মুজদালিফা"}}, {"left": {"en": "10 Dhul Hijjah, morning", "bn": "১০ জিলহজ, সকাল"}, "right": {"en": "Jamrat al-‘Aqabah", "bn": "জামরাতুল আকাবা"}}]}', '{"en": "Mina, Arafah, Muzdalifah, then back to Mina.", "bn": "মিনা, আরাফা, মুজদালিফা, তারপর আবার মিনা।"}', 'Sahih Muslim 1218', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('aee80d5f-7748-543b-a675-730105de6443', '99e7160f-4ef9-56bd-98f7-6f27e2696a12', 'true_false', '{"en": "Standing at Arafah is the heart of Hajj: whoever misses it misses the Hajj.", "bn": "আরাফায় অবস্থান হজের মূল: যে তা হারায় সে হজ হারায়।"}', '{"answer": true}', '{"en": "\"Hajj is Arafah.\"", "bn": "\"হজ হলো আরাফা।\""}', 'Jami‘ at-Tirmidhi 889', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('996c63ee-55c8-5231-b242-b1d83fecad6d', '99e7160f-4ef9-56bd-98f7-6f27e2696a12', 'choice', '{"en": "How many pebbles are thrown at a jamrah each time?", "bn": "প্রতিবার একটি জামরায় কয়টি কংকর মারা হয়?"}', '{"options": [{"en": "3", "bn": "৩"}, {"en": "5", "bn": "৫"}, {"en": "7", "bn": "৭"}, {"en": "9", "bn": "৯"}], "correct": 2}', '{"en": "Seven, saying \"Allahu Akbar\" with each.", "bn": "সাতটি, প্রতিটির সঙ্গে \"আল্লাহু আকবার\"।"}', 'Sahih Muslim 1218', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fc1aa1b6-f62c-5b13-a31c-46fbe4425526', '99e7160f-4ef9-56bd-98f7-6f27e2696a12', 'true_false', '{"en": "On the days of Tashriq all three jamarat are stoned.", "bn": "আইয়ামে তাশরিকে তিনটি জামরাতেই কংকর মারা হয়।"}', '{"answer": true}', '{"en": "The small, the middle, then al-‘Aqabah, each with seven pebbles.", "bn": "ছোট, মাঝেরটি, তারপর আকাবা — প্রতিটিতে সাতটি করে।"}', 'Sahih al-Bukhari 1751', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('61b18218-690b-5e59-877f-f739b4f9dc55', '99e7160f-4ef9-56bd-98f7-6f27e2696a12', 'choice', '{"en": "Which tawaf is a pillar of Hajj?", "bn": "কোন তাওয়াফ হজের রুকন?"}', '{"options": [{"en": "Tawaf al-Ifadah", "bn": "তাওয়াফে ইফাদা"}, {"en": "A voluntary tawaf", "bn": "নফল তাওয়াফ"}, {"en": "Tawaf al-Qudum", "bn": "তাওয়াফে কুদুম"}, {"en": "None", "bn": "কোনোটিই না"}], "correct": 0}', '{"en": "\"…and let them perform tawaf around the Ancient House.\"", "bn": "\"…এবং তারা যেন প্রাচীন ঘরের তাওয়াফ করে।\""}', 'Quran 22:29', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('9f0216df-00c9-5e82-9e64-aca8e2540d98', '{"en": "Learn about qurbani", "bn": "কুরবানি শিখি"}', '{"en": "Which animals, sharing, defects, and how to slaughter.", "bn": "কোন পশু, শরিকানা, ত্রুটি এবং জবাইয়ের নিয়ম।"}', NULL, 'star', 'in_review', 4, (SELECT s.id FROM is_learn_sections s WHERE s.id = '4d89a642-10e5-52e6-8833-7f6ca53f4032')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('64f176f3-0ab7-5764-b055-9959b85021e0', '9f0216df-00c9-5e82-9e64-aca8e2540d98', '{"en": "The animal", "bn": "কুরবানির পশু"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5fefd3a0-2b53-524c-af57-508843841255', '64f176f3-0ab7-5764-b055-9959b85021e0', 'choice', '{"en": "From which animals is qurbani given?", "bn": "কোন পশু দিয়ে কুরবানি হয়?"}', '{"options": [{"en": "Chickens and ducks", "bn": "মুরগি ও হাঁস"}, {"en": "Camels, cattle, sheep and goats", "bn": "উট, গরু-মহিষ, ভেড়া ও ছাগল"}, {"en": "Fish", "bn": "মাছ"}, {"en": "Deer", "bn": "হরিণ"}], "correct": 1}', '{"en": "\"…the livestock (bahimat al-an‘am) He has provided them.\"", "bn": "\"…তাদের দেওয়া চতুষ্পদ গৃহপালিত পশু (বাহিমাতুল আনআম)।\""}', 'Quran 22:34', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d2d30a45-dde9-5631-af0a-1d871a54c87f', '64f176f3-0ab7-5764-b055-9959b85021e0', 'true_false', '{"en": "Seven people may share one cow for qurbani.", "bn": "সাতজন মিলে একটি গরু কুরবানি দিতে পারেন।"}', '{"answer": true}', '{"en": "\"…a camel for seven and a cow for seven.\"", "bn": "\"…একটি উট সাতজনের পক্ষ থেকে, একটি গরু সাতজনের পক্ষ থেকে।\""}', 'Sahih Muslim 1318', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('aee5e368-050e-5a87-8bfd-7e10ac173656', '64f176f3-0ab7-5764-b055-9959b85021e0', 'true_false', '{"en": "Seven people may share one goat for qurbani.", "bn": "সাতজন মিলে একটি ছাগল কুরবানি দিতে পারেন।"}', '{"answer": false}', '{"en": "Sharing in shares is for camels and cattle; a sheep or goat is one person’s sacrifice.", "bn": "ভাগে শরিক হওয়া উট ও গরুর ক্ষেত্রে; ভেড়া বা ছাগল একজনের কুরবানি।"}', 'Sahih Muslim 1318', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('852ccdeb-9add-5ec3-92fd-73c3374e59f3', '64f176f3-0ab7-5764-b055-9959b85021e0', 'choice', '{"en": "Which animal is not accepted for qurbani?", "bn": "কোন পশু কুরবানির জন্য গ্রহণযোগ্য নয়?"}', '{"options": [{"en": "A healthy male goat", "bn": "সুস্থ খাসি/পাঁঠা"}, {"en": "A fat cow", "bn": "মোটাতাজা গরু"}, {"en": "A black sheep", "bn": "কালো ভেড়া"}, {"en": "One that is clearly blind in one eye", "bn": "স্পষ্টভাবে এক চোখ কানা"}], "correct": 3}', '{"en": "Four are not accepted: clearly one-eyed, clearly sick, clearly lame, and very thin.", "bn": "চারটি চলবে না: স্পষ্ট কানা, স্পষ্ট অসুস্থ, স্পষ্ট খোঁড়া ও অত্যন্ত দুর্বল।"}', 'Sunan Abi Dawud 2802', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2054dc74-ed46-5563-a6de-b53d3bb94210', '64f176f3-0ab7-5764-b055-9959b85021e0', 'true_false', '{"en": "A clearly lame animal is fine for qurbani.", "bn": "স্পষ্টভাবে খোঁড়া পশু দিয়ে কুরবানি চলে।"}', '{"answer": false}', '{"en": "A clearly lame animal is one of the four not accepted.", "bn": "স্পষ্ট খোঁড়া পশু অগ্রহণযোগ্য চারটির একটি।"}', 'Sunan Abi Dawud 2802; Jami‘ at-Tirmidhi 1497', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e0ac990c-fd3f-50cb-86c7-a72bb3a17f22', '64f176f3-0ab7-5764-b055-9959b85021e0', 'true_false', '{"en": "Choosing a good, healthy animal honours Allah’s symbols.", "bn": "ভালো ও সুস্থ পশু বাছাই করা আল্লাহর নিদর্শনের সম্মান।"}', '{"answer": true}', '{"en": "\"Whoever honours the symbols of Allah — it is from the piety of hearts.\"", "bn": "\"যে আল্লাহর নিদর্শনসমূহকে সম্মান করে, তা তো অন্তরের তাকওয়া থেকেই।\""}', 'Quran 22:32', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('ff44cd15-68fd-52f6-849e-fa6ac6979b63', '9f0216df-00c9-5e82-9e64-aca8e2540d98', '{"en": "How to sacrifice", "bn": "কুরবানির নিয়ম"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8abbc56a-2e92-5c01-b0c5-d463e4f0c8e1', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'order', '{"en": "Put the steps in order", "bn": "ধাপগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Pray the Eid prayer first", "bn": "আগে ঈদের নামাজ পড়া"}, {"en": "Lay the animal down facing the qiblah", "bn": "পশুকে কিবলামুখী করে শোয়ানো"}, {"en": "Say: Bismillah, Allahu Akbar", "bn": "বলা: বিসমিল্লাহ, আল্লাহু আকবার"}, {"en": "Slaughter quickly with a sharp knife", "bn": "ধারালো ছুরি দিয়ে দ্রুত জবাই"}, {"en": "Eat, gift and give to the poor", "bn": "নিজে খাওয়া, উপহার দেওয়া ও গরিবকে দেওয়া"}], "rtl": false}', '{"en": "After the prayer, with Allah’s name, with mercy to the animal, and sharing the meat.", "bn": "নামাজের পর, আল্লাহর নামে, পশুর প্রতি দয়া রেখে, আর গোশত ভাগ করে।"}', 'Sahih al-Bukhari 5560; Sahih Muslim 1966; Sahih Muslim 1955', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('70423d0d-aae3-5305-bb86-b632f77f4b71', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'fill', '{"en": "What is said when slaughtering?", "bn": "জবাইয়ের সময় কী বলা হয়?"}', '{"options": [{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "Amin", "bn": "আমিন"}, {"en": "Insha’Allah", "bn": "ইনশাআল্লাহ"}], "correct": 0, "rtl": false, "before": {"en": "Bismillah,", "bn": "বিসমিল্লাহ,"}}', '{"en": "He ﷺ said \"Bismillah\" and \"Allahu Akbar\" over his two rams.", "bn": "নবী ﷺ তাঁর দুই দুম্বার ওপর \"বিসমিল্লাহ\" ও \"আল্লাহু আকবার\" বলেছেন।"}', 'Sahih Muslim 1966', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c1c50bc7-88c2-5d2d-9157-652623a1e635', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'true_false', '{"en": "An animal slaughtered before the Eid prayer counts as qurbani.", "bn": "ঈদের নামাজের আগে জবাই করা পশু কুরবানি হিসেবে গণ্য।"}', '{"answer": false}', '{"en": "\"Whoever slaughtered before the prayer, it is only meat he gave his family.\"", "bn": "\"যে নামাজের আগে জবাই করল, তা শুধু পরিবারের জন্য গোশত।\""}', 'Sahih al-Bukhari 5560', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('86cd5cdf-33db-53d3-a99c-40a0fedfbc6d', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'true_false', '{"en": "The one who sacrifices may eat from the meat.", "bn": "কুরবানিদাতা নিজে গোশত খেতে পারেন।"}', '{"answer": true}', '{"en": "\"So eat from them and feed the needy and the poor.\"", "bn": "\"অতঃপর তোমরা তা থেকে খাও এবং দুস্থ-অভাবীকে খাওয়াও।\""}', 'Quran 22:28', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cadb9f2f-c9bc-5efe-9a92-906aa7639096', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'choice', '{"en": "What reaches Allah from the sacrifice?", "bn": "কুরবানির কোন জিনিস আল্লাহর কাছে পৌঁছায়?"}', '{"options": [{"en": "The meat", "bn": "গোশত"}, {"en": "The blood", "bn": "রক্ত"}, {"en": "Your piety (taqwa)", "bn": "তোমাদের তাকওয়া"}, {"en": "The price", "bn": "দাম"}], "correct": 2}', '{"en": "\"Neither their meat nor their blood reaches Allah, but piety from you reaches Him.\"", "bn": "\"এগুলোর গোশত বা রক্ত আল্লাহর কাছে পৌঁছায় না, বরং তোমাদের তাকওয়া পৌঁছায়।\""}', 'Quran 22:37', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b901c8ce-6718-5035-b73f-7a63a8563a85', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'true_false', '{"en": "Paying the butcher with meat from the qurbani is the Sunnah.", "bn": "কসাইকে কুরবানির গোশত দিয়ে পারিশ্রমিক দেওয়া সুন্নাত।"}', '{"answer": false}', '{"en": "‘Ali (RA): he ﷺ told me not to give the butcher anything from it as his wage; \"we will pay him ourselves.\"", "bn": "আলী (রা.): নবী ﷺ আমাকে কসাইকে পারিশ্রমিক হিসেবে তা থেকে কিছু দিতে নিষেধ করেছেন; \"আমরা নিজেরা তাকে দেব।\""}', 'Sahih Muslim 1317', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f6f90065-890f-5cea-9fbc-795ab92f7ca3', 'ff44cd15-68fd-52f6-849e-fa6ac6979b63', 'true_false', '{"en": "The Prophet ﷺ told us to sharpen the blade and spare the animal suffering.", "bn": "নবী ﷺ ছুরি ধারালো করতে ও পশুকে কষ্ট না দিতে বলেছেন।"}', '{"answer": true}', '{"en": "\"Allah has prescribed excellence in everything…\"", "bn": "\"আল্লাহ সবকিছুতে উত্তমতা ফরজ করেছেন…\""}', 'Sahih Muslim 1955', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_sections (id, category_id, title, description, sort_order) SELECT 'e6fe022e-d447-5192-93f2-e2d58bd8b81b', c.id, '{"en": "The kalima & the names of Allah", "bn": "কালিমা ও আল্লাহর নাম"}', '{"en": "The words of faith and the meanings of Allah’s beautiful names.", "bn": "ঈমানের বাক্য এবং আল্লাহর সুন্দর নামসমূহের অর্থ।"}', 10 FROM is_learn_categories c WHERE c.id = '19d65256-f537-5a40-93b3-65bb100e2507' ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('a63bd2f6-88a3-56d3-b4fa-95abb8d63585', '{"en": "The kalima", "bn": "কালিমা"}', '{"en": "Kalima Tayyibah and Kalima Shahadah: words, meaning and virtue.", "bn": "কালিমা তাইয়্যিবা ও কালিমা শাহাদাত: শব্দ, অর্থ ও ফজিলত।"}', NULL, 'sparkles', 'in_review', 1, (SELECT s.id FROM is_learn_sections s WHERE s.id = 'e6fe022e-d447-5192-93f2-e2d58bd8b81b')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'a63bd2f6-88a3-56d3-b4fa-95abb8d63585', '{"en": "Kalima Tayyibah", "bn": "কালিমা তাইয়্যিবা"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1168a8da-77c8-5b18-b886-ad8b3979f4ba', '6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'order', '{"en": "Put the words of the kalima in order", "bn": "কালিমার শব্দগুলো সাজান"}', '{"pieces": [{"ar": "لَا"}, {"ar": "إِلٰهَ"}, {"ar": "إِلَّا"}, {"ar": "اللّٰهُ"}, {"ar": "مُحَمَّدٌ"}, {"ar": "رَسُولُ"}, {"ar": "اللّٰهِ"}], "rtl": true}', '{"en": "\"La ilaha illallah, Muhammadur-Rasulullah\" — There is no god but Allah; Muhammad is the Messenger of Allah.", "bn": "\"লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসুলুল্লাহ\" — আল্লাহ ছাড়া কোনো ইলাহ নেই, মুহাম্মাদ ﷺ আল্লাহর রাসুল।"}', 'Quran 47:19; Quran 48:29', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2c7aacfc-acd7-537f-9f8f-d39df9efe67c', '6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'choice', '{"en": "What does \"La ilaha illallah, Muhammadur-Rasulullah\" mean?", "bn": "\"লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসুলুল্লাহ\" অর্থ কী?"}', '{"options": [{"en": "Allah is the Greatest; all praise is His", "bn": "আল্লাহ সবচেয়ে বড়; সব প্রশংসা তাঁর"}, {"en": "There is no god but Allah; Muhammad is the Messenger of Allah", "bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই; মুহাম্মাদ ﷺ আল্লাহর রাসুল"}, {"en": "In the name of Allah, the Merciful", "bn": "পরম দয়ালু আল্লাহর নামে"}, {"en": "Glory be to Allah", "bn": "আল্লাহ পবিত্র"}], "correct": 1}', '{"en": "The first half is tawhid; the second accepts the Prophet ﷺ as Allah’s messenger.", "bn": "প্রথম অংশ তাওহিদ; দ্বিতীয় অংশে নবী ﷺ-কে আল্লাহর রাসুল হিসেবে মেনে নেওয়া।"}', 'Quran 47:19; Quran 48:29', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a3701c5a-1e3b-5b82-88db-a66edd3a1d42', '6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'match', '{"en": "Match each word to its meaning", "bn": "প্রতিটি শব্দের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "لَا"}, "right": {"en": "No / none", "bn": "নেই"}}, {"left": {"ar": "إِلٰهَ"}, "right": {"en": "god (worthy of worship)", "bn": "ইলাহ (ইবাদতের যোগ্য)"}}, {"left": {"ar": "إِلَّا"}, "right": {"en": "except", "bn": "ছাড়া"}}, {"left": {"ar": "رَسُولُ"}, "right": {"en": "messenger", "bn": "রাসুল (বার্তাবাহক)"}}]}', '{"en": "La = no, ilaha = god, illa = except, rasul = messenger.", "bn": "লা = নেই, ইলাহ = উপাস্য, ইল্লা = ছাড়া, রাসুল = বার্তাবাহক।"}', 'Quran 47:19', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('699a385b-a892-52c5-8e61-cf8822ab589b', '6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'true_false', '{"en": "\"La ilaha\" denies every false god, and \"illallah\" affirms Allah alone.", "bn": "\"লা ইলাহা\" সব মিথ্যা উপাস্যকে অস্বীকার করে, আর \"ইল্লাল্লাহ\" শুধু আল্লাহকে সাব্যস্ত করে।"}', '{"answer": true}', '{"en": "\"Whoever disbelieves in false gods and believes in Allah has grasped the most firm handhold.\"", "bn": "\"যে তাগুতকে অস্বীকার করে এবং আল্লাহর ওপর ঈমান আনে, সে মজবুত হাতল আঁকড়ে ধরেছে।\""}', 'Quran 2:256', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1950a948-36fb-5b9d-84c4-81d17bd3243c', '6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'choice', '{"en": "Which surah has the ayah \"Muhammad is the Messenger of Allah\"?", "bn": "কোন সূরায় \"মুহাম্মাদ আল্লাহর রাসুল\" আয়াতটি আছে?"}', '{"options": [{"en": "Al-Fath", "bn": "আল-ফাতহ"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 0}', '{"en": "\"Muhammad is the Messenger of Allah, and those with him are firm against the disbelievers, merciful among themselves…\"", "bn": "\"মুহাম্মাদ আল্লাহর রাসুল; আর যারা তাঁর সঙ্গে আছে তারা কাফিরদের প্রতি কঠোর, নিজেদের মধ্যে দয়ালু…\""}', 'Quran 48:29', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('91079713-a2f6-5538-8a92-8cd788ad8cb4', '6297c94d-e9b9-524d-8f51-58746f1f0f0d', 'true_false', '{"en": "Whoever’s last words are \"La ilaha illallah\" will enter Paradise.", "bn": "যার শেষ কথা \"লা ইলাহা ইল্লাল্লাহ\", সে জান্নাতে প্রবেশ করবে।"}', '{"answer": true}', '{"en": "\"Whoever’s last words are La ilaha illallah will enter Paradise.\" So we gently remind the dying.", "bn": "\"যার শেষ কথা লা ইলাহা ইল্লাল্লাহ, সে জান্নাতে যাবে।\" তাই মুমূর্ষুকে কোমলভাবে স্মরণ করিয়ে দেওয়া হয়।"}', 'Sunan Abi Dawud 3116', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'a63bd2f6-88a3-56d3-b4fa-95abb8d63585', '{"en": "Kalima Shahadah & beloved words", "bn": "কালিমা শাহাদাত ও প্রিয় বাক্য"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0adc6427-e657-580d-80d2-e9990fa82419', 'b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'order', '{"en": "Put the shahadah in order", "bn": "কালিমা শাহাদাত সাজান"}', '{"pieces": [{"ar": "أَشْهَدُ"}, {"ar": "أَنْ لَا إِلٰهَ"}, {"ar": "إِلَّا اللّٰهُ"}, {"ar": "وَأَشْهَدُ"}, {"ar": "أَنَّ مُحَمَّدًا"}, {"ar": "عَبْدُهُ"}, {"ar": "وَرَسُولُهُ"}], "rtl": true}', '{"en": "\"I testify that there is no god but Allah, and I testify that Muhammad is His servant and His messenger.\"", "bn": "\"আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।\""}', 'Sahih Muslim 234; Sahih al-Bukhari 831', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b93693b9-f3ee-5aa9-9361-ab5fbcfe94bd', 'b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'choice', '{"en": "In the shahadah, what does \"‘abduhu wa rasuluh\" mean?", "bn": "শাহাদাতে \"আবদুহু ওয়া রাসুলুহ\" অর্থ কী?"}', '{"options": [{"en": "His servant and His messenger", "bn": "তাঁর বান্দা ও তাঁর রাসুল"}, {"en": "His friend and His angel", "bn": "তাঁর বন্ধু ও ফেরেশতা"}, {"en": "The first and the last", "bn": "প্রথম ও শেষ"}, {"en": "The king and the judge", "bn": "রাজা ও বিচারক"}], "correct": 0}', '{"en": "He ﷺ is a servant — not to be worshipped — and a messenger — to be followed.", "bn": "তিনি ﷺ বান্দা — তাঁর ইবাদত নয় — এবং রাসুল — তাঁর অনুসরণ করতে হবে।"}', 'Sahih al-Bukhari 3445', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a9e28d55-994f-5b32-8a1e-afe6f1ec5029', 'b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'true_false', '{"en": "The shahadah is the first pillar of Islam.", "bn": "শাহাদাত ইসলামের প্রথম স্তম্ভ।"}', '{"answer": true}', '{"en": "\"Islam is built on five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah…\"", "bn": "\"ইসলাম পাঁচটি ভিত্তির ওপর: সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো ইলাহ নেই ও মুহাম্মাদ ﷺ আল্লাহর রাসুল…\""}', 'Sahih al-Bukhari 8', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f2a86763-a7a6-596e-9c7a-20608e1f05d0', 'b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'choice', '{"en": "Which four phrases did the Prophet ﷺ call the most beloved words to Allah?", "bn": "কোন চারটি বাক্যকে নবী ﷺ আল্লাহর কাছে সবচেয়ে প্রিয় বলেছেন?"}', '{"options": [{"en": "Bismillah, Insha’Allah, Masha’Allah, Amin", "bn": "বিসমিল্লাহ, ইনশাআল্লাহ, মাশাআল্লাহ, আমিন"}, {"en": "SubhanAllah, Alhamdulillah, La ilaha illallah, Allahu Akbar", "bn": "সুবহানাল্লাহ, আলহামদুলিল্লাহ, লা ইলাহা ইল্লাল্লাহ, আল্লাহু আকবার"}, {"en": "Astaghfirullah four times", "bn": "চারবার আসতাগফিরুল্লাহ"}, {"en": "Labbayk four times", "bn": "চারবার লাব্বাইক"}], "correct": 1}', '{"en": "\"The most beloved words to Allah are four…\" — in Bangladesh they are taught as Kalima Tamjid, with \"la hawla wa la quwwata illa billah\" added.", "bn": "\"আল্লাহর কাছে সবচেয়ে প্রিয় বাক্য চারটি…\" — বাংলাদেশে এগুলো কালিমা তামজিদ হিসেবে শেখানো হয়, সঙ্গে \"লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ\"।"}', 'Sahih Muslim 2137', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1fa2cacd-d8f5-5c0a-83f7-daca87a1875c', 'b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'choice', '{"en": "Saying \"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ‘ala kulli shay’in qadir\" a hundred times a day is like freeing how many slaves?", "bn": "দিনে একশোবার \"লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহ, লাহুল মুলকু ওয়া লাহুল হামদু ওয়া হুয়া আলা কুল্লি শাইয়িন কাদির\" বললে কয়টি দাস মুক্ত করার সমান?"}', '{"options": [{"en": "One", "bn": "একটি"}, {"en": "Three", "bn": "তিনটি"}, {"en": "Ten", "bn": "দশটি"}, {"en": "A hundred", "bn": "একশোটি"}], "correct": 2}', '{"en": "\"…it is like freeing ten slaves; a hundred good deeds are written for him, a hundred sins wiped away, and it guards him from Shaytan that day.\"", "bn": "\"…দশটি দাস মুক্ত করার সমান; তার জন্য একশো নেকি লেখা হয়, একশো গুনাহ মোছা হয়, আর সেদিন শয়তান থেকে সুরক্ষা হয়।\""}', 'Sahih al-Bukhari 6403', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cbb82b34-796f-5e89-bee6-48596229a55e', 'b95f3d42-6b75-5328-9910-706d0d0d6c5c', 'match', '{"en": "Match the words to what the hadith calls them", "bn": "বাক্যগুলোকে হাদিসের পরিচয়ের সঙ্গে মেলান"}', '{"pairs": [{"left": {"en": "La ilaha illallah, Muhammadur-Rasulullah", "bn": "লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসুলুল্লাহ"}, "right": {"en": "Kalima Tayyibah, the good word", "bn": "কালিমা তাইয়্যিবা, পবিত্র বাক্য"}}, {"left": {"en": "Ashhadu an la ilaha illallah…", "bn": "আশহাদু আল্লা ইলাহা ইল্লাল্লাহু…"}, "right": {"en": "Kalima Shahadah, the testimony", "bn": "কালিমা শাহাদাত, সাক্ষ্যবাণী"}}, {"left": {"en": "SubhanAllah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "bn": "সুবহানাল্লাহি ওয়াল হামদু লিল্লাহি ওয়া লা ইলাহা ইল্লাল্লাহু ওয়াল্লাহু আকবার"}, "right": {"en": "The most beloved words to Allah", "bn": "আল্লাহর কাছে সবচেয়ে প্রিয় বাক্য"}}, {"left": {"en": "La hawla wa la quwwata illa billah", "bn": "লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ"}, "right": {"en": "A treasure of Paradise", "bn": "জান্নাতের একটি ভান্ডার"}}]}', '{"en": "\"A good word is like a good tree, its root firm and its branches in the sky.\"", "bn": "\"পবিত্র বাক্য একটি পবিত্র গাছের মতো, যার মূল সুদৃঢ় আর শাখা আকাশে।\""}', 'Quran 14:24; Sahih Muslim 2137; Sahih al-Bukhari 4205', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('33d6f75d-8f5d-5bbe-9db4-1d2d806c611a', '{"en": "The beautiful names of Allah", "bn": "আল্লাহর সুন্দর নামসমূহ"}', '{"en": "Forty-five of Allah’s names from the Quran and what they mean.", "bn": "কুরআনে বর্ণিত আল্লাহর পঁয়তাল্লিশটি নাম ও তাদের অর্থ।"}', NULL, 'sparkles', 'in_review', 2, (SELECT s.id FROM is_learn_sections s WHERE s.id = 'e6fe022e-d447-5192-93f2-e2d58bd8b81b')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a63e8891-d7f0-50eb-bb74-d9af41cc5161', '33d6f75d-8f5d-5bbe-9db4-1d2d806c611a', '{"en": "The names at the end of al-Hashr", "bn": "সূরা হাশরের শেষের নামসমূহ"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0208ad76-a1cf-5044-a636-774b90f1058a', 'a63e8891-d7f0-50eb-bb74-d9af41cc5161', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الملك"}, "right": {"en": "The King, the Sovereign", "bn": "অধিপতি, সার্বভৌম"}}, {"left": {"ar": "القدوس"}, "right": {"en": "The Most Holy", "bn": "মহাপবিত্র"}}, {"left": {"ar": "السلام"}, "right": {"en": "The Source of peace", "bn": "শান্তির উৎস"}}, {"left": {"ar": "المؤمن"}, "right": {"en": "The Giver of safety", "bn": "নিরাপত্তাদাতা"}}, {"left": {"ar": "المهيمن"}, "right": {"en": "The Guardian over all", "bn": "রক্ষণাবেক্ষণকারী"}}]}', '{"en": "Al-Malik, Al-Quddus, As-Salam, Al-Mu’min, Al-Muhaymin.", "bn": "আল-মালিক, আল-কুদ্দুস, আস-সালাম, আল-মুমিন, আল-মুহাইমিন।"}', 'Quran 59:23', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2356e1c8-d5fb-52dc-afaf-9cbb9a456da6', 'a63e8891-d7f0-50eb-bb74-d9af41cc5161', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "العزيز"}, "right": {"en": "The Almighty", "bn": "মহাপরাক্রমশালী"}}, {"left": {"ar": "الجبار"}, "right": {"en": "The Compeller, who sets right", "bn": "মহাপ্রতাপশালী, যিনি সব ঠিক করে দেন"}}, {"left": {"ar": "المتكبر"}, "right": {"en": "The Supreme in greatness", "bn": "সর্বশ্রেষ্ঠ মহিমার অধিকারী"}}, {"left": {"ar": "الخالق"}, "right": {"en": "The Creator", "bn": "সৃষ্টিকর্তা"}}, {"left": {"ar": "المصور"}, "right": {"en": "The Fashioner of forms", "bn": "আকৃতিদাতা"}}]}', '{"en": "Al-‘Aziz, Al-Jabbar, Al-Mutakabbir, Al-Khaliq, Al-Musawwir.", "bn": "আল-আজিজ, আল-জাব্বার, আল-মুতাকাব্বির, আল-খালিক, আল-মুসাওয়ির।"}', 'Quran 59:23; Quran 59:24', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6b3cad31-d279-5a18-9ea0-217f8f513041', 'a63e8891-d7f0-50eb-bb74-d9af41cc5161', 'choice', '{"en": "What does Al-Bari’ (البارئ) mean?", "bn": "আল-বারি (البارئ) অর্থ কী?"}', '{"options": [{"en": "The King, the Sovereign", "bn": "অধিপতি, সার্বভৌম"}, {"en": "The Light", "bn": "আলো"}, {"en": "The Originator", "bn": "উদ্ভাবনকর্তা"}, {"en": "The Loving", "bn": "প্রেমময়"}], "correct": 2}', '{"en": "Al-Bari’: The Originator.", "bn": "আল-বারি: উদ্ভাবনকর্তা।"}', 'Quran 59:24', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6c5b61f6-71ad-51ec-860a-48a74f43f983', 'a63e8891-d7f0-50eb-bb74-d9af41cc5161', 'choice', '{"en": "Which name means \"The Most Holy\"?", "bn": "কোন নামের অর্থ \"মহাপবিত্র\"?"}', '{"options": [{"ar": "القدوس"}, {"ar": "القهار"}, {"ar": "الغني"}, {"ar": "الوكيل"}], "correct": 0}', '{"en": "Al-Quddus: The Most Holy.", "bn": "আল-কুদ্দুস: মহাপবিত্র।"}', 'Quran 59:23', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('84ae9c79-7743-54e6-a0a1-c9afe3576178', 'a63e8891-d7f0-50eb-bb74-d9af41cc5161', 'true_false', '{"en": "The last three ayahs of Surah al-Hashr gather many of Allah’s names.", "bn": "সূরা হাশরের শেষ তিন আয়াতে আল্লাহর অনেক নাম একসঙ্গে এসেছে।"}', '{"answer": true}', '{"en": "\"…To Him belong the most beautiful names.\"", "bn": "\"…সুন্দরতম নামসমূহ তাঁরই।\""}', 'Quran 59:22–24', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('88813d29-69f9-5218-94c8-ecc4ddf269b5', 'a63e8891-d7f0-50eb-bb74-d9af41cc5161', 'true_false', '{"en": "The Prophet ﷺ said Allah has ninety-nine names; whoever learns them will enter Paradise.", "bn": "নবী ﷺ বলেছেন, আল্লাহর নিরানব্বইটি নাম আছে; যে এগুলো আয়ত্ত করবে সে জান্নাতে যাবে।"}', '{"answer": true}', '{"en": "Learning them means knowing them, understanding them and living by them.", "bn": "আয়ত্ত করা মানে জানা, বোঝা এবং সে অনুযায়ী জীবন গড়া।"}', 'Sahih al-Bukhari 2736', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b271f902-b380-5133-90d8-60df2ec2e13c', '33d6f75d-8f5d-5bbe-9db4-1d2d806c611a', '{"en": "Names of mercy & forgiveness", "bn": "দয়া ও ক্ষমার নামসমূহ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f5d5c313-e80e-5c8e-b9e3-e3b54449031f', 'b271f902-b380-5133-90d8-60df2ec2e13c', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الرحمن"}, "right": {"en": "The Entirely Merciful", "bn": "পরম করুণাময়"}}, {"left": {"ar": "التواب"}, "right": {"en": "The Accepter of repentance", "bn": "তওবা কবুলকারী"}}, {"left": {"ar": "الرؤوف"}, "right": {"en": "The Most Kind", "bn": "অতি স্নেহশীল"}}, {"left": {"ar": "الودود"}, "right": {"en": "The Loving", "bn": "প্রেমময়"}}, {"left": {"ar": "الحليم"}, "right": {"en": "The Forbearing", "bn": "সহনশীল"}}]}', '{"en": "Ar-Rahman, At-Tawwab, Ar-Ra’uf, Al-Wadud, Al-Halim.", "bn": "আর-রহমান, আত-তাওয়াব, আর-রাউফ, আল-ওয়াদুদ, আল-হালিম।"}', 'Quran 1:3; Quran 2:37; Quran 2:143; Quran 85:14; Quran 2:225', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4cbd21a5-69ab-5cde-8f60-fbb7da31afa7', 'b271f902-b380-5133-90d8-60df2ec2e13c', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الغفار"}, "right": {"en": "The Ever-Forgiving", "bn": "বারবার ক্ষমাকারী"}}, {"left": {"ar": "الكريم"}, "right": {"en": "The Most Generous", "bn": "মহাদয়ালু, মহানুভব"}}, {"left": {"ar": "الشكور"}, "right": {"en": "The Appreciative", "bn": "গুণগ্রাহী"}}, {"left": {"ar": "العفو"}, "right": {"en": "The Pardoner", "bn": "মার্জনাকারী"}}]}', '{"en": "Al-Ghaffar, Al-Karim, Ash-Shakur, Al-‘Afuww.", "bn": "আল-গাফফার, আল-কারিম, আশ-শাকুর, আল-আফুউ।"}', 'Quran 71:10; Quran 82:6; Quran 35:30; Quran 4:43', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2f090c1a-0b1d-56ca-8f1e-3cbb88931ef1', 'b271f902-b380-5133-90d8-60df2ec2e13c', 'choice', '{"en": "What does Al-Halim (الحليم) mean?", "bn": "আল-হালিম (الحليم) অর্থ কী?"}', '{"options": [{"en": "The All-Strong", "bn": "মহাশক্তিমান"}, {"en": "The Forbearing", "bn": "সহনশীল"}, {"en": "The First", "bn": "আদি (সর্বপ্রথম)"}, {"en": "The All-Seeing", "bn": "সর্বদ্রষ্টা"}], "correct": 1}', '{"en": "Al-Halim: The Forbearing.", "bn": "আল-হালিম: সহনশীল।"}', 'Quran 2:225', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6e43af39-143d-5374-a3ed-a29c6fd7ddf5', 'b271f902-b380-5133-90d8-60df2ec2e13c', 'choice', '{"en": "Which name means \"The Pardoner\"?", "bn": "কোন নামের অর্থ \"মার্জনাকারী\"?"}', '{"options": [{"ar": "الجبار"}, {"ar": "العليم"}, {"ar": "الحي"}, {"ar": "العفو"}], "correct": 3}', '{"en": "Al-‘Afuww: The Pardoner.", "bn": "আল-আফুউ: মার্জনাকারী।"}', 'Quran 4:43', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e1a77f22-9983-512c-97f3-a11b9cc79f7d', 'b271f902-b380-5133-90d8-60df2ec2e13c', 'true_false', '{"en": "\"Say: O My servants who have wronged themselves, do not despair of Allah’s mercy; Allah forgives all sins.\"", "bn": "\"বলুন: হে আমার বান্দারা, যারা নিজেদের ওপর জুলুম করেছ, আল্লাহর রহমত থেকে নিরাশ হয়ো না; আল্লাহ সব গুনাহ ক্ষমা করেন।\""}', '{"answer": true}', '{"en": "This is Quran 39:53 — for those who turn back to Him in repentance.", "bn": "এটি কুরআনের ৩৯:৫৩ আয়াত — যারা তওবা করে তাঁর দিকে ফিরে আসে তাদের জন্য।"}', 'Quran 39:53', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('086fc520-1dd6-5fe5-ae67-2542b7ff271a', 'b271f902-b380-5133-90d8-60df2ec2e13c', 'fill', '{"en": "Complete the dua of Laylat al-Qadr", "bn": "লাইলাতুল কদরের দোয়াটি পূর্ণ করুন"}', '{"options": [{"en": "‘afuwwun", "bn": "আফুউন"}, {"en": "jabbarun", "bn": "জাব্বারুন"}, {"en": "qahharun", "bn": "কাহহারুন"}, {"en": "ghaniyyun", "bn": "গনিয়্যুন"}], "correct": 0, "rtl": false, "before": {"en": "Allahumma innaka", "bn": "আল্লাহুম্মা ইন্নাকা"}, "after": {"en": "tuhibbul-‘afwa fa‘fu ‘anni", "bn": "তুহিব্বুল আফওয়া ফা‘ফু আন্নি"}}', '{"en": "\"O Allah, You are the Pardoner, You love to pardon, so pardon me.\"", "bn": "\"হে আল্লাহ, আপনি ক্ষমাশীল, ক্ষমা করতে ভালোবাসেন, তাই আমাকে ক্ষমা করুন।\""}', 'Jami‘ at-Tirmidhi 3513', 6) ON CONFLICT (id) DO NOTHING;
