INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b1b8c26d-ef60-59fa-a096-ab6da92259cb', '55d46e6f-a00a-5df4-8bc2-092812a305ed', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "العليم"}, "right": {"en": "The All-Knowing", "bn": "সর্বজ্ঞ"}}, {"left": {"ar": "السميع"}, "right": {"en": "The All-Hearing", "bn": "সর্বশ্রোতা"}}, {"left": {"ar": "البصير"}, "right": {"en": "The All-Seeing", "bn": "সর্বদ্রষ্টা"}}, {"left": {"ar": "الخبير"}, "right": {"en": "The All-Aware", "bn": "সম্যক অবগত"}}, {"left": {"ar": "الحكيم"}, "right": {"en": "The Wise", "bn": "প্রজ্ঞাময়"}}]}', '{"en": "Al-‘Alim, As-Sami‘, Al-Basir, Al-Khabir, Al-Hakim.", "bn": "আল-আলিম, আস-সামি, আল-বাসির, আল-খাবির, আল-হাকিম।"}', 'Quran 2:32; Quran 42:11; Quran 67:14', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bf326908-5c3b-517d-953b-754d4060d405', '55d46e6f-a00a-5df4-8bc2-092812a305ed', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "القوي"}, "right": {"en": "The All-Strong", "bn": "মহাশক্তিমান"}}, {"left": {"ar": "القهار"}, "right": {"en": "The Subduer of all", "bn": "মহাপ্রতাপশালী, সবকিছুর ওপর পরাক্রমশালী"}}, {"left": {"ar": "العظيم"}, "right": {"en": "The Magnificent", "bn": "মহামহিম"}}, {"left": {"ar": "العلي"}, "right": {"en": "The Most High", "bn": "সমুচ্চ"}}, {"left": {"ar": "الرقيب"}, "right": {"en": "The Watchful", "bn": "সদা পর্যবেক্ষক"}}]}', '{"en": "Al-Qawi, Al-Qahhar, Al-‘Azim, Al-‘Aliyy, Ar-Raqib.", "bn": "আল-কাওয়ি, আল-কাহহার, আল-আজিম, আল-আলিয়্যু, আর-রাকিব।"}', 'Quran 22:40; Quran 13:16; Quran 2:255; Quran 4:1', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7fa3a6a8-d875-5bb9-ae8d-beb131df0edd', '55d46e6f-a00a-5df4-8bc2-092812a305ed', 'choice', '{"en": "What does Al-Latif (اللطيف) mean?", "bn": "আল-লাতিফ (اللطيف) অর্থ কী?"}', '{"options": [{"en": "The Subtle, the Gentle", "bn": "সূক্ষ্মদর্শী, কোমল"}, {"en": "The Truth", "bn": "পরম সত্য"}, {"en": "The King, the Sovereign", "bn": "অধিপতি, সার্বভৌম"}, {"en": "The Manifest", "bn": "প্রকাশ্য"}], "correct": 0}', '{"en": "Al-Latif: The Subtle, the Gentle.", "bn": "আল-লাতিফ: সূক্ষ্মদর্শী, কোমল।"}', 'Quran 67:14', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e73f8ced-c722-5f78-b7e2-a74cc20857f8', '55d46e6f-a00a-5df4-8bc2-092812a305ed', 'choice', '{"en": "Which name means \"The Watchful\"?", "bn": "কোন নামের অর্থ \"সদা পর্যবেক্ষক\"?"}', '{"options": [{"ar": "الرزاق"}, {"ar": "السلام"}, {"ar": "الرقيب"}, {"ar": "النور"}], "correct": 2}', '{"en": "Ar-Raqib: The Watchful.", "bn": "আর-রাকিব: সদা পর্যবেক্ষক।"}', 'Quran 4:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ad386bb7-c275-5454-ba14-a62576e0df3a', '55d46e6f-a00a-5df4-8bc2-092812a305ed', 'true_false', '{"en": "\"There is nothing like Him, and He is the All-Hearing, the All-Seeing.\"", "bn": "\"কোনো কিছুই তাঁর সদৃশ নয়, তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।\""}', '{"answer": true}', '{"en": "Allah hears and sees, but nothing is like Him.", "bn": "আল্লাহ শোনেন ও দেখেন, কিন্তু কোনো কিছুই তাঁর মতো নয়।"}', 'Quran 42:11', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7f0e757b-2358-5fba-b72d-2b3b0a542d6f', '55d46e6f-a00a-5df4-8bc2-092812a305ed', 'choice', '{"en": "Ayat al-Kursi ends with which two names?", "bn": "আয়াতুল কুরসি কোন দুটি নাম দিয়ে শেষ হয়?"}', '{"options": [{"en": "Al-‘Aliyy, al-‘Azim (the Most High, the Magnificent)", "bn": "আল-আলিয়্যু, আল-আজিম (সমুচ্চ, মহামহিম)"}, {"en": "Al-Ghafur, ar-Rahim", "bn": "আল-গাফুর, আর-রাহিম"}, {"en": "Al-‘Aziz, al-Hakim", "bn": "আল-আজিজ, আল-হাকিম"}, {"en": "As-Sami‘, al-Basir", "bn": "আস-সামি, আল-বাসির"}], "correct": 0}', '{"en": "\"…and He is the Most High, the Magnificent (wa huwal-‘Aliyyul-‘Azim).\"", "bn": "\"…আর তিনি সমুচ্চ, মহামহিম (ওয়া হুয়াল আলিয়্যুল আজিম)।\""}', 'Quran 2:255', 6) ON CONFLICT (id) DO NOTHING;
