INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('91d44ccb-5549-5524-8fe6-2828c964a96a', '4a9ef91d-7e7a-5eb7-916f-fec0f534d7f3', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الحي"}, "right": {"en": "The Ever-Living", "bn": "চিরঞ্জীব"}}, {"left": {"ar": "القيوم"}, "right": {"en": "The Sustainer of all", "bn": "সবকিছুর ধারক"}}, {"left": {"ar": "الرزاق"}, "right": {"en": "The Provider", "bn": "রিজিকদাতা"}}, {"left": {"ar": "الوهاب"}, "right": {"en": "The Bestower", "bn": "মহাদাতা"}}, {"left": {"ar": "الفتاح"}, "right": {"en": "The Opener, the Judge", "bn": "উন্মোচনকারী, ফয়সালাকারী"}}]}', '{"en": "Al-Hayy, Al-Qayyum, Ar-Razzaq, Al-Wahhab, Al-Fattah.", "bn": "আল-হাইয়ু, আল-কাইয়ুম, আর-রাযযাক, আল-ওয়াহহাব, আল-ফাত্তাহ।"}', 'Quran 2:255; Quran 51:58; Quran 3:8; Quran 34:26', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('90c165cf-b30f-5b4b-a95e-afbb74261c12', '4a9ef91d-7e7a-5eb7-916f-fec0f534d7f3', 'match', '{"en": "Match the four names of al-Hadid 57:3", "bn": "সূরা হাদিদ ৫৭:৩-এর চারটি নাম মেলান"}', '{"pairs": [{"left": {"ar": "الأول"}, "right": {"en": "The First", "bn": "আদি (সর্বপ্রথম)"}}, {"left": {"ar": "الآخر"}, "right": {"en": "The Last", "bn": "অন্ত (সর্বশেষ)"}}, {"left": {"ar": "الظاهر"}, "right": {"en": "The Manifest", "bn": "প্রকাশ্য"}}, {"left": {"ar": "الباطن"}, "right": {"en": "The Hidden", "bn": "গোপন"}}]}', '{"en": "Al-Awwal, Al-Akhir, Az-Zahir, Al-Batin.", "bn": "আল-আউয়াল, আল-আখির, আজ-জাহির, আল-বাতিন।"}', 'Quran 57:3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8f649f06-b3c1-5b51-b777-631bd798d9d1', '4a9ef91d-7e7a-5eb7-916f-fec0f534d7f3', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "المجيب"}, "right": {"en": "The Answerer of prayers", "bn": "দোয়া কবুলকারী"}}, {"left": {"ar": "الوكيل"}, "right": {"en": "The Trustee", "bn": "কর্মবিধায়ক, ভরসাস্থল"}}, {"left": {"ar": "الغني"}, "right": {"en": "The Free of need", "bn": "অমুখাপেক্ষী"}}, {"left": {"ar": "النور"}, "right": {"en": "The Light", "bn": "আলো"}}, {"left": {"ar": "الحق"}, "right": {"en": "The Truth", "bn": "পরম সত্য"}}]}', '{"en": "Al-Mujib, Al-Wakil, Al-Ghani, An-Nur, Al-Haqq.", "bn": "আল-মুজিব, আল-ওয়াকিল, আল-গনি, আন-নূর, আল-হাক।"}', 'Quran 11:61; Quran 3:173; Quran 35:15; Quran 24:35; Quran 22:6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('baee32fe-b887-5c23-899f-f1c220192376', '4a9ef91d-7e7a-5eb7-916f-fec0f534d7f3', 'choice', '{"en": "What does Ar-Razzaq (الرزاق) mean?", "bn": "আর-রাযযাক (الرزاق) অর্থ কী?"}', '{"options": [{"en": "The Supreme in greatness", "bn": "সর্বশ্রেষ্ঠ মহিমার অধিকারী"}, {"en": "The First", "bn": "আদি (সর্বপ্রথম)"}, {"en": "The All-Hearing", "bn": "সর্বশ্রোতা"}, {"en": "The Provider", "bn": "রিজিকদাতা"}], "correct": 3}', '{"en": "Ar-Razzaq: The Provider.", "bn": "আর-রাযযাক: রিজিকদাতা।"}', 'Quran 51:58', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5a979c93-c469-5ada-96c9-0baa9e8053c0', '4a9ef91d-7e7a-5eb7-916f-fec0f534d7f3', 'choice', '{"en": "Which name means \"The Answerer of prayers\"?", "bn": "কোন নামের অর্থ \"দোয়া কবুলকারী\"?"}', '{"options": [{"ar": "الباطن"}, {"ar": "المجيب"}, {"ar": "الخالق"}, {"ar": "العزيز"}], "correct": 1}', '{"en": "Al-Mujib: The Answerer of prayers.", "bn": "আল-মুজিব: দোয়া কবুলকারী।"}', 'Quran 11:61', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('67f8f397-b9c3-56b0-8995-21459a939da1', '4a9ef91d-7e7a-5eb7-916f-fec0f534d7f3', 'true_false', '{"en": "\"Hasbunallahu wa ni‘mal-Wakil\" — Allah is enough for us, and He is the best Trustee.", "bn": "\"হাসবুনাল্লাহু ওয়া নি‘মাল ওয়াকিল\" — আল্লাহই আমাদের জন্য যথেষ্ট, তিনি উত্তম কর্মবিধায়ক।"}', '{"answer": true}', '{"en": "Said by the believers when they were frightened by the enemy, and by Ibrahim (AS) when thrown into the fire.", "bn": "শত্রুর ভয় দেখানো হলে মুমিনরা এবং আগুনে নিক্ষেপের সময় ইবরাহিম (আ.) এটি বলেছিলেন।"}', 'Quran 3:173; Sahih al-Bukhari 4563', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('1b0ffe23-553d-5a52-88ab-2387c01fd23b', '33d6f75d-8f5d-5bbe-9db4-1d2d806c611a', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ff4fe46f-3b80-5edd-ab5d-c292f38dce0a', '1b0ffe23-553d-5a52-88ab-2387c01fd23b', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الرحمن"}, "right": {"en": "The Entirely Merciful", "bn": "পরম করুণাময়"}}, {"left": {"ar": "الرزاق"}, "right": {"en": "The Provider", "bn": "রিজিকদাতা"}}, {"left": {"ar": "العليم"}, "right": {"en": "The All-Knowing", "bn": "সর্বজ্ঞ"}}, {"left": {"ar": "القدوس"}, "right": {"en": "The Most Holy", "bn": "মহাপবিত্র"}}, {"left": {"ar": "الغني"}, "right": {"en": "The Free of need", "bn": "অমুখাপেক্ষী"}}]}', '{"en": "Ar-Rahman, Ar-Razzaq, Al-‘Alim, Al-Quddus, Al-Ghani.", "bn": "আর-রহমান, আর-রাযযাক, আল-আলিম, আল-কুদ্দুস, আল-গনি।"}', 'Quran 1:3; Quran 51:58; Quran 2:32; Quran 59:23; Quran 35:15', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6fe13f79-6471-5177-b500-b77e98b5b081', '1b0ffe23-553d-5a52-88ab-2387c01fd23b', 'choice', '{"en": "What does Al-Wadud (الودود) mean?", "bn": "আল-ওয়াদুদ (الودود) অর্থ কী?"}', '{"options": [{"en": "The Subduer of all", "bn": "মহাপ্রতাপশালী, সবকিছুর ওপর পরাক্রমশালী"}, {"en": "The Hidden", "bn": "গোপন"}, {"en": "The Loving", "bn": "প্রেমময়"}, {"en": "The Compeller, who sets right", "bn": "মহাপ্রতাপশালী, যিনি সব ঠিক করে দেন"}], "correct": 2}', '{"en": "Al-Wadud: The Loving.", "bn": "আল-ওয়াদুদ: প্রেমময়।"}', 'Quran 85:14', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('05ea83d8-f0aa-5a03-b17b-5666826f4fb2', '1b0ffe23-553d-5a52-88ab-2387c01fd23b', 'choice', '{"en": "What does Al-Khabir (الخبير) mean?", "bn": "আল-খাবির (الخبير) অর্থ কী?"}', '{"options": [{"en": "The Most Generous", "bn": "মহাদয়ালু, মহানুভব"}, {"en": "The All-Aware", "bn": "সম্যক অবগত"}, {"en": "The Last", "bn": "অন্ত (সর্বশেষ)"}, {"en": "The Source of peace", "bn": "শান্তির উৎস"}], "correct": 1}', '{"en": "Al-Khabir: The All-Aware.", "bn": "আল-খাবির: সম্যক অবগত।"}', 'Quran 67:14', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('81eda12e-14a2-5adf-9444-1ba50d1770f5', '1b0ffe23-553d-5a52-88ab-2387c01fd23b', 'choice', '{"en": "Which name means \"The Ever-Living\"?", "bn": "কোন নামের অর্থ \"চিরঞ্জীব\"?"}', '{"options": [{"ar": "الحي"}, {"ar": "النور"}, {"ar": "الحكيم"}, {"ar": "الشكور"}], "correct": 0}', '{"en": "Al-Hayy: The Ever-Living.", "bn": "আল-হাইয়ু: চিরঞ্জীব।"}', 'Quran 2:255', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('50b8cafc-43ee-5c68-9676-2ad93ed42480', '1b0ffe23-553d-5a52-88ab-2387c01fd23b', 'choice', '{"en": "Which name means \"The Accepter of repentance\"?", "bn": "কোন নামের অর্থ \"তওবা কবুলকারী\"?"}', '{"options": [{"ar": "العلي"}, {"ar": "المؤمن"}, {"ar": "الفتاح"}, {"ar": "التواب"}], "correct": 3}', '{"en": "At-Tawwab: The Accepter of repentance.", "bn": "আত-তাওয়াব: তওবা কবুলকারী।"}', 'Quran 2:37', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('933fc588-0c5b-545c-a930-21d7c38b44b8', '1b0ffe23-553d-5a52-88ab-2387c01fd23b', 'match', '{"en": "Match each name to its meaning", "bn": "প্রতিটি নামের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "الملك"}, "right": {"en": "The King, the Sovereign", "bn": "অধিপতি, সার্বভৌম"}}, {"left": {"ar": "البصير"}, "right": {"en": "The All-Seeing", "bn": "সর্বদ্রষ্টা"}}, {"left": {"ar": "الوكيل"}, "right": {"en": "The Trustee", "bn": "কর্মবিধায়ক, ভরসাস্থল"}}, {"left": {"ar": "الأول"}, "right": {"en": "The First", "bn": "আদি (সর্বপ্রথম)"}}]}', '{"en": "Al-Malik, Al-Basir, Al-Wakil, Al-Awwal.", "bn": "আল-মালিক, আল-বাসির, আল-ওয়াকিল, আল-আউয়াল।"}', 'Quran 59:23; Quran 42:11; Quran 3:173; Quran 57:3', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_sections (id, category_id, title, description, sort_order) SELECT 'fd3ba4f3-84f0-51c0-bd1a-fcba486fdfb5', c.id, '{"en": "Meanings of the short surahs", "bn": "ছোট সূরার অর্থ"}', '{"en": "Match each ayah of the short surahs to its meaning, so you understand what you recite.", "bn": "ছোট সূরাগুলোর প্রতিটি আয়াতের অর্থ মিলিয়ে শিখুন, যাতে যা পড়েন তা বোঝেন।"}', 10 FROM is_learn_categories c WHERE c.id = 'b0639b78-f121-5b35-9592-9da250c09dac' ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('4e2a2593-b098-56f7-973c-98f6184e08cb', '{"en": "Meanings: Al-Fatiha & the last three", "bn": "অর্থ: আল-ফাতিহা ও শেষ তিন সূরা"}', '{"en": "Know what you recite every day: al-Fatiha, al-Ikhlas, al-Falaq and an-Nas.", "bn": "প্রতিদিন যা পড়ি তার অর্থ: ফাতিহা, ইখলাস, ফালাক ও নাস।"}', NULL, 'book-open', 'in_review', 1, (SELECT s.id FROM is_learn_sections s WHERE s.id = 'fd3ba4f3-84f0-51c0-bd1a-fcba486fdfb5')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('8b11e995-154f-5cda-a0a9-c338662192e1', '4e2a2593-b098-56f7-973c-98f6184e08cb', '{"en": "Surah Al-Fatiha: meaning", "bn": "সূরা আল-ফাতিহা: অর্থ"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eb58a6b8-ac1c-5f0a-b3db-addc7bc37af5', '8b11e995-154f-5cda-a0a9-c338662192e1', 'order', '{"en": "Put the meanings of Surah Al-Fatiha in order", "bn": "সূরা আল-ফাতিহা-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}, {"en": "All praise is for Allah, Lord of all the worlds.", "bn": "সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}, {"en": "The Entirely Merciful, the Especially Merciful.", "bn": "যিনি পরম করুণাময়, অতি দয়ালু।"}, {"en": "Master of the Day of Judgement.", "bn": "বিচার দিবসের মালিক।"}, {"en": "You alone we worship, and You alone we ask for help.", "bn": "আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই।"}, {"en": "Guide us to the straight path —", "bn": "আমাদের সরল পথ দেখান —"}, {"en": "the path of those You have blessed, not of those who earned anger, nor of those who went astray.", "bn": "তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Fatiha, one after another.", "bn": "সূরা আল-ফাতিহা-এর আয়াতগুলো পরপর।"}', 'Quran 1', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('aa317de8-575a-5cbd-9c39-e789e0efb846', '8b11e995-154f-5cda-a0a9-c338662192e1', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ"}, "right": {"en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}}, {"left": {"ar": "ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ"}, "right": {"en": "All praise is for Allah, Lord of all the worlds.", "bn": "সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}}, {"left": {"ar": "ٱلرَّحْمَٰنِ ٱلرَّحِيمِ"}, "right": {"en": "The Entirely Merciful, the Especially Merciful.", "bn": "যিনি পরম করুণাময়, অতি দয়ালু।"}}, {"left": {"ar": "مَٰلِكِ يَوْمِ ٱلدِّينِ"}, "right": {"en": "Master of the Day of Judgement.", "bn": "বিচার দিবসের মালিক।"}}]}', '{"en": "Surah Al-Fatiha.", "bn": "সূরা আল-ফাতিহা।"}', 'Quran 1:1–4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0ec49d71-fec1-5464-8638-5ebc77b73106', '8b11e995-154f-5cda-a0a9-c338662192e1', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ"}, "right": {"en": "You alone we worship, and You alone we ask for help.", "bn": "আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই।"}}, {"left": {"ar": "ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ"}, "right": {"en": "Guide us to the straight path —", "bn": "আমাদের সরল পথ দেখান —"}}, {"left": {"ar": "صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ"}, "right": {"en": "the path of those You have blessed, not of those who earned anger, nor of those who went astray.", "bn": "তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।"}}]}', '{"en": "Surah Al-Fatiha.", "bn": "সূরা আল-ফাতিহা।"}', 'Quran 1:5–7', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e9245f30-68ef-5450-8918-190d0d56a0bc', '8b11e995-154f-5cda-a0a9-c338662192e1', 'choice', '{"en": "What does «بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ» mean?", "bn": "«بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ» অর্থ কী?"}', '{"options": [{"en": "All praise is for Allah, Lord of all the worlds.", "bn": "সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}, {"en": "Master of the Day of Judgement.", "bn": "বিচার দিবসের মালিক।"}, {"en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}, {"en": "You alone we worship, and You alone we ask for help.", "bn": "আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই।"}], "correct": 2}', '{"en": "Surah Al-Fatiha, ayah 1: In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "সূরা আল-ফাতিহা, আয়াত ১: পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}', 'Quran 1:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6bb1f88a-6961-5a50-ad10-dd55e4cd9e96', '8b11e995-154f-5cda-a0a9-c338662192e1', 'choice', '{"en": "What does «مَٰلِكِ يَوْمِ ٱلدِّينِ» mean?", "bn": "«مَٰلِكِ يَوْمِ ٱلدِّينِ» অর্থ কী?"}', '{"options": [{"en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}, {"en": "All praise is for Allah, Lord of all the worlds.", "bn": "সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}, {"en": "Master of the Day of Judgement.", "bn": "বিচার দিবসের মালিক।"}, {"en": "The Entirely Merciful, the Especially Merciful.", "bn": "যিনি পরম করুণাময়, অতি দয়ালু।"}], "correct": 2}', '{"en": "Surah Al-Fatiha, ayah 4: Master of the Day of Judgement.", "bn": "সূরা আল-ফাতিহা, আয়াত ৪: বিচার দিবসের মালিক।"}', 'Quran 1:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('18c9d1af-58bb-50ab-bfcc-f3d150ff9df8', '8b11e995-154f-5cda-a0a9-c338662192e1', 'choice', '{"en": "What does «صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ» mean?", "bn": "«صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ» অর্থ কী?"}', '{"options": [{"en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}, {"en": "All praise is for Allah, Lord of all the worlds.", "bn": "সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}, {"en": "the path of those You have blessed, not of those who earned anger, nor of those who went astray.", "bn": "তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।"}, {"en": "The Entirely Merciful, the Especially Merciful.", "bn": "যিনি পরম করুণাময়, অতি দয়ালু।"}], "correct": 2}', '{"en": "Surah Al-Fatiha, ayah 7: the path of those You have blessed, not of those who earned anger, nor of those who went astray.", "bn": "সূরা আল-ফাতিহা, আয়াত ৭: তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।"}', 'Quran 1:7', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d9fdbe23-493a-5956-b7a1-665ba46786a0', '8b11e995-154f-5cda-a0a9-c338662192e1', 'choice', '{"en": "Which ayah means: \"All praise is for Allah, Lord of all the worlds.\"", "bn": "কোন আয়াতের অর্থ: \"সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।\""}', '{"options": [{"ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ"}, {"ar": "ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ"}, {"ar": "ٱلرَّحْمَٰنِ ٱلرَّحِيمِ"}, {"ar": "مَٰلِكِ يَوْمِ ٱلدِّينِ"}], "correct": 1}', '{"en": "Surah Al-Fatiha, ayah 2: All praise is for Allah, Lord of all the worlds.", "bn": "সূরা আল-ফাতিহা, আয়াত ২: সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}', 'Quran 1:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ffd8b865-6974-535b-b61c-260f8a4c2153', '8b11e995-154f-5cda-a0a9-c338662192e1', 'true_false', '{"en": "«صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ» means: \"the path of those You have blessed, not of those who earned anger, nor of those who went astray.\"", "bn": "«صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ» অর্থ: \"তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।\""}', '{"answer": true}', '{"en": "Surah Al-Fatiha, ayah 7: the path of those You have blessed, not of those who earned anger, nor of those who went astray.", "bn": "সূরা আল-ফাতিহা, আয়াত ৭: তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।"}', 'Quran 1:7', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('14b6fdde-8f3b-53c3-a690-7d1f1801d04b', '8b11e995-154f-5cda-a0a9-c338662192e1', 'true_false', '{"en": "«بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ» means: \"All praise is for Allah, Lord of all the worlds.\"", "bn": "«بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ» অর্থ: \"সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।\""}', '{"answer": false}', '{"en": "Surah Al-Fatiha, ayah 1: In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "সূরা আল-ফাতিহা, আয়াত ১: পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}', 'Quran 1:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('eb22dd7b-5110-5b03-b003-f444300146c4', '4e2a2593-b098-56f7-973c-98f6184e08cb', '{"en": "Surah Al-Ikhlas: meaning", "bn": "সূরা আল-ইখলাস: অর্থ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ca17bad8-9126-5494-879b-02bde3d7852f', 'eb22dd7b-5110-5b03-b003-f444300146c4', 'order', '{"en": "Put the meanings of Surah Al-Ikhlas in order", "bn": "সূরা আল-ইখলাস-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Say: He is Allah, the One.", "bn": "বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}, {"en": "Allah, the Self-Sufficient, whom all need.", "bn": "আল্লাহ অমুখাপেক্ষী, সবাই তাঁর মুখাপেক্ষী।"}, {"en": "He neither begets nor was He begotten.", "bn": "তিনি কাউকে জন্ম দেননি এবং কারো থেকে জন্ম নেননি।"}, {"en": "And there is none comparable to Him.", "bn": "এবং তাঁর সমতুল্য কেউ নেই।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Ikhlas, one after another.", "bn": "সূরা আল-ইখলাস-এর আয়াতগুলো পরপর।"}', 'Quran 112', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e29d695f-98c6-5565-a958-590f430fc8d4', 'eb22dd7b-5110-5b03-b003-f444300146c4', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "قُلْ هُوَ ٱللَّهُ أَحَدٌ"}, "right": {"en": "Say: He is Allah, the One.", "bn": "বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}}, {"left": {"ar": "ٱللَّهُ ٱلصَّمَدُ"}, "right": {"en": "Allah, the Self-Sufficient, whom all need.", "bn": "আল্লাহ অমুখাপেক্ষী, সবাই তাঁর মুখাপেক্ষী।"}}, {"left": {"ar": "لَمْ يَلِدْ وَلَمْ يُولَدْ"}, "right": {"en": "He neither begets nor was He begotten.", "bn": "তিনি কাউকে জন্ম দেননি এবং কারো থেকে জন্ম নেননি।"}}, {"left": {"ar": "وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ"}, "right": {"en": "And there is none comparable to Him.", "bn": "এবং তাঁর সমতুল্য কেউ নেই।"}}]}', '{"en": "Surah Al-Ikhlas.", "bn": "সূরা আল-ইখলাস।"}', 'Quran 112:1–4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('270cea9e-1202-5923-8510-e7ab6e6f66f8', 'eb22dd7b-5110-5b03-b003-f444300146c4', 'choice', '{"en": "What does «قُلْ هُوَ ٱللَّهُ أَحَدٌ» mean?", "bn": "«قُلْ هُوَ ٱللَّهُ أَحَدٌ» অর্থ কী?"}', '{"options": [{"en": "Allah, the Self-Sufficient, whom all need.", "bn": "আল্লাহ অমুখাপেক্ষী, সবাই তাঁর মুখাপেক্ষী।"}, {"en": "Say: He is Allah, the One.", "bn": "বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}, {"en": "He neither begets nor was He begotten.", "bn": "তিনি কাউকে জন্ম দেননি এবং কারো থেকে জন্ম নেননি।"}, {"en": "And there is none comparable to Him.", "bn": "এবং তাঁর সমতুল্য কেউ নেই।"}], "correct": 1}', '{"en": "Surah Al-Ikhlas, ayah 1: Say: He is Allah, the One.", "bn": "সূরা আল-ইখলাস, আয়াত ১: বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}', 'Quran 112:1', 3) ON CONFLICT (id) DO NOTHING;
