INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2c396cea-a6d5-5545-a8d6-0fceb14429db', 'eb22dd7b-5110-5b03-b003-f444300146c4', 'true_false', '{"en": "«قُلْ هُوَ ٱللَّهُ أَحَدٌ» means: \"Allah, the Self-Sufficient, whom all need.\"", "bn": "«قُلْ هُوَ ٱللَّهُ أَحَدٌ» অর্থ: \"আল্লাহ অমুখাপেক্ষী, সবাই তাঁর মুখাপেক্ষী।\""}', '{"answer": false}', '{"en": "Surah Al-Ikhlas, ayah 1: Say: He is Allah, the One.", "bn": "সূরা আল-ইখলাস, আয়াত ১: বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}', 'Quran 112:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b71f746e-9047-557a-883e-42066f788610', '4e2a2593-b098-56f7-973c-98f6184e08cb', '{"en": "Surah Al-Falaq: meaning", "bn": "সূরা আল-ফালাক: অর্থ"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dacf5dc8-233e-52ec-8824-751d01d811b8', 'b71f746e-9047-557a-883e-42066f788610', 'order', '{"en": "Put the meanings of Surah Al-Falaq in order", "bn": "সূরা আল-ফালাক-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Say: I seek refuge with the Lord of daybreak,", "bn": "বলুন: আমি আশ্রয় চাই ঊষার রবের কাছে,"}, {"en": "from the evil of what He created,", "bn": "তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে,"}, {"en": "and from the evil of darkness when it settles,", "bn": "এবং রাতের অন্ধকারের অনিষ্ট থেকে, যখন তা ছেয়ে যায়,"}, {"en": "and from the evil of those who blow on knots,", "bn": "এবং গিরায় ফুঁ দেয় এমন (জাদুকর) নারীদের অনিষ্ট থেকে,"}, {"en": "and from the evil of an envier when he envies.", "bn": "এবং হিংসুকের অনিষ্ট থেকে, যখন সে হিংসা করে।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Falaq, one after another.", "bn": "সূরা আল-ফালাক-এর আয়াতগুলো পরপর।"}', 'Quran 113', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('902ddd78-41fd-5014-9a48-a4f92ae539d3', 'b71f746e-9047-557a-883e-42066f788610', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ"}, "right": {"en": "Say: I seek refuge with the Lord of daybreak,", "bn": "বলুন: আমি আশ্রয় চাই ঊষার রবের কাছে,"}}, {"left": {"ar": "مِن شَرِّ مَا خَلَقَ"}, "right": {"en": "from the evil of what He created,", "bn": "তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে,"}}, {"left": {"ar": "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ"}, "right": {"en": "and from the evil of darkness when it settles,", "bn": "এবং রাতের অন্ধকারের অনিষ্ট থেকে, যখন তা ছেয়ে যায়,"}}]}', '{"en": "Surah Al-Falaq.", "bn": "সূরা আল-ফালাক।"}', 'Quran 113:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4890afb7-730e-5a00-aa30-7892df9fb9ae', 'b71f746e-9047-557a-883e-42066f788610', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ"}, "right": {"en": "and from the evil of those who blow on knots,", "bn": "এবং গিরায় ফুঁ দেয় এমন (জাদুকর) নারীদের অনিষ্ট থেকে,"}}, {"left": {"ar": "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ"}, "right": {"en": "and from the evil of an envier when he envies.", "bn": "এবং হিংসুকের অনিষ্ট থেকে, যখন সে হিংসা করে।"}}]}', '{"en": "Surah Al-Falaq.", "bn": "সূরা আল-ফালাক।"}', 'Quran 113:4–5', 3) ON CONFLICT (id) DO NOTHING;
