INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bbf05744-abb5-5e16-b01a-60a81dcbce5a', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'order', '{"en": "Put the meanings of Surah An-Nas in order", "bn": "সূরা আন-নাস-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Say: I seek refuge with the Lord of mankind,", "bn": "বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}, {"en": "the King of mankind,", "bn": "মানুষের অধিপতির কাছে,"}, {"en": "the God of mankind,", "bn": "মানুষের ইলাহের কাছে,"}, {"en": "from the evil of the retreating whisperer,", "bn": "আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,"}, {"en": "who whispers in the hearts of mankind,", "bn": "যে মানুষের অন্তরে কুমন্ত্রণা দেয়,"}, {"en": "from among the jinn and mankind.", "bn": "জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}], "rtl": false}', '{"en": "The ayahs of Surah An-Nas, one after another.", "bn": "সূরা আন-নাস-এর আয়াতগুলো পরপর।"}', 'Quran 114', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('303a444f-1031-5a76-bab5-c9592e2a0a87', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ"}, "right": {"en": "Say: I seek refuge with the Lord of mankind,", "bn": "বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}}, {"left": {"ar": "مَلِكِ ٱلنَّاسِ"}, "right": {"en": "the King of mankind,", "bn": "মানুষের অধিপতির কাছে,"}}, {"left": {"ar": "إِلَٰهِ ٱلنَّاسِ"}, "right": {"en": "the God of mankind,", "bn": "মানুষের ইলাহের কাছে,"}}]}', '{"en": "Surah An-Nas.", "bn": "সূরা আন-নাস।"}', 'Quran 114:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('391727b6-899d-5e19-9865-9f36497c8952', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ"}, "right": {"en": "from the evil of the retreating whisperer,", "bn": "আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,"}}, {"left": {"ar": "ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ"}, "right": {"en": "who whispers in the hearts of mankind,", "bn": "যে মানুষের অন্তরে কুমন্ত্রণা দেয়,"}}, {"left": {"ar": "مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ"}, "right": {"en": "from among the jinn and mankind.", "bn": "জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}}]}', '{"en": "Surah An-Nas.", "bn": "সূরা আন-নাস।"}', 'Quran 114:4–6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b8397662-ddb1-5974-a94f-26c58f22fc6a', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'choice', '{"en": "What does «قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ» mean?", "bn": "«قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ» অর্থ কী?"}', '{"options": [{"en": "from the evil of the retreating whisperer,", "bn": "আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,"}, {"en": "who whispers in the hearts of mankind,", "bn": "যে মানুষের অন্তরে কুমন্ত্রণা দেয়,"}, {"en": "from among the jinn and mankind.", "bn": "জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}, {"en": "Say: I seek refuge with the Lord of mankind,", "bn": "বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}], "correct": 3}', '{"en": "Surah An-Nas, ayah 1: Say: I seek refuge with the Lord of mankind,", "bn": "সূরা আন-নাস, আয়াত ১: বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}', 'Quran 114:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('29d42178-3b0f-5dcc-8384-b2d2fb72f38c', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'choice', '{"en": "What does «مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ» mean?", "bn": "«مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ» অর্থ কী?"}', '{"options": [{"en": "Say: I seek refuge with the Lord of mankind,", "bn": "বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}, {"en": "the King of mankind,", "bn": "মানুষের অধিপতির কাছে,"}, {"en": "the God of mankind,", "bn": "মানুষের ইলাহের কাছে,"}, {"en": "from the evil of the retreating whisperer,", "bn": "আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,"}], "correct": 3}', '{"en": "Surah An-Nas, ayah 4: from the evil of the retreating whisperer,", "bn": "সূরা আন-নাস, আয়াত ৪: আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,"}', 'Quran 114:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e1569d43-a7d2-505a-bcad-1c05e8f501a4', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'choice', '{"en": "What does «مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ» mean?", "bn": "«مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ» অর্থ কী?"}', '{"options": [{"en": "Say: I seek refuge with the Lord of mankind,", "bn": "বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}, {"en": "the King of mankind,", "bn": "মানুষের অধিপতির কাছে,"}, {"en": "from among the jinn and mankind.", "bn": "জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}, {"en": "the God of mankind,", "bn": "মানুষের ইলাহের কাছে,"}], "correct": 2}', '{"en": "Surah An-Nas, ayah 6: from among the jinn and mankind.", "bn": "সূরা আন-নাস, আয়াত ৬: জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}', 'Quran 114:6', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e18be556-59fd-5c84-8e12-00cd2ee32fd4', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'choice', '{"en": "Which ayah means: \"the King of mankind,\"", "bn": "কোন আয়াতের অর্থ: \"মানুষের অধিপতির কাছে,\""}', '{"options": [{"ar": "مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ"}, {"ar": "ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ"}, {"ar": "مَلِكِ ٱلنَّاسِ"}, {"ar": "مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ"}], "correct": 2}', '{"en": "Surah An-Nas, ayah 2: the King of mankind,", "bn": "সূরা আন-নাস, আয়াত ২: মানুষের অধিপতির কাছে,"}', 'Quran 114:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8239fa30-7786-5bb5-baab-0aa96e996e2b', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'true_false', '{"en": "«مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ» means: \"from among the jinn and mankind.\"", "bn": "«مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ» অর্থ: \"জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।\""}', '{"answer": true}', '{"en": "Surah An-Nas, ayah 6: from among the jinn and mankind.", "bn": "সূরা আন-নাস, আয়াত ৬: জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}', 'Quran 114:6', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5efdae08-d6c2-5597-a3f5-7b61ee11786c', '7e44724a-657f-568f-b78e-a238c02a1b9c', 'true_false', '{"en": "«قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ» means: \"from the evil of the retreating whisperer,\"", "bn": "«قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ» অর্থ: \"আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,\""}', '{"answer": false}', '{"en": "Surah An-Nas, ayah 1: Say: I seek refuge with the Lord of mankind,", "bn": "সূরা আন-নাস, আয়াত ১: বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}', 'Quran 114:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('e44eec17-41eb-54c1-9238-9061e1876f42', '4e2a2593-b098-56f7-973c-98f6184e08cb', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1823042d-ac6b-500c-bca0-eee298d6ad7c', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "Which surah has the ayah meaning: \"the path of those You have blessed, not of those who earned anger, nor of those who went astray.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।\""}', '{"options": [{"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Falaq", "bn": "আল-ফালাক"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 1}', '{"en": "Surah Al-Fatiha, ayah 7: the path of those You have blessed, not of those who earned anger, nor of those who went astray.", "bn": "সূরা আল-ফাতিহা, আয়াত ৭: তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের নয় যারা গজবপ্রাপ্ত, এবং তাদেরও নয় যারা পথভ্রষ্ট।"}', 'Quran 1:7', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7e6e9a2c-0c84-5b13-9940-130af9ebce97', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "Which surah has the ayah meaning: \"And there is none comparable to Him.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"এবং তাঁর সমতুল্য কেউ নেই।\""}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Falaq", "bn": "আল-ফালাক"}, {"en": "An-Nas", "bn": "আন-নাস"}], "correct": 1}', '{"en": "Surah Al-Ikhlas, ayah 4: And there is none comparable to Him.", "bn": "সূরা আল-ইখলাস, আয়াত ৪: এবং তাঁর সমতুল্য কেউ নেই।"}', 'Quran 112:4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1b43496c-55c1-5d05-ba5a-d42dc11eca51', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "Which surah has the ayah meaning: \"and from the evil of an envier when he envies.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"এবং হিংসুকের অনিষ্ট থেকে, যখন সে হিংসা করে।\""}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "An-Nas", "bn": "আন-নাস"}, {"en": "Al-Falaq", "bn": "আল-ফালাক"}], "correct": 3}', '{"en": "Surah Al-Falaq, ayah 5: and from the evil of an envier when he envies.", "bn": "সূরা আল-ফালাক, আয়াত ৫: এবং হিংসুকের অনিষ্ট থেকে, যখন সে হিংসা করে।"}', 'Quran 113:5', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4c12ff61-2086-5bf2-85ea-b567408c742d', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "Which surah has the ayah meaning: \"from among the jinn and mankind.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।\""}', '{"options": [{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}, {"en": "An-Nas", "bn": "আন-নাস"}, {"en": "Al-Ikhlas", "bn": "আল-ইখলাস"}, {"en": "Al-Falaq", "bn": "আল-ফালাক"}], "correct": 1}', '{"en": "Surah An-Nas, ayah 6: from among the jinn and mankind.", "bn": "সূরা আন-নাস, আয়াত ৬: জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}', 'Quran 114:6', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('012879c8-a4a7-5007-a24b-aa4c37705545', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "What does «بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ» mean?", "bn": "«بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ» অর্থ কী?"}', '{"options": [{"en": "All praise is for Allah, Lord of all the worlds.", "bn": "সকল প্রশংসা আল্লাহর, যিনি সকল জগতের রব।"}, {"en": "Master of the Day of Judgement.", "bn": "বিচার দিবসের মালিক।"}, {"en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}, {"en": "You alone we worship, and You alone we ask for help.", "bn": "আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই।"}], "correct": 2}', '{"en": "Surah Al-Fatiha, ayah 1: In the name of Allah, the Entirely Merciful, the Especially Merciful.", "bn": "সূরা আল-ফাতিহা, আয়াত ১: পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।"}', 'Quran 1:1', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9188d009-440f-523d-ac50-076f90d5d267', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "What does «قُلْ هُوَ ٱللَّهُ أَحَدٌ» mean?", "bn": "«قُلْ هُوَ ٱللَّهُ أَحَدٌ» অর্থ কী?"}', '{"options": [{"en": "Allah, the Self-Sufficient, whom all need.", "bn": "আল্লাহ অমুখাপেক্ষী, সবাই তাঁর মুখাপেক্ষী।"}, {"en": "Say: He is Allah, the One.", "bn": "বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}, {"en": "He neither begets nor was He begotten.", "bn": "তিনি কাউকে জন্ম দেননি এবং কারো থেকে জন্ম নেননি।"}, {"en": "And there is none comparable to Him.", "bn": "এবং তাঁর সমতুল্য কেউ নেই।"}], "correct": 1}', '{"en": "Surah Al-Ikhlas, ayah 1: Say: He is Allah, the One.", "bn": "সূরা আল-ইখলাস, আয়াত ১: বলুন: তিনিই আল্লাহ, এক-অদ্বিতীয়।"}', 'Quran 112:1', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f3d5be09-5775-57d5-8adf-c19a6a8a2daf', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "What does «قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ» mean?", "bn": "«قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ» অর্থ কী?"}', '{"options": [{"en": "Say: I seek refuge with the Lord of daybreak,", "bn": "বলুন: আমি আশ্রয় চাই ঊষার রবের কাছে,"}, {"en": "from the evil of what He created,", "bn": "তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে,"}, {"en": "and from the evil of darkness when it settles,", "bn": "এবং রাতের অন্ধকারের অনিষ্ট থেকে, যখন তা ছেয়ে যায়,"}, {"en": "and from the evil of those who blow on knots,", "bn": "এবং গিরায় ফুঁ দেয় এমন (জাদুকর) নারীদের অনিষ্ট থেকে,"}], "correct": 0}', '{"en": "Surah Al-Falaq, ayah 1: Say: I seek refuge with the Lord of daybreak,", "bn": "সূরা আল-ফালাক, আয়াত ১: বলুন: আমি আশ্রয় চাই ঊষার রবের কাছে,"}', 'Quran 113:1', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7e35bc02-9b1a-5247-b820-06743c197ccd', 'e44eec17-41eb-54c1-9238-9061e1876f42', 'choice', '{"en": "What does «قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ» mean?", "bn": "«قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ» অর্থ কী?"}', '{"options": [{"en": "from the evil of the retreating whisperer,", "bn": "আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে,"}, {"en": "who whispers in the hearts of mankind,", "bn": "যে মানুষের অন্তরে কুমন্ত্রণা দেয়,"}, {"en": "from among the jinn and mankind.", "bn": "জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।"}, {"en": "Say: I seek refuge with the Lord of mankind,", "bn": "বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}], "correct": 3}', '{"en": "Surah An-Nas, ayah 1: Say: I seek refuge with the Lord of mankind,", "bn": "সূরা আন-নাস, আয়াত ১: বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,"}', 'Quran 114:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('e9a2d3c2-7314-56f2-b45a-617223bd923b', '{"en": "Meanings: Al-‘Asr to Al-Masad", "bn": "অর্থ: আল-আসর থেকে আল-মাসাদ"}', '{"en": "Al-‘Asr, al-Kawthar, al-Kafirun, an-Nasr and al-Masad.", "bn": "আসর, কাওসার, কাফিরুন, নাসর ও মাসাদ।"}', NULL, 'book-open', 'in_review', 2, (SELECT s.id FROM is_learn_sections s WHERE s.id = 'fd3ba4f3-84f0-51c0-bd1a-fcba486fdfb5')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('7f34b674-d18f-55a4-b116-0866f2683f88', 'e9a2d3c2-7314-56f2-b45a-617223bd923b', '{"en": "Surah Al-‘Asr: meaning", "bn": "সূরা আল-আসর: অর্থ"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8288b9a9-a436-523a-84b7-6b557f9ad59c', '7f34b674-d18f-55a4-b116-0866f2683f88', 'order', '{"en": "Put the meanings of Surah Al-‘Asr in order", "bn": "সূরা আল-আসর-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "Indeed, mankind is in loss,", "bn": "নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}, {"en": "except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-‘Asr, one after another.", "bn": "সূরা আল-আসর-এর আয়াতগুলো পরপর।"}', 'Quran 103', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7ed2b56b-c951-50e9-85a8-e33d8db3cef7', '7f34b674-d18f-55a4-b116-0866f2683f88', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "وَٱلْعَصْرِ"}, "right": {"en": "By time!", "bn": "সময়ের শপথ!"}}, {"left": {"ar": "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ"}, "right": {"en": "Indeed, mankind is in loss,", "bn": "নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}}, {"left": {"ar": "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ"}, "right": {"en": "except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}}]}', '{"en": "Surah Al-‘Asr.", "bn": "সূরা আল-আসর।"}', 'Quran 103:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6310e8d0-ed92-5d6f-ad9f-f57bfc64bebb', '7f34b674-d18f-55a4-b116-0866f2683f88', 'choice', '{"en": "What does «وَٱلْعَصْرِ» mean?", "bn": "«وَٱلْعَصْرِ» অর্থ কী?"}', '{"options": [{"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "Indeed, mankind is in loss,", "bn": "নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}, {"en": "except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}, {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}], "correct": 0}', '{"en": "Surah Al-‘Asr, ayah 1: By time!", "bn": "সূরা আল-আসর, আয়াত ১: সময়ের শপথ!"}', 'Quran 103:1', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5e6aa0c1-1d1a-5b05-9eed-d2da031ffbb9', '7f34b674-d18f-55a4-b116-0866f2683f88', 'choice', '{"en": "What does «إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ» mean?", "bn": "«إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ» অর্থ কী?"}', '{"options": [{"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}, {"en": "Indeed, mankind is in loss,", "bn": "নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}, {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}], "correct": 2}', '{"en": "Surah Al-‘Asr, ayah 2: Indeed, mankind is in loss,", "bn": "সূরা আল-আসর, আয়াত ২: নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}', 'Quran 103:2', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('94920b4f-b0cc-533d-8937-a095b8466211', '7f34b674-d18f-55a4-b116-0866f2683f88', 'choice', '{"en": "What does «إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ» mean?", "bn": "«إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ» অর্থ কী?"}', '{"options": [{"en": "except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "Indeed, mankind is in loss,", "bn": "নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}, {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}], "correct": 0}', '{"en": "Surah Al-‘Asr, ayah 3: except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "সূরা আল-আসর, আয়াত ৩: তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}', 'Quran 103:3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('904bd9e2-2ddf-5fcc-a15e-d5f2027a9a5a', '7f34b674-d18f-55a4-b116-0866f2683f88', 'choice', '{"en": "Which ayah means: \"Indeed, mankind is in loss,\"", "bn": "কোন আয়াতের অর্থ: \"নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,\""}', '{"options": [{"ar": "وَٱلْعَصْرِ"}, {"ar": "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ"}, {"ar": "إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ"}, {"ar": "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ"}], "correct": 3}', '{"en": "Surah Al-‘Asr, ayah 2: Indeed, mankind is in loss,", "bn": "সূরা আল-আসর, আয়াত ২: নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}', 'Quran 103:2', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('db0f3082-6c16-5586-9251-2071aab26ca4', '7f34b674-d18f-55a4-b116-0866f2683f88', 'true_false', '{"en": "«إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ» means: \"except those who believe, do righteous deeds, and urge one another to the truth and to patience.\"", "bn": "«إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ» অর্থ: \"তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।\""}', '{"answer": true}', '{"en": "Surah Al-‘Asr, ayah 3: except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "সূরা আল-আসর, আয়াত ৩: তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}', 'Quran 103:3', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2096a28a-f6e4-5cbf-96c8-231fadd64e9f', '7f34b674-d18f-55a4-b116-0866f2683f88', 'true_false', '{"en": "«وَٱلْعَصْرِ» means: \"Indeed, mankind is in loss,\"", "bn": "«وَٱلْعَصْرِ» অর্থ: \"নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,\""}', '{"answer": false}', '{"en": "Surah Al-‘Asr, ayah 1: By time!", "bn": "সূরা আল-আসর, আয়াত ১: সময়ের শপথ!"}', 'Quran 103:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('50bbdcd6-2a2b-5f79-8712-689e7f6a9de9', 'e9a2d3c2-7314-56f2-b45a-617223bd923b', '{"en": "Surah Al-Kawthar: meaning", "bn": "সূরা আল-কাওসার: অর্থ"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d381de2d-f3b3-5fa1-a455-3b808037f06c', '50bbdcd6-2a2b-5f79-8712-689e7f6a9de9', 'order', '{"en": "Put the meanings of Surah Al-Kawthar in order", "bn": "সূরা আল-কাওসার-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}, {"en": "So pray to your Lord and sacrifice.", "bn": "অতএব আপনার রবের উদ্দেশে নামাজ পড়ুন ও কুরবানি করুন।"}, {"en": "Indeed, it is your enemy who is cut off.", "bn": "নিশ্চয় আপনার শত্রুই শিকড়কাটা (নির্বংশ)।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Kawthar, one after another.", "bn": "সূরা আল-কাওসার-এর আয়াতগুলো পরপর।"}', 'Quran 108', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5da8808c-322e-5ef3-81af-e7bb5ae2fd63', '50bbdcd6-2a2b-5f79-8712-689e7f6a9de9', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ"}, "right": {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}}, {"left": {"ar": "فَصَلِّ لِرَبِّكَ وَٱنْحَرْ"}, "right": {"en": "So pray to your Lord and sacrifice.", "bn": "অতএব আপনার রবের উদ্দেশে নামাজ পড়ুন ও কুরবানি করুন।"}}, {"left": {"ar": "إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ"}, "right": {"en": "Indeed, it is your enemy who is cut off.", "bn": "নিশ্চয় আপনার শত্রুই শিকড়কাটা (নির্বংশ)।"}}]}', '{"en": "Surah Al-Kawthar.", "bn": "সূরা আল-কাওসার।"}', 'Quran 108:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('535bf945-f6fe-54ea-aec3-3e7c7f86e717', '50bbdcd6-2a2b-5f79-8712-689e7f6a9de9', 'choice', '{"en": "What does «إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ» mean?", "bn": "«إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ» অর্থ কী?"}', '{"options": [{"en": "So pray to your Lord and sacrifice.", "bn": "অতএব আপনার রবের উদ্দেশে নামাজ পড়ুন ও কুরবানি করুন।"}, {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}, {"en": "Indeed, it is your enemy who is cut off.", "bn": "নিশ্চয় আপনার শত্রুই শিকড়কাটা (নির্বংশ)।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}], "correct": 1}', '{"en": "Surah Al-Kawthar, ayah 1: Indeed, We have given you al-Kawthar (abundant good).", "bn": "সূরা আল-কাওসার, আয়াত ১: নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}', 'Quran 108:1', 3) ON CONFLICT (id) DO NOTHING;
