INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3476193a-2be5-568a-86ba-5ea2f993ad9d', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'order', '{"en": "Put the meanings of Surah Al-Kafirun in order", "bn": "সূরা আল-কাফিরুন-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Say: O disbelievers,", "bn": "বলুন: হে কাফিররা,"}, {"en": "I do not worship what you worship,", "bn": "আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,"}, {"en": "nor do you worship what I worship,", "bn": "এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}, {"en": "nor will I worship what you have worshipped,", "bn": "আর আমি তার ইবাদতকারী নই, যার ইবাদত তোমরা করেছ,"}, {"en": "nor will you worship what I worship.", "bn": "এবং তোমরাও তাঁর ইবাদতকারী হবে না, যাঁর ইবাদত আমি করি।"}, {"en": "For you is your religion, and for me is mine.", "bn": "তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Kafirun, one after another.", "bn": "সূরা আল-কাফিরুন-এর আয়াতগুলো পরপর।"}', 'Quran 109', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a9f122d7-1523-51e2-bfa2-86d1f1bad2af', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ"}, "right": {"en": "Say: O disbelievers,", "bn": "বলুন: হে কাফিররা,"}}, {"left": {"ar": "لَآ أَعْبُدُ مَا تَعْبُدُونَ"}, "right": {"en": "I do not worship what you worship,", "bn": "আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,"}}, {"left": {"ar": "وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ"}, "right": {"en": "nor do you worship what I worship,", "bn": "এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}}]}', '{"en": "Surah Al-Kafirun.", "bn": "সূরা আল-কাফিরুন।"}', 'Quran 109:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('acea3159-5f97-54e4-9c4a-a5941f11bfa0', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ"}, "right": {"en": "nor will I worship what you have worshipped,", "bn": "আর আমি তার ইবাদতকারী নই, যার ইবাদত তোমরা করেছ,"}}, {"left": {"ar": "لَكُمْ دِينُكُمْ وَلِىَ دِينِ"}, "right": {"en": "For you is your religion, and for me is mine.", "bn": "তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}}]}', '{"en": "Surah Al-Kafirun.", "bn": "সূরা আল-কাফিরুন।"}', 'Quran 109:4–6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b57af4a4-2653-5cc7-b818-d0153e1838a8', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'choice', '{"en": "What does «قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ» mean?", "bn": "«قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ» অর্থ কী?"}', '{"options": [{"en": "I do not worship what you worship,", "bn": "আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,"}, {"en": "nor do you worship what I worship,", "bn": "এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}, {"en": "Say: O disbelievers,", "bn": "বলুন: হে কাফিররা,"}, {"en": "nor will I worship what you have worshipped,", "bn": "আর আমি তার ইবাদতকারী নই, যার ইবাদত তোমরা করেছ,"}], "correct": 2}', '{"en": "Surah Al-Kafirun, ayah 1: Say: O disbelievers,", "bn": "সূরা আল-কাফিরুন, আয়াত ১: বলুন: হে কাফিররা,"}', 'Quran 109:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7c769044-9e06-5887-bcfc-0014bdd4a336', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'choice', '{"en": "What does «وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ» mean?", "bn": "«وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ» অর্থ কী?"}', '{"options": [{"en": "Say: O disbelievers,", "bn": "বলুন: হে কাফিররা,"}, {"en": "nor do you worship what I worship,", "bn": "এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}, {"en": "For you is your religion, and for me is mine.", "bn": "তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}], "correct": 1}', '{"en": "Surah Al-Kafirun, ayah 3: nor do you worship what I worship,", "bn": "সূরা আল-কাফিরুন, আয়াত ৩: এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}', 'Quran 109:3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('efd69f78-0c02-5950-938c-39a247d37cab', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'choice', '{"en": "What does «لَكُمْ دِينُكُمْ وَلِىَ دِينِ» mean?", "bn": "«لَكُمْ دِينُكُمْ وَلِىَ دِينِ» অর্থ কী?"}', '{"options": [{"en": "Say: O disbelievers,", "bn": "বলুন: হে কাফিররা,"}, {"en": "For you is your religion, and for me is mine.", "bn": "তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}, {"en": "I do not worship what you worship,", "bn": "আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,"}, {"en": "nor do you worship what I worship,", "bn": "এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}], "correct": 1}', '{"en": "Surah Al-Kafirun, ayah 6: For you is your religion, and for me is mine.", "bn": "সূরা আল-কাফিরুন, আয়াত ৬: তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}', 'Quran 109:6', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d03b520d-2136-5888-8322-05bbfa831b44', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'choice', '{"en": "Which ayah means: \"I do not worship what you worship,\"", "bn": "কোন আয়াতের অর্থ: \"আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,\""}', '{"options": [{"ar": "قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ"}, {"ar": "لَآ أَعْبُدُ مَا تَعْبُدُونَ"}, {"ar": "لَكُمْ دِينُكُمْ وَلِىَ دِينِ"}, {"ar": "وَٱلْعَصْرِ"}], "correct": 1}', '{"en": "Surah Al-Kafirun, ayah 2: I do not worship what you worship,", "bn": "সূরা আল-কাফিরুন, আয়াত ২: আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,"}', 'Quran 109:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e08b9435-c40b-59e0-bc99-3b50b4c8b92b', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'true_false', '{"en": "«لَكُمْ دِينُكُمْ وَلِىَ دِينِ» means: \"For you is your religion, and for me is mine.\"", "bn": "«لَكُمْ دِينُكُمْ وَلِىَ دِينِ» অর্থ: \"তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।\""}', '{"answer": true}', '{"en": "Surah Al-Kafirun, ayah 6: For you is your religion, and for me is mine.", "bn": "সূরা আল-কাফিরুন, আয়াত ৬: তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}', 'Quran 109:6', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('68f34f11-e2ff-59e0-b116-3d33cc360a61', '8fb7ee8a-f707-520d-b0d1-b4a1ea8c6447', 'true_false', '{"en": "«قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ» means: \"I do not worship what you worship,\"", "bn": "«قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ» অর্থ: \"আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,\""}', '{"answer": false}', '{"en": "Surah Al-Kafirun, ayah 1: Say: O disbelievers,", "bn": "সূরা আল-কাফিরুন, আয়াত ১: বলুন: হে কাফিররা,"}', 'Quran 109:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('839a4729-13b2-5a57-84cf-d7dbce16d087', 'e9a2d3c2-7314-56f2-b45a-617223bd923b', '{"en": "Surah An-Nasr: meaning", "bn": "সূরা আন-নাসর: অর্থ"}', 'lesson', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d469699b-172d-590e-bf2d-326f018b7d1d', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'order', '{"en": "Put the meanings of Surah An-Nasr in order", "bn": "সূরা আন-নাসর-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "When the help of Allah and the victory come,", "bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}, {"en": "and you see people entering Allah’s religion in crowds,", "bn": "এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}, {"en": "then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}], "rtl": false}', '{"en": "The ayahs of Surah An-Nasr, one after another.", "bn": "সূরা আন-নাসর-এর আয়াতগুলো পরপর।"}', 'Quran 110', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1db14906-6fa1-5d07-b5d2-70f91752eb0b', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ"}, "right": {"en": "When the help of Allah and the victory come,", "bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}}, {"left": {"ar": "وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا"}, "right": {"en": "and you see people entering Allah’s religion in crowds,", "bn": "এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}}, {"left": {"ar": "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا"}, "right": {"en": "then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}}]}', '{"en": "Surah An-Nasr.", "bn": "সূরা আন-নাসর।"}', 'Quran 110:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('12175608-4656-512b-a01a-314693a96d45', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'choice', '{"en": "What does «إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ» mean?", "bn": "«إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ» অর্থ কী?"}', '{"options": [{"en": "and you see people entering Allah’s religion in crowds,", "bn": "এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}, {"en": "then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "When the help of Allah and the victory come,", "bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}], "correct": 3}', '{"en": "Surah An-Nasr, ayah 1: When the help of Allah and the victory come,", "bn": "সূরা আন-নাসর, আয়াত ১: যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}', 'Quran 110:1', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0d8e0afb-64c9-5e24-8da2-d84f79354608', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'choice', '{"en": "What does «وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا» mean?", "bn": "«وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا» অর্থ কী?"}', '{"options": [{"en": "When the help of Allah and the victory come,", "bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}, {"en": "and you see people entering Allah’s religion in crowds,", "bn": "এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}, {"en": "then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}], "correct": 1}', '{"en": "Surah An-Nasr, ayah 2: and you see people entering Allah’s religion in crowds,", "bn": "সূরা আন-নাসর, আয়াত ২: এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}', 'Quran 110:2', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('395c067d-e949-58cf-bb54-43a90983313d', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'choice', '{"en": "What does «فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا» mean?", "bn": "«فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا» অর্থ কী?"}', '{"options": [{"en": "When the help of Allah and the victory come,", "bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}, {"en": "and you see people entering Allah’s religion in crowds,", "bn": "এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}, {"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}], "correct": 3}', '{"en": "Surah An-Nasr, ayah 3: then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "সূরা আন-নাসর, আয়াত ৩: তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}', 'Quran 110:3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4e439da7-2284-5408-b531-a05485455e00', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'choice', '{"en": "Which ayah means: \"and you see people entering Allah’s religion in crowds,\"", "bn": "কোন আয়াতের অর্থ: \"এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,\""}', '{"options": [{"ar": "إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ"}, {"ar": "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا"}, {"ar": "وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا"}, {"ar": "وَٱلْعَصْرِ"}], "correct": 2}', '{"en": "Surah An-Nasr, ayah 2: and you see people entering Allah’s religion in crowds,", "bn": "সূরা আন-নাসর, আয়াত ২: এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}', 'Quran 110:2', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1c88d80e-4f28-5a2c-9af0-e001f64215b8', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'true_false', '{"en": "«فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا» means: \"then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.\"", "bn": "«فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا» অর্থ: \"তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।\""}', '{"answer": true}', '{"en": "Surah An-Nasr, ayah 3: then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "সূরা আন-নাসর, আয়াত ৩: তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}', 'Quran 110:3', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e328b608-e319-5045-9fd2-e3e19da942db', '839a4729-13b2-5a57-84cf-d7dbce16d087', 'true_false', '{"en": "«إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ» means: \"and you see people entering Allah’s religion in crowds,\"", "bn": "«إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ» অর্থ: \"এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,\""}', '{"answer": false}', '{"en": "Surah An-Nasr, ayah 1: When the help of Allah and the victory come,", "bn": "সূরা আন-নাসর, আয়াত ১: যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}', 'Quran 110:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'e9a2d3c2-7314-56f2-b45a-617223bd923b', '{"en": "Surah Al-Masad: meaning", "bn": "সূরা আল-মাসাদ: অর্থ"}', 'lesson', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b4b28611-5c64-5ef4-bba4-39061d86b6a0', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'order', '{"en": "Put the meanings of Surah Al-Masad in order", "bn": "সূরা আল-মাসাদ-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "May the hands of Abu Lahab perish, and perish he has!", "bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}, {"en": "His wealth did not help him, nor what he earned.", "bn": "তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।"}, {"en": "He will burn in a Fire of blazing flame,", "bn": "অচিরেই সে লেলিহান শিখার আগুনে প্রবেশ করবে,"}, {"en": "and his wife too, the carrier of firewood,", "bn": "আর তার স্ত্রীও — যে কাঠ বহনকারিণী,"}, {"en": "around her neck a rope of palm fibre.", "bn": "তার গলায় খেজুর-আঁশের পাকানো রশি।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Masad, one after another.", "bn": "সূরা আল-মাসাদ-এর আয়াতগুলো পরপর।"}', 'Quran 111', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cae6d7c6-0902-583d-a1fb-b2e6e9129692', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ"}, "right": {"en": "May the hands of Abu Lahab perish, and perish he has!", "bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}}, {"left": {"ar": "مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ"}, "right": {"en": "His wealth did not help him, nor what he earned.", "bn": "তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।"}}, {"left": {"ar": "سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ"}, "right": {"en": "He will burn in a Fire of blazing flame,", "bn": "অচিরেই সে লেলিহান শিখার আগুনে প্রবেশ করবে,"}}]}', '{"en": "Surah Al-Masad.", "bn": "সূরা আল-মাসাদ।"}', 'Quran 111:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('233e7783-409b-518e-bd8d-2db86ff586c4', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ"}, "right": {"en": "and his wife too, the carrier of firewood,", "bn": "আর তার স্ত্রীও — যে কাঠ বহনকারিণী,"}}, {"left": {"ar": "فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ"}, "right": {"en": "around her neck a rope of palm fibre.", "bn": "তার গলায় খেজুর-আঁশের পাকানো রশি।"}}]}', '{"en": "Surah Al-Masad.", "bn": "সূরা আল-মাসাদ।"}', 'Quran 111:4–5', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('db03543d-a9b9-56c4-a897-2fdf89a7607d', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'choice', '{"en": "What does «تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ» mean?", "bn": "«تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ» অর্থ কী?"}', '{"options": [{"en": "May the hands of Abu Lahab perish, and perish he has!", "bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}, {"en": "His wealth did not help him, nor what he earned.", "bn": "তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।"}, {"en": "He will burn in a Fire of blazing flame,", "bn": "অচিরেই সে লেলিহান শিখার আগুনে প্রবেশ করবে,"}, {"en": "and his wife too, the carrier of firewood,", "bn": "আর তার স্ত্রীও — যে কাঠ বহনকারিণী,"}], "correct": 0}', '{"en": "Surah Al-Masad, ayah 1: May the hands of Abu Lahab perish, and perish he has!", "bn": "সূরা আল-মাসাদ, আয়াত ১: আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}', 'Quran 111:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3222bda8-7568-5f4c-9abf-c82e903d8920', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'choice', '{"en": "What does «سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ» mean?", "bn": "«سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ» অর্থ কী?"}', '{"options": [{"en": "May the hands of Abu Lahab perish, and perish he has!", "bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}, {"en": "His wealth did not help him, nor what he earned.", "bn": "তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।"}, {"en": "and his wife too, the carrier of firewood,", "bn": "আর তার স্ত্রীও — যে কাঠ বহনকারিণী,"}, {"en": "He will burn in a Fire of blazing flame,", "bn": "অচিরেই সে লেলিহান শিখার আগুনে প্রবেশ করবে,"}], "correct": 3}', '{"en": "Surah Al-Masad, ayah 3: He will burn in a Fire of blazing flame,", "bn": "সূরা আল-মাসাদ, আয়াত ৩: অচিরেই সে লেলিহান শিখার আগুনে প্রবেশ করবে,"}', 'Quran 111:3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c0a5ea4f-bdcb-5c12-bcab-ef83081c7809', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'choice', '{"en": "What does «فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ» mean?", "bn": "«فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ» অর্থ কী?"}', '{"options": [{"en": "May the hands of Abu Lahab perish, and perish he has!", "bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}, {"en": "His wealth did not help him, nor what he earned.", "bn": "তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।"}, {"en": "around her neck a rope of palm fibre.", "bn": "তার গলায় খেজুর-আঁশের পাকানো রশি।"}, {"en": "He will burn in a Fire of blazing flame,", "bn": "অচিরেই সে লেলিহান শিখার আগুনে প্রবেশ করবে,"}], "correct": 2}', '{"en": "Surah Al-Masad, ayah 5: around her neck a rope of palm fibre.", "bn": "সূরা আল-মাসাদ, আয়াত ৫: তার গলায় খেজুর-আঁশের পাকানো রশি।"}', 'Quran 111:5', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('999766bf-0cc4-5bd8-ae53-6a31c4da8433', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'choice', '{"en": "Which ayah means: \"His wealth did not help him, nor what he earned.\"", "bn": "কোন আয়াতের অর্থ: \"তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।\""}', '{"options": [{"ar": "تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ"}, {"ar": "سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ"}, {"ar": "وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ"}, {"ar": "مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ"}], "correct": 3}', '{"en": "Surah Al-Masad, ayah 2: His wealth did not help him, nor what he earned.", "bn": "সূরা আল-মাসাদ, আয়াত ২: তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।"}', 'Quran 111:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f04f37a0-9428-51d8-91c6-4409326f2e47', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'true_false', '{"en": "«فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ» means: \"around her neck a rope of palm fibre.\"", "bn": "«فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ» অর্থ: \"তার গলায় খেজুর-আঁশের পাকানো রশি।\""}', '{"answer": true}', '{"en": "Surah Al-Masad, ayah 5: around her neck a rope of palm fibre.", "bn": "সূরা আল-মাসাদ, আয়াত ৫: তার গলায় খেজুর-আঁশের পাকানো রশি।"}', 'Quran 111:5', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f984dd7b-203d-5822-a1f0-a0e678825afc', '5d39d54f-a2f1-54db-a7c3-d4b6a15efe11', 'true_false', '{"en": "«تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ» means: \"His wealth did not help him, nor what he earned.\"", "bn": "«تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ» অর্থ: \"তার সম্পদ ও উপার্জন তার কোনো কাজে আসেনি।\""}', '{"answer": false}', '{"en": "Surah Al-Masad, ayah 1: May the hands of Abu Lahab perish, and perish he has!", "bn": "সূরা আল-মাসাদ, আয়াত ১: আবু লাহাবের দুই হাত ধ্বংস হোক, আর সে নিজেও ধ্বংস হয়েছে!"}', 'Quran 111:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('40328da6-93a0-50f4-a908-ea04e5211f86', 'e9a2d3c2-7314-56f2-b45a-617223bd923b', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ceca74c2-44ff-5d30-a6ac-6207050d843d', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "Which surah has the ayah meaning: \"except those who believe, do righteous deeds, and urge one another to the truth and to patience.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।\""}', '{"options": [{"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "Al-Kafirun", "bn": "আল-কাফিরুন"}, {"en": "An-Nasr", "bn": "আন-নাসর"}, {"en": "Al-‘Asr", "bn": "আল-আসর"}], "correct": 3}', '{"en": "Surah Al-‘Asr, ayah 3: except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "সূরা আল-আসর, আয়াত ৩: তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}', 'Quran 103:3', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c408dbae-0a44-562d-a1ce-2851ca68daef', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "Which surah has the ayah meaning: \"Indeed, it is your enemy who is cut off.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"নিশ্চয় আপনার শত্রুই শিকড়কাটা (নির্বংশ)।\""}', '{"options": [{"en": "Al-‘Asr", "bn": "আল-আসর"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "Al-Kafirun", "bn": "আল-কাফিরুন"}, {"en": "An-Nasr", "bn": "আন-নাসর"}], "correct": 1}', '{"en": "Surah Al-Kawthar, ayah 3: Indeed, it is your enemy who is cut off.", "bn": "সূরা আল-কাওসার, আয়াত ৩: নিশ্চয় আপনার শত্রুই শিকড়কাটা (নির্বংশ)।"}', 'Quran 108:3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a546c709-de84-5cd3-81dc-65e020a40f14', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "Which surah has the ayah meaning: \"For you is your religion, and for me is mine.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।\""}', '{"options": [{"en": "Al-‘Asr", "bn": "আল-আসর"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "An-Nasr", "bn": "আন-নাসর"}, {"en": "Al-Kafirun", "bn": "আল-কাফিরুন"}], "correct": 3}', '{"en": "Surah Al-Kafirun, ayah 6: For you is your religion, and for me is mine.", "bn": "সূরা আল-কাফিরুন, আয়াত ৬: তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।"}', 'Quran 109:6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('61ccaccc-9fd0-5cde-acd5-372427e5b278', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "Which surah has the ayah meaning: \"then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।\""}', '{"options": [{"en": "Al-‘Asr", "bn": "আল-আসর"}, {"en": "An-Nasr", "bn": "আন-নাসর"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "Al-Kafirun", "bn": "আল-কাফিরুন"}], "correct": 1}', '{"en": "Surah An-Nasr, ayah 3: then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "সূরা আন-নাসর, আয়াত ৩: তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}', 'Quran 110:3', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('102af9cb-5f45-5cb5-ba34-f77b7f688f0c', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "Which surah has the ayah meaning: \"around her neck a rope of palm fibre.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"তার গলায় খেজুর-আঁশের পাকানো রশি।\""}', '{"options": [{"en": "Al-‘Asr", "bn": "আল-আসর"}, {"en": "Al-Kawthar", "bn": "আল-কাওসার"}, {"en": "Al-Kafirun", "bn": "আল-কাফিরুন"}, {"en": "Al-Masad", "bn": "আল-মাসাদ"}], "correct": 3}', '{"en": "Surah Al-Masad, ayah 5: around her neck a rope of palm fibre.", "bn": "সূরা আল-মাসাদ, আয়াত ৫: তার গলায় খেজুর-আঁশের পাকানো রশি।"}', 'Quran 111:5', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ff8cb49d-a289-5b6e-928e-9e3e287a8609', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "What does «وَٱلْعَصْرِ» mean?", "bn": "«وَٱلْعَصْرِ» অর্থ কী?"}', '{"options": [{"en": "Indeed, mankind is in loss,", "bn": "নিশ্চয় মানুষ ক্ষতির মধ্যে আছে,"}, {"en": "except those who believe, do righteous deeds, and urge one another to the truth and to patience.", "bn": "তবে তারা নয়, যারা ঈমান আনে, সৎকাজ করে, পরস্পরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}], "correct": 2}', '{"en": "Surah Al-‘Asr, ayah 1: By time!", "bn": "সূরা আল-আসর, আয়াত ১: সময়ের শপথ!"}', 'Quran 103:1', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c411698c-abd5-53d1-95f1-cd8f9c064d89', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "What does «إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ» mean?", "bn": "«إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ» অর্থ কী?"}', '{"options": [{"en": "So pray to your Lord and sacrifice.", "bn": "অতএব আপনার রবের উদ্দেশে নামাজ পড়ুন ও কুরবানি করুন।"}, {"en": "Indeed, We have given you al-Kawthar (abundant good).", "bn": "নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}, {"en": "Indeed, it is your enemy who is cut off.", "bn": "নিশ্চয় আপনার শত্রুই শিকড়কাটা (নির্বংশ)।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}], "correct": 1}', '{"en": "Surah Al-Kawthar, ayah 1: Indeed, We have given you al-Kawthar (abundant good).", "bn": "সূরা আল-কাওসার, আয়াত ১: নিশ্চয় আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।"}', 'Quran 108:1', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a01a96e5-589f-5e07-a4ce-ddb2dab10ca9', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "What does «قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ» mean?", "bn": "«قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ» অর্থ কী?"}', '{"options": [{"en": "Say: O disbelievers,", "bn": "বলুন: হে কাফিররা,"}, {"en": "I do not worship what you worship,", "bn": "আমি তার ইবাদত করি না, যার ইবাদত তোমরা করো,"}, {"en": "nor do you worship what I worship,", "bn": "এবং তোমরাও তাঁর ইবাদতকারী নও, যাঁর ইবাদত আমি করি,"}, {"en": "nor will I worship what you have worshipped,", "bn": "আর আমি তার ইবাদতকারী নই, যার ইবাদত তোমরা করেছ,"}], "correct": 0}', '{"en": "Surah Al-Kafirun, ayah 1: Say: O disbelievers,", "bn": "সূরা আল-কাফিরুন, আয়াত ১: বলুন: হে কাফিররা,"}', 'Quran 109:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('002eb451-7cca-51b6-b967-837b7518a328', '40328da6-93a0-50f4-a908-ea04e5211f86', 'choice', '{"en": "What does «إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ» mean?", "bn": "«إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ» অর্থ কী?"}', '{"options": [{"en": "and you see people entering Allah’s religion in crowds,", "bn": "এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,"}, {"en": "then glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.", "bn": "তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয় তিনি তওবা কবুলকারী।"}, {"en": "By time!", "bn": "সময়ের শপথ!"}, {"en": "When the help of Allah and the victory come,", "bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}], "correct": 3}', '{"en": "Surah An-Nasr, ayah 1: When the help of Allah and the victory come,", "bn": "সূরা আন-নাসর, আয়াত ১: যখন আল্লাহর সাহায্য ও বিজয় আসবে,"}', 'Quran 110:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('8ac57609-8277-56f6-beff-4591276646f6', '{"en": "Meanings: Al-Fil, Quraysh, Al-Ma‘un, At-Takathur & Al-Qadr", "bn": "অর্থ: আল-ফিল, কুরাইশ, আল-মাউন, আত-তাকাসুর ও আল-কদর"}', '{"en": "Five more short surahs often read in salah.", "bn": "নামাজে প্রায়ই পড়া আরও পাঁচটি ছোট সূরা।"}', NULL, 'book-open', 'in_review', 3, (SELECT s.id FROM is_learn_sections s WHERE s.id = 'fd3ba4f3-84f0-51c0-bd1a-fcba486fdfb5')) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('037059c4-b020-5646-aa18-3abeb5712727', '8ac57609-8277-56f6-beff-4591276646f6', '{"en": "Surah Al-Fil: meaning", "bn": "সূরা আল-ফিল: অর্থ"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a3459037-e08d-5a14-a5f8-38f31c8639c8', '037059c4-b020-5646-aa18-3abeb5712727', 'order', '{"en": "Put the meanings of Surah Al-Fil in order", "bn": "সূরা আল-ফিল-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Have you not seen how your Lord dealt with the people of the Elephant?", "bn": "আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সঙ্গে কী করেছিলেন?"}, {"en": "Did He not make their plan go astray?", "bn": "তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?"}, {"en": "And He sent against them birds in flocks,", "bn": "আর তিনি তাদের ওপর ঝাঁকে ঝাঁকে পাখি পাঠালেন,"}, {"en": "striking them with stones of baked clay,", "bn": "যারা তাদের ওপর পোড়া মাটির পাথর নিক্ষেপ করছিল,"}, {"en": "and He made them like eaten straw.", "bn": "অতঃপর তিনি তাদের খাওয়া ভুসির মতো করে দিলেন।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Fil, one after another.", "bn": "সূরা আল-ফিল-এর আয়াতগুলো পরপর।"}', 'Quran 105', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('de8bd73a-b8b2-5a43-8113-32c5e357aad4', '037059c4-b020-5646-aa18-3abeb5712727', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ"}, "right": {"en": "Have you not seen how your Lord dealt with the people of the Elephant?", "bn": "আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সঙ্গে কী করেছিলেন?"}}, {"left": {"ar": "أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ"}, "right": {"en": "Did He not make their plan go astray?", "bn": "তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?"}}, {"left": {"ar": "وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ"}, "right": {"en": "And He sent against them birds in flocks,", "bn": "আর তিনি তাদের ওপর ঝাঁকে ঝাঁকে পাখি পাঠালেন,"}}]}', '{"en": "Surah Al-Fil.", "bn": "সূরা আল-ফিল।"}', 'Quran 105:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5d0230b9-1715-5ebd-9575-f50352b28fab', '037059c4-b020-5646-aa18-3abeb5712727', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ"}, "right": {"en": "striking them with stones of baked clay,", "bn": "যারা তাদের ওপর পোড়া মাটির পাথর নিক্ষেপ করছিল,"}}, {"left": {"ar": "فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ"}, "right": {"en": "and He made them like eaten straw.", "bn": "অতঃপর তিনি তাদের খাওয়া ভুসির মতো করে দিলেন।"}}]}', '{"en": "Surah Al-Fil.", "bn": "সূরা আল-ফিল।"}', 'Quran 105:4–5', 3) ON CONFLICT (id) DO NOTHING;
