INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b46ecbd8-9ce5-55a5-9369-7752116de6e0', '037059c4-b020-5646-aa18-3abeb5712727', 'choice', '{"en": "Which ayah means: \"Did He not make their plan go astray?\"", "bn": "কোন আয়াতের অর্থ: \"তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?\""}', '{"options": [{"ar": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ"}, {"ar": "أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ"}, {"ar": "وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ"}, {"ar": "تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ"}], "correct": 1}', '{"en": "Surah Al-Fil, ayah 2: Did He not make their plan go astray?", "bn": "সূরা আল-ফিল, আয়াত ২: তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?"}', 'Quran 105:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a0b5ba38-a1ea-572b-9a12-9af6c5e4d7b1', '037059c4-b020-5646-aa18-3abeb5712727', 'true_false', '{"en": "«فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ» means: \"and He made them like eaten straw.\"", "bn": "«فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ» অর্থ: \"অতঃপর তিনি তাদের খাওয়া ভুসির মতো করে দিলেন।\""}', '{"answer": true}', '{"en": "Surah Al-Fil, ayah 5: and He made them like eaten straw.", "bn": "সূরা আল-ফিল, আয়াত ৫: অতঃপর তিনি তাদের খাওয়া ভুসির মতো করে দিলেন।"}', 'Quran 105:5', 8) ON CONFLICT (id) DO NOTHING;
