INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e417a018-7110-5ce0-9616-9be0e1929537', '50579104-ce84-5738-aec5-464a29567c4a', 'order', '{"en": "Put the meanings of Surah Quraysh in order", "bn": "সূরা কুরাইশ-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "For the familiar safety of Quraysh —", "bn": "কুরাইশের অভ্যস্ততার কারণে —"}, {"en": "their familiar journeys of winter and summer —", "bn": "শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}, {"en": "let them worship the Lord of this House,", "bn": "তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}, {"en": "who fed them against hunger and made them safe from fear.", "bn": "যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}], "rtl": false}', '{"en": "The ayahs of Surah Quraysh, one after another.", "bn": "সূরা কুরাইশ-এর আয়াতগুলো পরপর।"}', 'Quran 106', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5f64be05-d41e-5072-ac9c-74e5b9da7428', '50579104-ce84-5738-aec5-464a29567c4a', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "لِإِيلَٰفِ قُرَيْشٍ"}, "right": {"en": "For the familiar safety of Quraysh —", "bn": "কুরাইশের অভ্যস্ততার কারণে —"}}, {"left": {"ar": "إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ"}, "right": {"en": "their familiar journeys of winter and summer —", "bn": "শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}}, {"left": {"ar": "فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ"}, "right": {"en": "let them worship the Lord of this House,", "bn": "তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}}, {"left": {"ar": "ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ"}, "right": {"en": "who fed them against hunger and made them safe from fear.", "bn": "যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}}]}', '{"en": "Surah Quraysh.", "bn": "সূরা কুরাইশ।"}', 'Quran 106:1–4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('221c454e-c014-5786-b208-13673839e822', '50579104-ce84-5738-aec5-464a29567c4a', 'choice', '{"en": "What does «لِإِيلَٰفِ قُرَيْشٍ» mean?", "bn": "«لِإِيلَٰفِ قُرَيْشٍ» অর্থ কী?"}', '{"options": [{"en": "their familiar journeys of winter and summer —", "bn": "শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}, {"en": "let them worship the Lord of this House,", "bn": "তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}, {"en": "who fed them against hunger and made them safe from fear.", "bn": "যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}, {"en": "For the familiar safety of Quraysh —", "bn": "কুরাইশের অভ্যস্ততার কারণে —"}], "correct": 3}', '{"en": "Surah Quraysh, ayah 1: For the familiar safety of Quraysh —", "bn": "সূরা কুরাইশ, আয়াত ১: কুরাইশের অভ্যস্ততার কারণে —"}', 'Quran 106:1', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9e7b97a0-9d50-5354-8bbe-99133fc7df9c', '50579104-ce84-5738-aec5-464a29567c4a', 'choice', '{"en": "What does «فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ» mean?", "bn": "«فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ» অর্থ কী?"}', '{"options": [{"en": "For the familiar safety of Quraysh —", "bn": "কুরাইশের অভ্যস্ততার কারণে —"}, {"en": "their familiar journeys of winter and summer —", "bn": "শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}, {"en": "let them worship the Lord of this House,", "bn": "তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}, {"en": "who fed them against hunger and made them safe from fear.", "bn": "যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}], "correct": 2}', '{"en": "Surah Quraysh, ayah 3: let them worship the Lord of this House,", "bn": "সূরা কুরাইশ, আয়াত ৩: তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}', 'Quran 106:3', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4daf4f85-fadc-52eb-81b7-638136da6900', '50579104-ce84-5738-aec5-464a29567c4a', 'choice', '{"en": "What does «ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ» mean?", "bn": "«ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ» অর্থ কী?"}', '{"options": [{"en": "who fed them against hunger and made them safe from fear.", "bn": "যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}, {"en": "For the familiar safety of Quraysh —", "bn": "কুরাইশের অভ্যস্ততার কারণে —"}, {"en": "their familiar journeys of winter and summer —", "bn": "শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}, {"en": "let them worship the Lord of this House,", "bn": "তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}], "correct": 0}', '{"en": "Surah Quraysh, ayah 4: who fed them against hunger and made them safe from fear.", "bn": "সূরা কুরাইশ, আয়াত ৪: যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}', 'Quran 106:4', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0d8bc7f3-cf64-5486-8727-a88632e7e151', '50579104-ce84-5738-aec5-464a29567c4a', 'choice', '{"en": "Which ayah means: \"their familiar journeys of winter and summer —\"", "bn": "কোন আয়াতের অর্থ: \"শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —\""}', '{"options": [{"ar": "لِإِيلَٰفِ قُرَيْشٍ"}, {"ar": "فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ"}, {"ar": "إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ"}, {"ar": "ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ"}], "correct": 2}', '{"en": "Surah Quraysh, ayah 2: their familiar journeys of winter and summer —", "bn": "সূরা কুরাইশ, আয়াত ২: শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}', 'Quran 106:2', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f8c358ac-56e8-5df6-a9cc-7800d9363f78', '50579104-ce84-5738-aec5-464a29567c4a', 'true_false', '{"en": "«ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ» means: \"who fed them against hunger and made them safe from fear.\"", "bn": "«ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ» অর্থ: \"যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।\""}', '{"answer": true}', '{"en": "Surah Quraysh, ayah 4: who fed them against hunger and made them safe from fear.", "bn": "সূরা কুরাইশ, আয়াত ৪: যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}', 'Quran 106:4', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b1aa6354-8c77-521d-94ac-0e8fc5a63108', '50579104-ce84-5738-aec5-464a29567c4a', 'true_false', '{"en": "«لِإِيلَٰفِ قُرَيْشٍ» means: \"their familiar journeys of winter and summer —\"", "bn": "«لِإِيلَٰفِ قُرَيْشٍ» অর্থ: \"শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —\""}', '{"answer": false}', '{"en": "Surah Quraysh, ayah 1: For the familiar safety of Quraysh —", "bn": "সূরা কুরাইশ, আয়াত ১: কুরাইশের অভ্যস্ততার কারণে —"}', 'Quran 106:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('02602c2b-554a-58e7-aa86-b38b4f16b90e', '8ac57609-8277-56f6-beff-4591276646f6', '{"en": "Surah Al-Ma‘un: meaning", "bn": "সূরা আল-মাউন: অর্থ"}', 'lesson', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('60f493e8-7be1-5560-90b3-fffcaa35d54e', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'order', '{"en": "Put the meanings of Surah Al-Ma‘un in order", "bn": "সূরা আল-মাউন-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Have you seen the one who denies the Judgement?", "bn": "আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে?"}, {"en": "That is the one who drives away the orphan,", "bn": "সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,"}, {"en": "and does not urge the feeding of the poor.", "bn": "এবং মিসকিনকে খাবার দিতে উৎসাহ দেয় না।"}, {"en": "So woe to those who pray,", "bn": "অতএব দুর্ভোগ সেই নামাজিদের,"}, {"en": "who are heedless of their prayer,", "bn": "যারা নিজেদের নামাজের ব্যাপারে উদাসীন,"}, {"en": "those who only show off,", "bn": "যারা লোক দেখানোর জন্য আমল করে,"}, {"en": "and withhold small kindnesses.", "bn": "এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Ma‘un, one after another.", "bn": "সূরা আল-মাউন-এর আয়াতগুলো পরপর।"}', 'Quran 107', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9612af9c-4d83-5af6-997d-65bbd481b35f', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ"}, "right": {"en": "Have you seen the one who denies the Judgement?", "bn": "আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে?"}}, {"left": {"ar": "فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ"}, "right": {"en": "That is the one who drives away the orphan,", "bn": "সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,"}}, {"left": {"ar": "وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ"}, "right": {"en": "and does not urge the feeding of the poor.", "bn": "এবং মিসকিনকে খাবার দিতে উৎসাহ দেয় না।"}}, {"left": {"ar": "فَوَيْلٌۭ لِّلْمُصَلِّينَ"}, "right": {"en": "So woe to those who pray,", "bn": "অতএব দুর্ভোগ সেই নামাজিদের,"}}]}', '{"en": "Surah Al-Ma‘un.", "bn": "সূরা আল-মাউন।"}', 'Quran 107:1–4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c00bef75-d391-5d0e-9ce2-e6060fc06ac8', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ"}, "right": {"en": "who are heedless of their prayer,", "bn": "যারা নিজেদের নামাজের ব্যাপারে উদাসীন,"}}, {"left": {"ar": "ٱلَّذِينَ هُمْ يُرَآءُونَ"}, "right": {"en": "those who only show off,", "bn": "যারা লোক দেখানোর জন্য আমল করে,"}}, {"left": {"ar": "وَيَمْنَعُونَ ٱلْمَاعُونَ"}, "right": {"en": "and withhold small kindnesses.", "bn": "এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।"}}]}', '{"en": "Surah Al-Ma‘un.", "bn": "সূরা আল-মাউন।"}', 'Quran 107:5–7', 3) ON CONFLICT (id) DO NOTHING;
