INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1a365cc4-0c3f-51ad-a52c-58caabca50e8', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'choice', '{"en": "What does «وَيَمْنَعُونَ ٱلْمَاعُونَ» mean?", "bn": "«وَيَمْنَعُونَ ٱلْمَاعُونَ» অর্থ কী?"}', '{"options": [{"en": "and withhold small kindnesses.", "bn": "এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।"}, {"en": "Have you seen the one who denies the Judgement?", "bn": "আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে?"}, {"en": "That is the one who drives away the orphan,", "bn": "সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,"}, {"en": "and does not urge the feeding of the poor.", "bn": "এবং মিসকিনকে খাবার দিতে উৎসাহ দেয় না।"}], "correct": 0}', '{"en": "Surah Al-Ma‘un, ayah 7: and withhold small kindnesses.", "bn": "সূরা আল-মাউন, আয়াত ৭: এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।"}', 'Quran 107:7', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d8c89526-0cf4-55e9-84f5-b2e4e9cdd857', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'choice', '{"en": "Which ayah means: \"That is the one who drives away the orphan,\"", "bn": "কোন আয়াতের অর্থ: \"সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,\""}', '{"options": [{"ar": "أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ"}, {"ar": "وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ"}, {"ar": "فَوَيْلٌۭ لِّلْمُصَلِّينَ"}, {"ar": "فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ"}], "correct": 3}', '{"en": "Surah Al-Ma‘un, ayah 2: That is the one who drives away the orphan,", "bn": "সূরা আল-মাউন, আয়াত ২: সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,"}', 'Quran 107:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8b9408ea-758e-565a-9ee9-9da56253689a', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'true_false', '{"en": "«وَيَمْنَعُونَ ٱلْمَاعُونَ» means: \"and withhold small kindnesses.\"", "bn": "«وَيَمْنَعُونَ ٱلْمَاعُونَ» অর্থ: \"এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।\""}', '{"answer": true}', '{"en": "Surah Al-Ma‘un, ayah 7: and withhold small kindnesses.", "bn": "সূরা আল-মাউন, আয়াত ৭: এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।"}', 'Quran 107:7', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('15efc314-5dc3-5a9b-9a6a-4442c7a31695', '02602c2b-554a-58e7-aa86-b38b4f16b90e', 'true_false', '{"en": "«أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ» means: \"That is the one who drives away the orphan,\"", "bn": "«أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ» অর্থ: \"সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,\""}', '{"answer": false}', '{"en": "Surah Al-Ma‘un, ayah 1: Have you seen the one who denies the Judgement?", "bn": "সূরা আল-মাউন, আয়াত ১: আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে?"}', 'Quran 107:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', '8ac57609-8277-56f6-beff-4591276646f6', '{"en": "Surah At-Takathur: meaning", "bn": "সূরা আত-তাকাসুর: অর্থ"}', 'lesson', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('792b8022-9df8-5eab-99b8-fc05f13beca4', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'order', '{"en": "Put the meanings of Surah At-Takathur in order", "bn": "সূরা আত-তাকাসুর-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Competing for more and more distracts you,", "bn": "প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}, {"en": "until you visit the graves.", "bn": "যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}, {"en": "No! You are going to know.", "bn": "কখনো না! শীঘ্রই তোমরা জানবে।"}, {"en": "Then no! You are going to know.", "bn": "আবার বলি, কখনো না! শীঘ্রই তোমরা জানবে।"}, {"en": "No! If only you knew with the knowledge of certainty…", "bn": "কখনো না! যদি তোমরা নিশ্চিত জ্ঞানে জানতে…"}, {"en": "You will surely see the Blazing Fire.", "bn": "তোমরা অবশ্যই জাহান্নাম দেখবে।"}, {"en": "Then you will surely see it with the eye of certainty.", "bn": "তারপর তোমরা তা অবশ্যই নিশ্চিত চোখে দেখবে।"}, {"en": "Then on that Day you will surely be asked about the pleasures (you enjoyed).", "bn": "তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"}], "rtl": false}', '{"en": "The ayahs of Surah At-Takathur, one after another.", "bn": "সূরা আত-তাকাসুর-এর আয়াতগুলো পরপর।"}', 'Quran 102', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ec4aa271-c21b-510c-ae76-0716e66a1bd2', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "أَلْهَىٰكُمُ ٱلتَّكَاثُرُ"}, "right": {"en": "Competing for more and more distracts you,", "bn": "প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}}, {"left": {"ar": "حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ"}, "right": {"en": "until you visit the graves.", "bn": "যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}}, {"left": {"ar": "كَلَّا سَوْفَ تَعْلَمُونَ"}, "right": {"en": "No! You are going to know.", "bn": "কখনো না! শীঘ্রই তোমরা জানবে।"}}, {"left": {"ar": "ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ"}, "right": {"en": "Then no! You are going to know.", "bn": "আবার বলি, কখনো না! শীঘ্রই তোমরা জানবে।"}}]}', '{"en": "Surah At-Takathur.", "bn": "সূরা আত-তাকাসুর।"}', 'Quran 102:1–4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dc786054-f572-595a-90cd-c93dc7f9d9a8', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ"}, "right": {"en": "No! If only you knew with the knowledge of certainty…", "bn": "কখনো না! যদি তোমরা নিশ্চিত জ্ঞানে জানতে…"}}, {"left": {"ar": "لَتَرَوُنَّ ٱلْجَحِيمَ"}, "right": {"en": "You will surely see the Blazing Fire.", "bn": "তোমরা অবশ্যই জাহান্নাম দেখবে।"}}, {"left": {"ar": "ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ"}, "right": {"en": "Then you will surely see it with the eye of certainty.", "bn": "তারপর তোমরা তা অবশ্যই নিশ্চিত চোখে দেখবে।"}}, {"left": {"ar": "ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ"}, "right": {"en": "Then on that Day you will surely be asked about the pleasures (you enjoyed).", "bn": "তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"}}]}', '{"en": "Surah At-Takathur.", "bn": "সূরা আত-তাকাসুর।"}', 'Quran 102:5–8', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('512bcadd-80b8-593a-b73c-ad8f74ed5975', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'choice', '{"en": "What does «أَلْهَىٰكُمُ ٱلتَّكَاثُرُ» mean?", "bn": "«أَلْهَىٰكُمُ ٱلتَّكَاثُرُ» অর্থ কী?"}', '{"options": [{"en": "until you visit the graves.", "bn": "যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}, {"en": "No! You are going to know.", "bn": "কখনো না! শীঘ্রই তোমরা জানবে।"}, {"en": "Then no! You are going to know.", "bn": "আবার বলি, কখনো না! শীঘ্রই তোমরা জানবে।"}, {"en": "Competing for more and more distracts you,", "bn": "প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}], "correct": 3}', '{"en": "Surah At-Takathur, ayah 1: Competing for more and more distracts you,", "bn": "সূরা আত-তাকাসুর, আয়াত ১: প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}', 'Quran 102:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e548cb11-015b-5cb2-9428-31cd18526cdc', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'choice', '{"en": "What does «كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ» mean?", "bn": "«كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ» অর্থ কী?"}', '{"options": [{"en": "No! If only you knew with the knowledge of certainty…", "bn": "কখনো না! যদি তোমরা নিশ্চিত জ্ঞানে জানতে…"}, {"en": "Competing for more and more distracts you,", "bn": "প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}, {"en": "until you visit the graves.", "bn": "যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}, {"en": "No! You are going to know.", "bn": "কখনো না! শীঘ্রই তোমরা জানবে।"}], "correct": 0}', '{"en": "Surah At-Takathur, ayah 5: No! If only you knew with the knowledge of certainty…", "bn": "সূরা আত-তাকাসুর, আয়াত ৫: কখনো না! যদি তোমরা নিশ্চিত জ্ঞানে জানতে…"}', 'Quran 102:5', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('97e08166-4015-5fd8-844f-7f148cb5f462', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'choice', '{"en": "What does «ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ» mean?", "bn": "«ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ» অর্থ কী?"}', '{"options": [{"en": "Then on that Day you will surely be asked about the pleasures (you enjoyed).", "bn": "তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"}, {"en": "Competing for more and more distracts you,", "bn": "প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}, {"en": "until you visit the graves.", "bn": "যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}, {"en": "No! You are going to know.", "bn": "কখনো না! শীঘ্রই তোমরা জানবে।"}], "correct": 0}', '{"en": "Surah At-Takathur, ayah 8: Then on that Day you will surely be asked about the pleasures (you enjoyed).", "bn": "সূরা আত-তাকাসুর, আয়াত ৮: তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"}', 'Quran 102:8', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('989bdab2-f359-5f2e-9506-de2b058134a5', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'choice', '{"en": "Which ayah means: \"until you visit the graves.\"", "bn": "কোন আয়াতের অর্থ: \"যতক্ষণ না তোমরা কবরে পৌঁছে যাও।\""}', '{"options": [{"ar": "أَلْهَىٰكُمُ ٱلتَّكَاثُرُ"}, {"ar": "كَلَّا سَوْفَ تَعْلَمُونَ"}, {"ar": "حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ"}, {"ar": "ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ"}], "correct": 2}', '{"en": "Surah At-Takathur, ayah 2: until you visit the graves.", "bn": "সূরা আত-তাকাসুর, আয়াত ২: যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}', 'Quran 102:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('95e93100-1aeb-535b-b47c-7e823a9f9ab1', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'true_false', '{"en": "«ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ» means: \"Then on that Day you will surely be asked about the pleasures (you enjoyed).\"", "bn": "«ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ» অর্থ: \"তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।\""}', '{"answer": true}', '{"en": "Surah At-Takathur, ayah 8: Then on that Day you will surely be asked about the pleasures (you enjoyed).", "bn": "সূরা আত-তাকাসুর, আয়াত ৮: তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"}', 'Quran 102:8', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('571173ed-75bb-5f0f-8b13-80e3473d2d9d', '6c3ebea5-1c4b-5e8f-9198-fa96e955d6aa', 'true_false', '{"en": "«أَلْهَىٰكُمُ ٱلتَّكَاثُرُ» means: \"until you visit the graves.\"", "bn": "«أَلْهَىٰكُمُ ٱلتَّكَاثُرُ» অর্থ: \"যতক্ষণ না তোমরা কবরে পৌঁছে যাও।\""}', '{"answer": false}', '{"en": "Surah At-Takathur, ayah 1: Competing for more and more distracts you,", "bn": "সূরা আত-তাকাসুর, আয়াত ১: প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}', 'Quran 102:1', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('3439462e-6a3e-5a2b-8d85-d32375a89418', '8ac57609-8277-56f6-beff-4591276646f6', '{"en": "Surah Al-Qadr: meaning", "bn": "সূরা আল-কদর: অর্থ"}', 'lesson', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9dc0ac4c-5086-51f8-9648-6e6f15e57c94', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'order', '{"en": "Put the meanings of Surah Al-Qadr in order", "bn": "সূরা আল-কদর-এর অর্থগুলো ক্রমানুসারে সাজান"}', '{"pieces": [{"en": "Indeed, We sent it (the Quran) down on the Night of Decree.", "bn": "নিশ্চয় আমি এটি (কুরআন) কদরের রাতে নাজিল করেছি।"}, {"en": "And what will make you know what the Night of Decree is?", "bn": "আর আপনি কি জানেন, কদরের রাত কী?"}, {"en": "The Night of Decree is better than a thousand months.", "bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।"}, {"en": "The angels and the Spirit (Jibril) come down in it, by their Lord’s leave, with every matter.", "bn": "সে রাতে ফেরেশতাগণ ও রুহ (জিবরাইল) তাঁদের রবের অনুমতিক্রমে প্রত্যেক বিষয় নিয়ে অবতরণ করেন।"}, {"en": "Peace it is, until the rising of the dawn.", "bn": "শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।"}], "rtl": false}', '{"en": "The ayahs of Surah Al-Qadr, one after another.", "bn": "সূরা আল-কদর-এর আয়াতগুলো পরপর।"}', 'Quran 97', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('46b88fe5-c3d9-51fe-93da-905d4195b665', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ"}, "right": {"en": "Indeed, We sent it (the Quran) down on the Night of Decree.", "bn": "নিশ্চয় আমি এটি (কুরআন) কদরের রাতে নাজিল করেছি।"}}, {"left": {"ar": "وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ"}, "right": {"en": "And what will make you know what the Night of Decree is?", "bn": "আর আপনি কি জানেন, কদরের রাত কী?"}}, {"left": {"ar": "لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ"}, "right": {"en": "The Night of Decree is better than a thousand months.", "bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।"}}]}', '{"en": "Surah Al-Qadr.", "bn": "সূরা আল-কদর।"}', 'Quran 97:1–3', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('aeabaf1e-f477-51a2-8604-1feaea8e29ee', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'match', '{"en": "Match each ayah to its meaning", "bn": "প্রতিটি আয়াতের অর্থ মেলান"}', '{"pairs": [{"left": {"ar": "تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ"}, "right": {"en": "The angels and the Spirit (Jibril) come down in it, by their Lord’s leave, with every matter.", "bn": "সে রাতে ফেরেশতাগণ ও রুহ (জিবরাইল) তাঁদের রবের অনুমতিক্রমে প্রত্যেক বিষয় নিয়ে অবতরণ করেন।"}}, {"left": {"ar": "سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ"}, "right": {"en": "Peace it is, until the rising of the dawn.", "bn": "শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।"}}]}', '{"en": "Surah Al-Qadr.", "bn": "সূরা আল-কদর।"}', 'Quran 97:4–5', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('207fd428-736a-54bc-8de5-35bdea1e0379', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'choice', '{"en": "What does «إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ» mean?", "bn": "«إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ» অর্থ কী?"}', '{"options": [{"en": "And what will make you know what the Night of Decree is?", "bn": "আর আপনি কি জানেন, কদরের রাত কী?"}, {"en": "The Night of Decree is better than a thousand months.", "bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।"}, {"en": "Indeed, We sent it (the Quran) down on the Night of Decree.", "bn": "নিশ্চয় আমি এটি (কুরআন) কদরের রাতে নাজিল করেছি।"}, {"en": "The angels and the Spirit (Jibril) come down in it, by their Lord’s leave, with every matter.", "bn": "সে রাতে ফেরেশতাগণ ও রুহ (জিবরাইল) তাঁদের রবের অনুমতিক্রমে প্রত্যেক বিষয় নিয়ে অবতরণ করেন।"}], "correct": 2}', '{"en": "Surah Al-Qadr, ayah 1: Indeed, We sent it (the Quran) down on the Night of Decree.", "bn": "সূরা আল-কদর, আয়াত ১: নিশ্চয় আমি এটি (কুরআন) কদরের রাতে নাজিল করেছি।"}', 'Quran 97:1', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fcbbb61d-9823-5d9e-b22d-f4df55d71015', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'choice', '{"en": "What does «لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ» mean?", "bn": "«لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ» অর্থ কী?"}', '{"options": [{"en": "Indeed, We sent it (the Quran) down on the Night of Decree.", "bn": "নিশ্চয় আমি এটি (কুরআন) কদরের রাতে নাজিল করেছি।"}, {"en": "The Night of Decree is better than a thousand months.", "bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।"}, {"en": "And what will make you know what the Night of Decree is?", "bn": "আর আপনি কি জানেন, কদরের রাত কী?"}, {"en": "The angels and the Spirit (Jibril) come down in it, by their Lord’s leave, with every matter.", "bn": "সে রাতে ফেরেশতাগণ ও রুহ (জিবরাইল) তাঁদের রবের অনুমতিক্রমে প্রত্যেক বিষয় নিয়ে অবতরণ করেন।"}], "correct": 1}', '{"en": "Surah Al-Qadr, ayah 3: The Night of Decree is better than a thousand months.", "bn": "সূরা আল-কদর, আয়াত ৩: কদরের রাত হাজার মাসের চেয়েও উত্তম।"}', 'Quran 97:3', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9770d555-4045-5fe1-9397-984f520d030b', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'choice', '{"en": "What does «سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ» mean?", "bn": "«سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ» অর্থ কী?"}', '{"options": [{"en": "Peace it is, until the rising of the dawn.", "bn": "শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।"}, {"en": "Indeed, We sent it (the Quran) down on the Night of Decree.", "bn": "নিশ্চয় আমি এটি (কুরআন) কদরের রাতে নাজিল করেছি।"}, {"en": "And what will make you know what the Night of Decree is?", "bn": "আর আপনি কি জানেন, কদরের রাত কী?"}, {"en": "The Night of Decree is better than a thousand months.", "bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।"}], "correct": 0}', '{"en": "Surah Al-Qadr, ayah 5: Peace it is, until the rising of the dawn.", "bn": "সূরা আল-কদর, আয়াত ৫: শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।"}', 'Quran 97:5', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('49e59cff-9a1d-5ee3-84c0-df429f2b81b3', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'choice', '{"en": "Which ayah means: \"And what will make you know what the Night of Decree is?\"", "bn": "কোন আয়াতের অর্থ: \"আর আপনি কি জানেন, কদরের রাত কী?\""}', '{"options": [{"ar": "إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ"}, {"ar": "وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ"}, {"ar": "لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ"}, {"ar": "تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ"}], "correct": 1}', '{"en": "Surah Al-Qadr, ayah 2: And what will make you know what the Night of Decree is?", "bn": "সূরা আল-কদর, আয়াত ২: আর আপনি কি জানেন, কদরের রাত কী?"}', 'Quran 97:2', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('37d32552-d045-5067-87ab-52fe4eb3d016', '3439462e-6a3e-5a2b-8d85-d32375a89418', 'true_false', '{"en": "«سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ» means: \"Peace it is, until the rising of the dawn.\"", "bn": "«سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ» অর্থ: \"শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।\""}', '{"answer": true}', '{"en": "Surah Al-Qadr, ayah 5: Peace it is, until the rising of the dawn.", "bn": "সূরা আল-কদর, আয়াত ৫: শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।"}', 'Quran 97:5', 8) ON CONFLICT (id) DO NOTHING;
