INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d825a566-b35b-56c7-bb8a-96090868e3f0', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "Which surah has the ayah meaning: \"and He made them like eaten straw.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"অতঃপর তিনি তাদের খাওয়া ভুসির মতো করে দিলেন।\""}', '{"options": [{"en": "Quraysh", "bn": "কুরাইশ"}, {"en": "Al-Fil", "bn": "আল-ফিল"}, {"en": "Al-Ma‘un", "bn": "আল-মাউন"}, {"en": "At-Takathur", "bn": "আত-তাকাসুর"}], "correct": 1}', '{"en": "Surah Al-Fil, ayah 5: and He made them like eaten straw.", "bn": "সূরা আল-ফিল, আয়াত ৫: অতঃপর তিনি তাদের খাওয়া ভুসির মতো করে দিলেন।"}', 'Quran 105:5', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bf2ac848-96bd-540e-b6ea-873bcf430cc2', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "Which surah has the ayah meaning: \"who fed them against hunger and made them safe from fear.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।\""}', '{"options": [{"en": "Al-Fil", "bn": "আল-ফিল"}, {"en": "Al-Ma‘un", "bn": "আল-মাউন"}, {"en": "At-Takathur", "bn": "আত-তাকাসুর"}, {"en": "Quraysh", "bn": "কুরাইশ"}], "correct": 3}', '{"en": "Surah Quraysh, ayah 4: who fed them against hunger and made them safe from fear.", "bn": "সূরা কুরাইশ, আয়াত ৪: যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}', 'Quran 106:4', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('32dcc4c9-1d80-5fc1-8a00-9cfd8fd54a79', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "Which surah has the ayah meaning: \"and withhold small kindnesses.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।\""}', '{"options": [{"en": "Al-Fil", "bn": "আল-ফিল"}, {"en": "Al-Ma‘un", "bn": "আল-মাউন"}, {"en": "Quraysh", "bn": "কুরাইশ"}, {"en": "At-Takathur", "bn": "আত-তাকাসুর"}], "correct": 1}', '{"en": "Surah Al-Ma‘un, ayah 7: and withhold small kindnesses.", "bn": "সূরা আল-মাউন, আয়াত ৭: এবং ছোটখাটো সাহায্যের জিনিসও দেয় না।"}', 'Quran 107:7', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('21fc19b7-b012-5f91-91ab-99829529206b', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "Which surah has the ayah meaning: \"Then on that Day you will surely be asked about the pleasures (you enjoyed).\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।\""}', '{"options": [{"en": "Al-Fil", "bn": "আল-ফিল"}, {"en": "At-Takathur", "bn": "আত-তাকাসুর"}, {"en": "Quraysh", "bn": "কুরাইশ"}, {"en": "Al-Ma‘un", "bn": "আল-মাউন"}], "correct": 1}', '{"en": "Surah At-Takathur, ayah 8: Then on that Day you will surely be asked about the pleasures (you enjoyed).", "bn": "সূরা আত-তাকাসুর, আয়াত ৮: তারপর সেদিন তোমাদের অবশ্যই (দুনিয়ার) নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"}', 'Quran 102:8', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a32eda31-e047-597f-bf4d-f33500380e7d', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "Which surah has the ayah meaning: \"Peace it is, until the rising of the dawn.\"", "bn": "কোন সূরায় এই অর্থের আয়াত আছে: \"শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।\""}', '{"options": [{"en": "Al-Fil", "bn": "আল-ফিল"}, {"en": "Al-Qadr", "bn": "আল-কদর"}, {"en": "Quraysh", "bn": "কুরাইশ"}, {"en": "Al-Ma‘un", "bn": "আল-মাউন"}], "correct": 1}', '{"en": "Surah Al-Qadr, ayah 5: Peace it is, until the rising of the dawn.", "bn": "সূরা আল-কদর, আয়াত ৫: শান্তিময় সে রাত, ফজরের উদয় পর্যন্ত।"}', 'Quran 97:5', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9b08413d-dcd1-5497-86c1-b0ed15172af7', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "What does «أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ» mean?", "bn": "«أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ» অর্থ কী?"}', '{"options": [{"en": "Did He not make their plan go astray?", "bn": "তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?"}, {"en": "And He sent against them birds in flocks,", "bn": "আর তিনি তাদের ওপর ঝাঁকে ঝাঁকে পাখি পাঠালেন,"}, {"en": "Have you not seen how your Lord dealt with the people of the Elephant?", "bn": "আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সঙ্গে কী করেছিলেন?"}, {"en": "striking them with stones of baked clay,", "bn": "যারা তাদের ওপর পোড়া মাটির পাথর নিক্ষেপ করছিল,"}], "correct": 2}', '{"en": "Surah Al-Fil, ayah 1: Have you not seen how your Lord dealt with the people of the Elephant?", "bn": "সূরা আল-ফিল, আয়াত ১: আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সঙ্গে কী করেছিলেন?"}', 'Quran 105:1', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bda32a2a-ed74-5579-8bbb-e15c13ba201b', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "What does «لِإِيلَٰفِ قُرَيْشٍ» mean?", "bn": "«لِإِيلَٰفِ قُرَيْشٍ» অর্থ কী?"}', '{"options": [{"en": "their familiar journeys of winter and summer —", "bn": "শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার কারণে —"}, {"en": "For the familiar safety of Quraysh —", "bn": "কুরাইশের অভ্যস্ততার কারণে —"}, {"en": "let them worship the Lord of this House,", "bn": "তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে,"}, {"en": "who fed them against hunger and made them safe from fear.", "bn": "যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।"}], "correct": 1}', '{"en": "Surah Quraysh, ayah 1: For the familiar safety of Quraysh —", "bn": "সূরা কুরাইশ, আয়াত ১: কুরাইশের অভ্যস্ততার কারণে —"}', 'Quran 106:1', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d51aacd2-5aff-58c9-a10d-239e765fa26a', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "What does «أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ» mean?", "bn": "«أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ» অর্থ কী?"}', '{"options": [{"en": "Have you seen the one who denies the Judgement?", "bn": "আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে?"}, {"en": "That is the one who drives away the orphan,", "bn": "সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয়,"}, {"en": "and does not urge the feeding of the poor.", "bn": "এবং মিসকিনকে খাবার দিতে উৎসাহ দেয় না।"}, {"en": "So woe to those who pray,", "bn": "অতএব দুর্ভোগ সেই নামাজিদের,"}], "correct": 0}', '{"en": "Surah Al-Ma‘un, ayah 1: Have you seen the one who denies the Judgement?", "bn": "সূরা আল-মাউন, আয়াত ১: আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে?"}', 'Quran 107:1', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e93f3c0f-5c9e-56ca-a3d1-8c2864f44f5d', 'e467ac6f-6f99-5b20-ad0a-0c1d6713a82c', 'choice', '{"en": "What does «أَلْهَىٰكُمُ ٱلتَّكَاثُرُ» mean?", "bn": "«أَلْهَىٰكُمُ ٱلتَّكَاثُرُ» অর্থ কী?"}', '{"options": [{"en": "until you visit the graves.", "bn": "যতক্ষণ না তোমরা কবরে পৌঁছে যাও।"}, {"en": "No! You are going to know.", "bn": "কখনো না! শীঘ্রই তোমরা জানবে।"}, {"en": "Then no! You are going to know.", "bn": "আবার বলি, কখনো না! শীঘ্রই তোমরা জানবে।"}, {"en": "Competing for more and more distracts you,", "bn": "প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}], "correct": 3}', '{"en": "Surah At-Takathur, ayah 1: Competing for more and more distracts you,", "bn": "সূরা আত-তাকাসুর, আয়াত ১: প্রাচুর্যের প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) ভুলিয়ে রেখেছে,"}', 'Quran 102:1', 9) ON CONFLICT (id) DO NOTHING;
